const cwd = 'C:/Users/mattm/Code/x-mcp';
const child = spawn('node', ['dist/index.js'], { cwd, stdio: ['pipe', 'pipe', 'pipe'] });
let buf = '', errbuf = '', done = false;
const finish = (msg) => { if (done) return; done = true; try { child.kill(); } catch {} console.log(msg); process.exit(0); };
function summarize(m) {
  // CONTENT-SAFE: never print the actual bookmark text/authors.
  try {
    const r = m.result;
    if (m.error) return 'JSONRPC ERROR: ' + JSON.stringify(m.error).slice(0, 300);
    if (r && r.isError) {
      const t = (r.content && r.content[0] && r.content[0].text) || '';
      return 'TOOL ERROR (auth/tier?): ' + t.slice(0, 300);
    }
    const text = r && r.content && r.content[0] && r.content[0].text;
    if (!text) return 'UNEXPECTED: ' + JSON.stringify(r).slice(0, 200);
    let parsed; try { parsed = JSON.parse(text); } catch { return 'NON-JSON RESULT (first 120 chars, may be error): ' + text.slice(0, 120); }
    // dig for an array of bookmarks
    const data = parsed.data && parsed.data.data ? parsed.data.data : (parsed.data || parsed);
    const count = Array.isArray(data) ? data.length : (data && Array.isArray(data.data) ? data.data.length : 'unknown');
    const rl = parsed.rate_limit || (parsed.data && parsed.data.rate_limit) || '';
    return 'SUCCESS: get_bookmarks returned ' + count + ' bookmark(s) [content withheld]. ' + (rl ? 'rate_limit: ' + rl : '');
  } catch (e) { return 'PARSE EXCEPTION: ' + e.message; }
}
child.stdout.on('data', d => {
  buf += d.toString();
  let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i); buf = buf.slice(i + 1);
    if (!line.trim()) continue;
    let m; try { m = JSON.parse(line); } catch { continue; }
    if (m.id === 3) finish(summarize(m));
  }
});
child.stderr.on('data', d => errbuf += d.toString());
child.on('exit', c => finish('child exited (' + c + ') STDERR: ' + errbuf.slice(0, 600)));
const send = o => child.stdin.write(JSON.stringify(o) + '\n');
send({ jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'probe', version: '1.0' } } });
send({ jsonrpc: '2.0', method: 'notifications/initialized' });
send({ jsonrpc: '2.0', id: 3, method: 'tools/call', params: { name: 'get_bookmarks', arguments: { max_results: 10 } } });
setTimeout(() => finish('TIMEOUT (no response in 20s) STDERR: ' + errbuf.slice(0, 600)), 20000);

