1	import crypto from "crypto";
2	import { exec } from "child_process";
3	import http from "http";
4	import fs from "fs";
5	import path from "path";
6	import { fileURLToPath } from "url";
7	
8	const __dirname = path.dirname(fileURLToPath(import.meta.url));
9	const TOKEN_FILE = path.resolve(__dirname, "..", ".oauth2-tokens.json");
10	const AUTH_URL = "https://twitter.com/i/oauth2/authorize";
11	const TOKEN_URL = "https://api.twitter.com/2/oauth2/token";
12	const REDIRECT_URI = "http://127.0.0.1:3219/callback";
13	const SCOPES = "bookmark.read bookmark.write tweet.read users.read offline.access";
14	
15	interface OAuth2Tokens {
16	  access_token: string;
17	  refresh_token: string;
18	  expires_at: number; // unix ms
19	}
20	
21	export class OAuth2Manager {
22	  private tokens: OAuth2Tokens | null = null;
23	  private clientId: string;
24	  private clientSecret: string;
25	
26	  constructor(clientId: string, clientSecret: string) {
27	    this.clientId = clientId;
28	    this.clientSecret = clientSecret;
29	    this.loadTokens();
30	  }
31	
32	  private loadTokens() {
33	    try {
34	      if (fs.existsSync(TOKEN_FILE)) {
35	        const raw = fs.readFileSync(TOKEN_FILE, "utf-8");
36	        this.tokens = JSON.parse(raw);
37	      }
38	    } catch {
39	      this.tokens = null;
40	    }
41	  }
42	
43	  private saveTokens(tokens: OAuth2Tokens) {
44	    this.tokens = tokens;
45	    fs.writeFileSync(TOKEN_FILE, JSON.stringify(tokens, null, 2));
46	  }
47	
48	  get isAuthorized(): boolean {
49	    return this.tokens !== null;
50	  }
51	
52	  async getAccessToken(): Promise<string> {
53	    if (!this.tokens) {
54	      throw new Error(
55	        "OAuth 2.0 not authorized. Run the 'setup_oauth2' tool first to authorize bookmark access.",
56	      );
57	    }
58	
59	    // Refresh if expired or expiring within 60s
60	    if (Date.now() > this.tokens.expires_at - 60_000) {
61	      await this.refreshAccessToken();
62	    }
63	
64	    return this.tokens!.access_token;
65	  }
66	
67	  private async refreshAccessToken() {
68	    if (!this.tokens?.refresh_token) {
69	      throw new Error("No refresh token available. Re-run 'setup_oauth2'.");
70	    }
71	
72	    const body = new URLSearchParams({
73	      grant_type: "refresh_token",
74	      refresh_token: this.tokens.refresh_token,
75	      client_id: this.clientId,
76	    });
77	
78	    const response = await fetch(TOKEN_URL, {
79	      method: "POST",
80	      headers: {
81	        "Content-Type": "application/x-www-form-urlencoded",
82	        Authorization: `Basic ${Buffer.from(`${this.clientId}:${this.clientSecret}`).toString("base64")}`,
83	      },
84	      body: body.toString(),
85	    });
86	
87	    if (!response.ok) {
88	      const text = await response.text();
89	      this.tokens = null;
90	      try { fs.unlinkSync(TOKEN_FILE); } catch {}
91	      throw new Error(
92	        `OAuth 2.0 token refresh failed (HTTP ${response.status}): ${text}. Re-run 'setup_oauth2'.`,
93	      );
94	    }
95	
96	    const data = await response.json() as {
97	      access_token: string;
98	      refresh_token: string;
99	      expires_in: number;
100	    };
101	
102	    this.saveTokens({
103	      access_token: data.access_token,
104	      refresh_token: data.refresh_token,
105	      expires_at: Date.now() + data.expires_in * 1000,
106	    });
107	  }
108	
109	  /**
110	   * Starts the OAuth 2.0 PKCE authorization flow.
111	   * Opens a local HTTP server, returns the URL the user must visit.
112	   * Resolves when the callback is received and tokens are stored.
113	   */
114	  async authorize(): Promise<string> {
115	    const codeVerifier = crypto.randomBytes(32).toString("base64url");
116	    const codeChallenge = crypto
117	      .createHash("sha256")
118	      .update(codeVerifier)
119	      .digest("base64url");
120	    const state = crypto.randomBytes(16).toString("hex");
121	
122	    const authParams = new URLSearchParams({
123	      response_type: "code",
124	      client_id: this.clientId,
125	      redirect_uri: REDIRECT_URI,
126	      scope: SCOPES,
127	      state,
128	      code_challenge: codeChallenge,
129	      code_challenge_method: "S256",
130	    });
131	
132	    const authUrl = `${AUTH_URL}?${authParams}`;
133	
134	    return new Promise<string>((resolve, reject) => {
135	      const server = http.createServer(async (req, res) => {
136	        try {
137	          const url = new URL(req.url!, `http://127.0.0.1:3219`);
138	          if (url.pathname !== "/callback") {
139	            res.writeHead(404);
140	            res.end("Not found");
141	            return;
142	          }
143	
144	          const code = url.searchParams.get("code");
145	          const returnedState = url.searchParams.get("state");
146	
147	          if (!code || returnedState !== state) {
148	            res.writeHead(400);
149	            res.end("Invalid callback: missing code or state mismatch");
150	            server.close();
151	            reject(new Error("OAuth callback failed: state mismatch or missing code"));
152	            return;
153	          }
154	
155	          // Exchange code for tokens
156	          const tokenBody = new URLSearchParams({
157	            grant_type: "authorization_code",
158	            code,
159	            redirect_uri: REDIRECT_URI,
160	            code_verifier: codeVerifier,
161	            client_id: this.clientId,
162	          });
163	
164	          const tokenRes = await fetch(TOKEN_URL, {
165	            method: "POST",
166	            headers: {
167	              "Content-Type": "application/x-www-form-urlencoded",
