1	// harvest-api.mjs — X.com bookmark harvester via direct GraphQL API (no browser).
2	//
3	// Usage:
4	//   node harvest-api.mjs              # harvest up to 1000
5	//   node harvest-api.mjs --max 200    # stop after N bookmarks
6	//
7	// Setup: create .auth.json with { "auth_token": "...", "ct0": "..." }
8	// Get values from Chrome → DevTools → Application → Cookies → .x.com
9	
10	import { mkdirSync, existsSync, readFileSync, appendFileSync } from 'fs';
11	import { join, dirname } from 'path';
12	import { fileURLToPath } from 'url';
13	import { createHash } from 'crypto';
14	
15	const __dirname = dirname(fileURLToPath(import.meta.url));
16	const VAULT_DIR = 'C:\\Users\\mattm\\master-jarvis\\second-brain\\raw\\x-bookmarks';
17	const AUTH_FILE = join(__dirname, '.auth.json');
18	const SEEN_LEDGER = join(VAULT_DIR, '.seen.txt');
19	const REMOVED_LEDGER = join(VAULT_DIR, '.removed.txt');
20	
21	const cliArgs = process.argv.slice(2);
22	const MAX_BOOKMARKS = (() => {
23	  const i = cliArgs.indexOf('--max');
24	  return i !== -1 ? parseInt(cliArgs[i + 1], 10) : 1000;
25	})();
26	
27	mkdirSync(VAULT_DIR, { recursive: true });
28	
29	if (!existsSync(AUTH_FILE)) {
30	  console.error(`AUTH_MISSING: ${AUTH_FILE} not found.`);
31	  console.error('Create it: { "auth_token": "...", "ct0": "..." }');
32	  console.error('Chrome DevTools → Application → Cookies → .x.com');
33	  process.exit(2);
34	}
