36	const authConf = JSON.parse(readFileSync(AUTH_FILE, 'utf-8'));
37	const { auth_token, ct0 } = authConf;
38	const COOKIE_STRING = authConf.cookie_string || `auth_token=${auth_token}; ct0=${ct0}`;
39	if (!auth_token || !ct0) {
40	  console.error('AUTH_INVALID: .auth.json must have auth_token and ct0');
41	  process.exit(2);
42	}
