92	// ---- Helpers ----
93	function isoWeek(date) {
94	  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
95	  const dayNum = d.getUTCDay() || 7;
96	  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
97	  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
98	  const weekNum = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
99	  return `${d.getUTCFullYear()}-W${String(weekNum).padStart(2, '0')}`;
100	}
101	
102	function bookmarkKey(b) {
103	  return createHash('sha1').update(`${b.author}|${b.text.slice(0, 200)}`).digest('hex').slice(0, 16);
104	}
105	
106	function tweetToMd(b) {
107	  const links = (b.links || []).map(l => `- ${l}`).join('\n');
108	  const quote = b.quoteText ? `\n\n> Quote: ${b.quoteText.replace(/\n/g, ' ')}` : '';
109	  const media = b.mediaUrls?.length ? `\n**Media:** ${b.mediaUrls.join(' | ')}` : '';
110	  const engagementParts = [];
111	  if (b.likes != null) engagementParts.push(`likes:${b.likes}`);
112	  if (b.retweets != null) engagementParts.push(`rt:${b.retweets}`);
113	  if (b.views != null) engagementParts.push(`views:${b.views}`);
114	  const engagement = engagementParts.length ? ` | ${engagementParts.join(' ')}` : '';
115	  const followers = b.followers != null ? ` | followers:${b.followers}` : '';
116	  return `## ${b.author}
117	- captured: ${new Date().toISOString()}
118	- time: ${b.time || 'unknown'}
119	- url: ${b.url || 'unknown'}${engagement}${followers}
120	
121	${b.text}${quote}${media}
122	
123	${links ? '**Links:**\n' + links : ''}
124	`;
125	}
126	
127	function parseTweet(itemContent) {
128	  try {
129	    let tweet = itemContent?.tweet_results?.result;
130	    if (!tweet) return null;
131	    // Unwrap TweetWithVisibilityResults envelope
132	    if (tweet.__typename === 'TweetWithVisibilityResults') tweet = tweet.tweet;
133	    if (!tweet) return null;
134	    const userResult = tweet.core?.user_results?.result;
135	    // X.com moved name/screen_name from legacy → core (API change ~2026)
136	    const userIdentity = userResult?.core ?? userResult?.legacy;
137	    const userLegacy = userResult?.legacy;
138	    const legacy = tweet.legacy;
139	    if (!legacy || !userIdentity) return null;
140	    const screenName = userIdentity.screen_name;
141	    const author = `${userIdentity.name} @${screenName}`;
142	    const tweetId = tweet.rest_id || legacy.id_str;
