// harvest-api.mjs — X.com bookmark harvester via direct GraphQL API (no browser).
//
// Usage:
//   node harvest-api.mjs              # harvest up to 1000
//   node harvest-api.mjs --max 200    # stop after N bookmarks
//
// Setup: create .auth.json with { "auth_token": "...", "ct0": "..." }
// Get values from Chrome → DevTools → Application → Cookies → .x.com

import { mkdirSync, existsSync, readFileSync, appendFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { createHash } from 'crypto';

const __dirname = dirname(fileURLToPath(import.meta.url));
const VAULT_DIR = 'C:\\Users\\mattm\\master-jarvis\\second-brain\\raw\\x-bookmarks';
const AUTH_FILE = join(__dirname, '.auth.json');
const SEEN_LEDGER = join(VAULT_DIR, '.seen.txt');
const REMOVED_LEDGER = join(VAULT_DIR, '.removed.txt');

const cliArgs = process.argv.slice(2);
const MAX_BOOKMARKS = (() => {
  const i = cliArgs.indexOf('--max');
  return i !== -1 ? parseInt(cliArgs[i + 1], 10) : 1000;
})();

mkdirSync(VAULT_DIR, { recursive: true });

if (!existsSync(AUTH_FILE)) {
  console.error(`AUTH_MISSING: ${AUTH_FILE} not found.`);
  console.error('Create it: { "auth_token": "...", "ct0": "..." }');
  console.error('Chrome DevTools → Application → Cookies → .x.com');
  process.exit(2);
}

const authConf = JSON.parse(readFileSync(AUTH_FILE, 'utf-8'));
const { auth_token, ct0 } = authConf;
const COOKIE_STRING = authConf.cookie_string || `auth_token=${auth_token}; ct0=${ct0}`;
if (!auth_token || !ct0) {
  console.error('AUTH_INVALID: .auth.json must have auth_token and ct0');
  process.exit(2);
}

// X.com web-app bearer token — static across all web clients since 2015.
const BEARER = 'AAAAAAAAAAAAAAAAAAAAANRILgAAAAAAnNwIzUejRCOuH5E6I8xnZz4puTs%3D1Zv7ttfk8LF81IUq16cHjhLTvJu4FA33AGWWjCpTnA';

// GraphQL operation ID for Bookmarks. If you get 400 errors, find the current ID:
// Chrome DevTools → Network → go to x.com/i/bookmarks → filter "Bookmarks" → copy path segment.
const QUERY_ID = 'kqHFIgP5b-GYJFABN6ARPA';

const FEATURES = {
  rweb_video_screen_enabled: false,
  rweb_cashtags_enabled: true,
  profile_label_improvements_pcf_label_in_post_enabled: true,
  responsive_web_profile_redirect_enabled: false,
  rweb_tipjar_consumption_enabled: false,
  verified_phone_label_enabled: false,
  creator_subscriptions_tweet_preview_api_enabled: true,
  responsive_web_graphql_timeline_navigation_enabled: true,
  responsive_web_graphql_skip_user_profile_image_extensions_enabled: false,
  premium_content_api_read_enabled: false,
  communities_web_enable_tweet_community_results_fetch: true,
  c9s_tweet_anatomy_moderator_badge_enabled: true,
  responsive_web_grok_analyze_button_fetch_trends_enabled: false,
  responsive_web_grok_analyze_post_followups_enabled: true,
  rweb_cashtags_composer_attachment_enabled: true,
  responsive_web_jetfuel_frame: true,
  responsive_web_grok_share_attachment_enabled: true,
  responsive_web_grok_annotations_enabled: true,
  articles_preview_enabled: true,
  responsive_web_edit_tweet_api_enabled: true,
  graphql_is_translatable_rweb_tweet_is_translatable_enabled: true,
  view_counts_everywhere_api_enabled: true,
  longform_notetweets_consumption_enabled: true,
  responsive_web_twitter_article_tweet_consumption_enabled: true,
  content_disclosure_indicator_enabled: true,
  content_disclosure_ai_generated_indicator_enabled: true,
  responsive_web_grok_show_grok_translated_post: true,
  responsive_web_grok_analysis_button_from_backend: true,
  post_ctas_fetch_enabled: true,
  freedom_of_speech_not_reach_fetch_enabled: true,
  standardized_nudges_misinfo: true,
  tweet_with_visibility_results_prefer_gql_limited_actions_policy_enabled: true,
  longform_notetweets_rich_text_read_enabled: true,
  longform_notetweets_inline_media_enabled: false,
  responsive_web_grok_image_annotation_enabled: true,
  responsive_web_grok_imagine_annotation_enabled: true,
  responsive_web_grok_community_note_auto_translation_is_enabled: true,
  responsive_web_enhance_cards_enabled: false,
};

// ---- Helpers ----
function isoWeek(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const weekNum = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
  return `${d.getUTCFullYear()}-W${String(weekNum).padStart(2, '0')}`;
}

function bookmarkKey(b) {
  return createHash('sha1').update(`${b.author}|${b.text.slice(0, 200)}`).digest('hex').slice(0, 16);
}

function tweetToMd(b) {
  const links = (b.links || []).map(l => `- ${l}`).join('\n');
  const quote = b.quoteText ? `\n\n> Quote: ${b.quoteText.replace(/\n/g, ' ')}` : '';
  const media = b.mediaUrls?.length ? `\n**Media:** ${b.mediaUrls.join(' | ')}` : '';
  const engagementParts = [];
  if (b.likes != null) engagementParts.push(`likes:${b.likes}`);
  if (b.retweets != null) engagementParts.push(`rt:${b.retweets}`);
  if (b.views != null) engagementParts.push(`views:${b.views}`);
  const engagement = engagementParts.length ? ` | ${engagementParts.join(' ')}` : '';
  const followers = b.followers != null ? ` | followers:${b.followers}` : '';
  return `## ${b.author}
- captured: ${new Date().toISOString()}
- time: ${b.time || 'unknown'}
- url: ${b.url || 'unknown'}${engagement}${followers}

${b.text}${quote}${media}

${links ? '**Links:**\n' + links : ''}
`;
}

function parseTweet(itemContent) {
  try {
    let tweet = itemContent?.tweet_results?.result;
    if (!tweet) return null;
    // Unwrap TweetWithVisibilityResults envelope
    if (tweet.__typename === 'TweetWithVisibilityResults') tweet = tweet.tweet;
    if (!tweet) return null;
    const userResult = tweet.core?.user_results?.result;
    // X.com moved name/screen_name from legacy → core (API change ~2026)
    const userIdentity = userResult?.core ?? userResult?.legacy;
    const userLegacy = userResult?.legacy;
    const legacy = tweet.legacy;
    if (!legacy || !userIdentity) return null;
    const screenName = userIdentity.screen_name;
    const author = `${userIdentity.name} @${screenName}`;
    const tweetId = tweet.rest_id || legacy.id_str;
    const url = tweetId && screenName ? `https://x.com/${screenName}/status/${tweetId}` : null;
    const text = (legacy.full_text || tweet.note_tweet?.note_tweet_results?.result?.text || '')
      .replace(/https:\/\/t\.co\/\S+/g, '').trim();
    const time = legacy.created_at || '';
    const links = (legacy.entities?.urls || [])
      .map(u => u.expanded_url)
      .filter(u => u && !u.includes('t.co') && !u.includes('twitter.com') && !u.includes('x.com'));
    const quoteText = tweet.quoted_status_result?.result?.legacy?.full_text
      || tweet.quoted_status_result?.result?.tweet?.legacy?.full_text || '';
    const mediaUrls = (legacy.entities?.media || legacy.extended_entities?.media || [])
      .map(m => m.media_url_https).filter(Boolean);
    const likes = legacy.favorite_count ?? null;
    const retweets = legacy.retweet_count ?? null;
    const views = parseInt(tweet.views?.count, 10) || null;
    const followers = userLegacy?.followers_count ?? null;
    return { author, text, time, url, tweetId, links, quoteText, mediaUrls, likes, retweets, views, followers };
  } catch {
    return null;
  }
}

async function fetchPage(cursor) {
  const variables = JSON.stringify({ count: 20, ...(cursor ? { cursor } : {}), includePromotedContent: false });
  const url = `https://x.com/i/api/graphql/${QUERY_ID}/Bookmarks` +
    `?variables=${encodeURIComponent(variables)}&features=${encodeURIComponent(JSON.stringify(FEATURES))}`;

  const resp = await fetch(url, {
    headers: {
      'Authorization': `Bearer ${BEARER}`,
      'Cookie': COOKIE_STRING,
      'x-csrf-token': ct0,
      'x-twitter-active-user': 'yes',
      'x-twitter-auth-type': 'OAuth2Session',
      'x-twitter-client-language': 'en',
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/136.0.0.0 Safari/537.36',
      'Referer': 'https://x.com/i/bookmarks',
      'Accept': '*/*',
    },
  });

  if (resp.status === 401 || resp.status === 403) {
    throw new Error(`AUTH_EXPIRED (${resp.status}): refresh auth_token and ct0 in .auth.json`);
  }
  if (resp.status === 400 || resp.status === 404) {
    const body = await resp.text();
    if (body.includes('"query"') || body.includes('query not found') || resp.status === 404) {
      console.error(`QUERY_ID_STALE: update QUERY_ID in harvest-api.mjs — see raw/x-bookmarks/AUTH-REFRESH.md §Section 2`);
      process.exit(3);
    }
    throw new Error(`HTTP ${resp.status}: ${body.slice(0, 400)}`);
  }
  if (!resp.ok) {
    const body = await resp.text();
    throw new Error(`HTTP ${resp.status}: ${body.slice(0, 400)}`);
  }
  return resp.json();
}

// Retry fetchPage up to maxRetries times when timeline is missing (transient X.com hiccup).
async function fetchTimeline(cursor, maxRetries = 3) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const data = await fetchPage(cursor);
    const timeline = data?.data?.bookmark_timeline_v2?.timeline;
    if (timeline) return timeline;
    if (attempt < maxRetries) {
      const delay = 5000 * attempt;
      console.error(`\nTransient null timeline (attempt ${attempt}/${maxRetries}), retrying in ${delay / 1000}s...`);
      console.error('Response:', JSON.stringify(data).slice(0, 200));
      await new Promise(r => setTimeout(r, delay));
    } else {
      console.error('\nUnexpected response after retries — auth may be expired or QUERY_ID changed.');
      console.error('Response:', JSON.stringify(data).slice(0, 500));
      process.exit(1);
    }
  }
}

// ---- Main ----
async function run() {
  const seen = new Set();
  if (existsSync(SEEN_LEDGER)) {
    for (const line of readFileSync(SEEN_LEDGER, 'utf-8').split('\n')) {
      if (line.trim()) seen.add(line.trim());
    }
  }

  const collected = new Map();
  let cursor = null;
  let page = 0;

  while (collected.size < MAX_BOOKMARKS) {
    page++;
    process.stderr.write(`\rPage ${page} — ${collected.size} collected...`);

    const timeline = await fetchTimeline(cursor);

    let nextCursor = null;
    let pageHits = 0;

    for (const inst of (timeline.instructions || [])) {
      for (const entry of (inst.entries || [])) {
        if (entry.entryId?.startsWith('cursor-bottom')) {
          nextCursor = entry.content?.value;
          continue;
        }
        const tweet = parseTweet(entry.content?.itemContent);
        if (tweet) {
          const key = bookmarkKey(tweet);
          if (!collected.has(key)) { collected.set(key, tweet); pageHits++; }
        }
      }
    }

    if (pageHits === 0 || !nextCursor) break;
    cursor = nextCursor;
    await new Promise(r => setTimeout(r, 400));
  }

  process.stderr.write('\n');
  console.log(`Harvested ${collected.size} unique bookmarks via API.`);
  const fullHarvest = collected.size < MAX_BOOKMARKS;

  // Delete tracking
  let removedCount = 0;
  if (fullHarvest && seen.size > 0) {
    const currentKeys = new Set(collected.keys());
    const previouslyRemoved = new Set();
    if (existsSync(REMOVED_LEDGER)) {
      for (const line of readFileSync(REMOVED_LEDGER, 'utf-8').split('\n')) {
        if (line.trim()) previouslyRemoved.add(line.trim());
      }
    }
    const newlyRemoved = [...seen].filter(k => !currentKeys.has(k) && !previouslyRemoved.has(k));
    if (newlyRemoved.length > 0) {
      appendFileSync(REMOVED_LEDGER, newlyRemoved.map(k => `${k} ${new Date().toISOString()}`).join('\n') + '\n', 'utf-8');
      removedCount = newlyRemoved.length;
      console.log(`${removedCount} bookmark(s) removed from X.com since last run.`);
    }
  }

  const newBookmarks = [...collected.entries()].filter(([k]) => !seen.has(k));
  console.log(`${newBookmarks.length} new (after dedupe).`);

  if (newBookmarks.length === 0) {
    return { harvested: collected.size, written: 0, removed: removedCount };
  }

  const week = isoWeek(new Date());
  const file = join(VAULT_DIR, `${week}.md`);
  const fileExists = existsSync(file);
  const blocks = newBookmarks.map(([, b]) => tweetToMd(b)).join('\n---\n\n');
  const header = fileExists ? '\n---\n\n' : `# X Bookmarks — ${week}\n\nharvested ${new Date().toISOString()}\n\n`;
  appendFileSync(file, header + blocks, 'utf-8');
  appendFileSync(SEEN_LEDGER, newBookmarks.map(([k]) => k).join('\n') + '\n', 'utf-8');

  const jsonlFile = join(VAULT_DIR, `${week}.jsonl`);
  const jsonlLines = newBookmarks.map(([k, b]) => JSON.stringify({
    key: k,
    author: b.author,
    handle: (b.author.match(/@(\S+)/) || [])[1] || '',
    tweetId: b.tweetId || null,
    url: b.url || null,
    time: b.time || null,
    text: b.text,
    links: b.links || [],
    quoteText: b.quoteText || '',
    mediaUrls: b.mediaUrls || [],
    likes: b.likes ?? null,
    retweets: b.retweets ?? null,
    views: b.views ?? null,
    followers: b.followers ?? null,
  })).join('\n');
  appendFileSync(jsonlFile, jsonlLines + '\n', 'utf-8');

  return { harvested: collected.size, written: newBookmarks.length, removed: removedCount, file, jsonlFile };
}

run().then(r => {
  const removedStr = r.removed ? ` removed=${r.removed}` : '';
  console.log(`DONE harvested=${r.harvested} written=${r.written}${removedStr}${r.file ? ` file=${r.file}` : ''}`);
  process.exit(0);
}).catch(e => {
  console.error('ERROR:', e.message);
  process.exit(1);
});

