const SRC = 'C:/Users/mattm/twitter_access.txt';
const OUT = 'C:/Users/mattm/Code/x-mcp/.oauth2-tokens.json';
const raw = readFileSync(SRC, 'utf-8');
const grab = (re) => { const m = raw.match(re); return m ? m[1].trim() : null; };
// Tolerant of the file's spellings ("Outh 2", "Oautho 2")
const access = grab(/O?uth?o?\s*2\s*access token:\s*(.+)/i);
const refresh = grab(/O?auth?o?\s*2\s*refresh token:\s*(.+)/i);
