const tokens = { access_token: access, refresh_token: refresh, expires_at: Date.now() + 3600 * 1000 };
writeFileSync(OUT, JSON.stringify(tokens, null, 2));
console.log('Wrote .oauth2-tokens.json  (access len=' + access.length + ', refresh len=' + refresh.length + ', no values printed)');

