  const screenName = u.username || '';
  const author = `${u.name || ''} @${screenName}`.trim();
  const text = (t.note_tweet?.text || t.text || '').replace(/https:\/\/t\.co\/\S+/g, '').trim();
  const url = (t.id && screenName) ? `https://x.com/${screenName}/status/${t.id}` : null;
  const links = (t.entities?.urls || [])
    .map(x => x.expanded_url)
    .filter(x => x && !x.includes('t.co') && !x.includes('twitter.com') && !x.includes('x.com'));
  let quoteText = '';
  for (const ref of (t.referenced_tweets || [])) {
    if (ref.type === 'quoted' && tweetsById[ref.id]) { quoteText = tweetsById[ref.id].text || ''; break; }
  }
  const mediaUrls = (t.attachments?.media_keys || [])
    .map(k => mediaByKey[k]).filter(Boolean)
    .map(m => m.url || m.preview_image_url).filter(Boolean);
  const pm = t.public_metrics || {};
  return {
    author, text, time: t.created_at || '', url, tweetId: t.id, links, quoteText, mediaUrls,
    likes: pm.like_count ?? null, retweets: pm.retweet_count ?? null,
    views: pm.impression_count ?? null, followers: u.public_metrics?.followers_count ?? null,
  };
}

// ---- minimal MCP stdio client: paginate get_bookmarks ----
function harvestViaMcp(maxTotal) {
  return new Promise((resolve, reject) => {
    const child = spawn('node', [MCP_ENTRY], { stdio: ['pipe', 'pipe', 'pipe'] });
    let buf = '', errbuf = '', nextId = 1, settled = false;
    const pending = new Map();
    const out = [];
    let token;
    const send = o => child.stdin.write(JSON.stringify(o) + '\n');
    const callTool = (name, args) => new Promise((res, rej) => {
      const id = ++nextId; pending.set(id, { res, rej });
      send({ jsonrpc: '2.0', id, method: 'tools/call', params: { name, arguments: args } });
    });
    const fail = (e) => { if (settled) return; settled = true; try { child.kill(); } catch {} reject(e instanceof Error ? e : new Error(String(e))); };
    const done = () => { if (settled) return; settled = true; try { child.kill(); } catch {} resolve(out); };

    child.stderr.on('data', d => { errbuf += d.toString(); });
    child.on('exit', () => { if (!settled) fail(new Error('MCP exited early. stderr: ' + errbuf.slice(0, 300))); });
    child.stdout.on('data', d => {
      buf += d.toString();
      let i;
      while ((i = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, i); buf = buf.slice(i + 1);
        if (!line.trim()) continue;
        let m; try { m = JSON.parse(line); } catch { continue; }
        if (m.id === 1) { send({ jsonrpc: '2.0', method: 'notifications/initialized' }); driver().catch(fail); }
        else if (pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); p.res(m); }
      }
    });

    async function driver() {
      while (out.length < maxTotal) {
        const want = Math.min(100, maxTotal - out.length);
        const m = await callTool('get_bookmarks', token ? { max_results: want, next_token: token } : { max_results: want });
        const r = m.result;
        if (!r || r.isError) throw new Error('get_bookmarks tool error: ' + JSON.stringify(r).slice(0, 300));
        const text = r.content?.[0]?.text;
        if (!text) throw new Error('get_bookmarks: empty content');
        const parsed = JSON.parse(text);
        const payload = parsed.data || parsed;            // { data:[...], includes:{...}, meta:{...} }
        const tweets = payload.data || [];
        const inc = payload.includes || {};
        const usersById = Object.fromEntries((inc.users || []).map(u => [u.id, u]));
        const mediaByKey = Object.fromEntries((inc.media || []).map(mm => [mm.media_key, mm]));
        const tweetsById = Object.fromEntries((inc.tweets || []).map(tt => [tt.id, tt]));
        for (const t of tweets) out.push(mapTweet(t, usersById, mediaByKey, tweetsById));
        process.stderr.write(`\rFetched ${out.length}...`);
        token = payload.meta?.next_token;
        if (!token || tweets.length === 0) break;
      }
      process.stderr.write('\n');
      done();
    }

    send({ jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'harvest-mcp', version: '1.0' } } });
    setTimeout(() => fail(new Error('MCP harvest timed out (120s). stderr: ' + errbuf.slice(0, 200))), 120000);
  });
}

// ---- main: dedup + write + ledgers (mirror harvest-api.mjs run()) ----
async function run() {
  const seen = new Set();
  if (existsSync(SEEN_LEDGER)) {
    for (const line of readFileSync(SEEN_LEDGER, 'utf-8').split('\n')) {
      if (line.trim()) seen.add(line.trim());
    }
  }

  const harvested = await harvestViaMcp(MAX_BOOKMARKS);
  const collected = new Map();
  for (const b of harvested) {
    const key = bookmarkKey(b);
    if (!collected.has(key)) collected.set(key, b);
  }
  console.log(`Harvested ${collected.size} unique bookmarks via MCP get_bookmarks.`);
  const fullHarvest = collected.size < MAX_BOOKMARKS;

  // Delete tracking (only trust removals on a full harvest)
  let removedCount = 0;
  if (fullHarvest && seen.size > 0) {
    const currentKeys = new Set(collected.keys());
    const previouslyRemoved = new Set();
    if (existsSync(REMOVED_LEDGER)) {
      for (const line of readFileSync(REMOVED_LEDGER, 'utf-8').split('\n')) {
        if (line.trim()) previouslyRemoved.add(line.trim());
      }
    }
    const newlyRemoved = [...seen].filter(k => !currentKeys.has(k) && !previouslyRemoved.has(k));
    if (newlyRemoved.length > 0) {
      appendFileSync(REMOVED_LEDGER, newlyRemoved.map(k => `${k} ${new Date().toISOString()}`).join('\n') + '\n', 'utf-8');
      removedCount = newlyRemoved.length;
      console.log(`${removedCount} bookmark(s) removed from X.com since last run.`);
    }
  }

  const newBookmarks = [...collected.entries()].filter(([k]) => !seen.has(k));
  console.log(`${newBookmarks.length} new (after dedupe).`);

  if (newBookmarks.length === 0) {
    return { harvested: collected.size, written: 0, removed: removedCount };
  }

  const week = isoWeek(new Date());
  const file = join(VAULT_DIR, `${week}.md`);
  const fileExists = existsSync(file);
  const blocks = newBookmarks.map(([, b]) => tweetToMd(b)).join('\n---\n\n');
  const header = fileExists ? '\n---\n\n' : `# X Bookmarks — ${week}\n\nharvested ${new Date().toISOString()}\n\n`;
  appendFileSync(file, header + blocks, 'utf-8');
  appendFileSync(SEEN_LEDGER, newBookmarks.map(([k]) => k).join('\n') + '\n', 'utf-8');

  const jsonlFile = join(VAULT_DIR, `${week}.jsonl`);
  const jsonlLines = newBookmarks.map(([k, b]) => JSON.stringify({
    key: k, author: b.author, handle: (b.author.match(/@(\S+)/) || [])[1] || '',
    tweetId: b.tweetId || null, url: b.url || null, time: b.time || null, text: b.text,
    links: b.links || [], quoteText: b.quoteText || '', mediaUrls: b.mediaUrls || [],
    likes: b.likes ?? null, retweets: b.retweets ?? null, views: b.views ?? null, followers: b.followers ?? null,
  })).join('\n');
  appendFileSync(jsonlFile, jsonlLines + '\n', 'utf-8');

  return { harvested: collected.size, written: newBookmarks.length, removed: removedCount, file, jsonlFile };
}

run().then(r => {
  const removedStr = r.removed ? ` removed=${r.removed}` : '';
  console.log(`DONE harvested=${r.harvested} written=${r.written}${removedStr}${r.file ? ` file=${r.file}` : ''}`);
  process.exit(0);
}).catch(e => {
  console.error('ERROR:', e.message);
  process.exit(1);
});

