import { readFileSync } from 'fs';
import { execFileSync } from 'child_process';
const raw = readFileSync('C:/Users/mattm/twitter_access.txt', 'utf-8');
const m = raw.match(/Client ID:\s*(.+)/i);
if (!m) { console.error('no Client ID line found'); process.exit(1); }
const id = m[1].trim();
// stdout ignored so op's item echo (which includes field values) never prints.
execFileSync('op', ['item', 'edit', 'X-API', '--vault', 'Amo Personal', `oauth2_client_id[password]=${id}`], { stdio: ['ignore', 'ignore', 'inherit'] });
console.log('Added oauth2_client_id to 1P X-API (value len=' + id.length + ', not printed)');

import { readFileSync, writeFileSync } from 'fs';
const SRC = 'C:/Users/mattm/twitter_access.txt';
const OUT = 'C:/Users/mattm/Code/x-mcp/.oauth2-tokens.json';
const raw = readFileSync(SRC, 'utf-8');
const grab = (re) => { const m = raw.match(re); return m ? m[1].trim() : null; };
// Tolerant of the file's spellings ("Outh 2", "Oautho 2")
const access = grab(/O?uth?o?\s*2\s*access token:\s*(.+)/i);
const refresh = grab(/O?auth?o?\s*2\s*refresh token:\s*(.+)/i);
if (!access || !refresh) {
  console.error('PARSE FAIL — access:' + !!access + ' refresh:' + !!refresh);
  process.exit(1);
}
// Conservatively mark valid for 1h so the manager uses it directly (no refresh attempt yet).
const tokens = { access_token: access, refresh_token: refresh, expires_at: Date.now() + 3600 * 1000 };
writeFileSync(OUT, JSON.stringify(tokens, null, 2));
console.log('Wrote .oauth2-tokens.json  (access len=' + access.length + ', refresh len=' + refresh.length + ', no values printed)');

