// Offline fixture test for harvest-mcp.mjs — validates v2 JSON -> normalized -> md/jsonl
// without a live token. Sets a scratch VAULT_DIR before import (module mkdir's it at load).
import { mkdtempSync, readFileSync, existsSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';

const scratch = mkdtempSync(join(tmpdir(), 'bm-fixture-'));
process.env.X_BM_VAULT_DIR = scratch;

const mod = await import('file:///C:/Users/mattm/master-jarvis/scripts/ingest/x-bookmarks/harvest-mcp.mjs');
const { mapTweet, bookmarkKey, tweetToMd, run } = mod;

let pass = 0, fail = 0;
const ok = (cond, msg) => { if (cond) { pass++; } else { fail++; console.log('  FAIL:', msg); } };

// --- representative get_bookmarks v2 payload ---
const includes = {
  users: [
    { id: 'u1', name: 'Jane Trader', username: 'janetrader', verified: true, public_metrics: { followers_count: 12345 } },
    { id: 'u2', name: 'Quoted Quinn', username: 'quotedquinn', public_metrics: { followers_count: 50 } },
  ],
  media: [
    { media_key: 'm1', type: 'photo', url: 'https://pbs.twimg.com/media/photo1.jpg' },
    { media_key: 'm2', type: 'video', preview_image_url: 'https://pbs.twimg.com/preview2.jpg' },
  ],
  tweets: [
    { id: 'q1', text: 'This is the quoted tweet body.' },
  ],
};
const usersById = Object.fromEntries(includes.users.map(u => [u.id, u]));
const mediaByKey = Object.fromEntries(includes.media.map(m => [m.media_key, m]));
const tweetsById = Object.fromEntries(includes.tweets.map(t => [t.id, t]));

// Tweet A: long note_tweet, links, media, quote, full metrics
const tA = {
  id: '111', author_id: 'u1', created_at: '2026-06-30T10:00:00.000Z',
  text: 'short visible text https://t.co/abc',
  note_tweet: { text: 'FULL long-form note tweet text that should win over the truncated text https://t.co/abc' },
  entities: { urls: [
    { expanded_url: 'https://example.com/research-paper' },
    { expanded_url: 'https://t.co/abc' },                       // t.co -> filtered
    { expanded_url: 'https://twitter.com/janetrader/status/111' }, // self -> filtered
  ]},
  referenced_tweets: [{ type: 'quoted', id: 'q1' }],
  attachments: { media_keys: ['m1', 'm2'] },
  public_metrics: { like_count: 42, retweet_count: 7, impression_count: 9001 },
};
// Tweet B: minimal — no note_tweet, no media, no quote, no entities
const tB = {
  id: '222', author_id: 'u2', created_at: '2026-06-29T08:30:00.000Z',
  text: 'plain bookmark with no extras',
  public_metrics: { like_count: 1, retweet_count: 0, impression_count: 100 },
};

const a = mapTweet(tA, usersById, mediaByKey, tweetsById);
const b = mapTweet(tB, usersById, mediaByKey, tweetsById);

console.log('--- mapTweet(A) ---');
ok(a.author === 'Jane Trader @janetrader', `author got "${a.author}"`);
ok(a.text.startsWith('FULL long-form note tweet'), 'note_tweet wins over text');
ok(!a.text.includes('t.co'), 't.co stripped from text');
ok(a.url === 'https://x.com/janetrader/status/111', `url got "${a.url}"`);
ok(a.tweetId === '111', 'tweetId');
ok(a.links.length === 1 && a.links[0] === 'https://example.com/research-paper', `links got ${JSON.stringify(a.links)}`);
ok(a.quoteText === 'This is the quoted tweet body.', `quoteText got "${a.quoteText}"`);
ok(a.mediaUrls.length === 2 && a.mediaUrls[0].includes('photo1') && a.mediaUrls[1].includes('preview2'), `mediaUrls got ${JSON.stringify(a.mediaUrls)}`);
ok(a.likes === 42 && a.retweets === 7 && a.views === 9001, 'metrics');
ok(a.followers === 12345, `followers got ${a.followers}`);

console.log('--- mapTweet(B) minimal ---');
ok(b.author === 'Quoted Quinn @quotedquinn', `author got "${b.author}"`);
ok(b.links.length === 0 && b.mediaUrls.length === 0 && b.quoteText === '', 'empty extras safe');
ok(b.url === 'https://x.com/quotedquinn/status/222', 'url');

console.log('--- bookmarkKey stable & 16 hex ---');
const k = bookmarkKey(a);
ok(/^[0-9a-f]{16}$/.test(k), `key shape ${k}`);
ok(bookmarkKey(a) === k, 'key deterministic');

console.log('--- tweetToMd(A) ---');
const md = tweetToMd(a);
ok(md.startsWith('## Jane Trader @janetrader'), 'md header');
ok(md.includes('likes:42 rt:7 views:9001'), 'md engagement line');
ok(md.includes('followers:12345'), 'md followers');
ok(md.includes('> Quote: This is the quoted tweet body.'), 'md quote');
ok(md.includes('**Media:**') && md.includes('photo1.jpg'), 'md media');
ok(md.includes('**Links:**') && md.includes('- https://example.com/research-paper'), 'md links');

// --- full pipeline via injected fetcher (writes to scratch) ---
console.log('--- run() full write pipeline (injected fetcher) ---');
const r1 = await run(async () => [a, b]);
ok(r1.harvested === 2 && r1.written === 2, `first run harvested=${r1.harvested} written=${r1.written}`);
const wk = /(\d{4}-W\d{2})\.md$/.exec(r1.file)?.[1];
ok(!!wk, `week file ${r1.file}`);
const mdFile = readFileSync(r1.file, 'utf-8');
ok(mdFile.includes('Jane Trader') && mdFile.includes('Quoted Quinn'), 'both written to md');
const jsonl = readFileSync(join(scratch, `${wk}.jsonl`), 'utf-8').trim().split('\n');
ok(jsonl.length === 2, `jsonl lines ${jsonl.length}`);
const j0 = JSON.parse(jsonl[0]);
ok(j0.handle === 'janetrader' && j0.tweetId === '111' && j0.views === 9001, 'jsonl fields');
ok(existsSync(join(scratch, '.seen.txt')), '.seen.txt created');

// --- idempotency: re-run same set => 0 new ---
console.log('--- run() idempotency (dedup vs .seen) ---');
const r2 = await run(async () => [a, b]);
ok(r2.written === 0, `second run written=${r2.written} (expected 0)`);

console.log(`\nRESULT: ${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

