$t = Get-ScheduledTask | Where-Object { $_.TaskName -like '*XBookmark*' -or $_.TaskName -like '*Bookmark*' -or $_.TaskName -like '*VaultIngest*' }
foreach ($x in $t) {
  Write-Output "TASK: $($x.TaskName)  [$($x.State)]"
  foreach ($a in $x.Actions) { Write-Output "  EXEC: $($a.Execute) $($a.Arguments)"; if ($a.WorkingDirectory) { Write-Output "  CWD:  $($a.WorkingDirectory)" } }
}

