1	# x-bookmarks-export.ps1
2	# Wrapper for the X.com bookmark harvester + AI analysis pass.
3	# Schedule via: Jarvis-VaultIngest-XBookmarks (daily 06:00 CT).
4	#
5	# Uses direct GraphQL API -- no browser, no login prompts.
6	# Auth: update .auth.json with fresh auth_token/ct0/cookie_string from Chrome DevTools.
7	#
8	# Pipeline:
9	#   1. harvest-api.mjs -- calls X.com GraphQL directly, writes YYYY-WW.md (deduped)
10	#   2. analyze.mjs     -- enriches new tweet blocks with AI frontmatter (summary/topics/wiki_links)
11	#   3. vault-commit-and-scan.ps1 -- commits enriched file to second-brain git repo
12	
13	[CmdletBinding()]
14	param(
15	    [int]$Max = 1000
16	)
17	
18	$ErrorActionPreference = 'Continue'
19	
20	$HARVEST_DIR = 'C:\Users\mattm\master-jarvis\scripts\ingest\x-bookmarks'
21	$BUN = 'C:\Users\mattm\.bun\bin\bun.exe'
22	$NODE = 'C:\Program Files\nodejs\node.exe'   # bun's child_process is incompatible with Playwright; runtime uses node
23	$STATUS_FILE = 'C:\Users\mattm\master-jarvis\second-brain\raw\_ingest-status.md'
24	
25	Push-Location $HARVEST_DIR
26	try {
27	    # Build node args; harvest-api.mjs accepts --max <N>
28	    $nodeArgs = @('harvest-api.mjs', '--max', $Max.ToString())
29	
30	    $start = Get-Date
31	    # Stream Node output line-by-line so login prompts are visible in real-time.
32	    # Collect into $lines for later parsing; $LASTEXITCODE is captured after the loop.
33	    $lines = [System.Collections.Generic.List[string]]::new()
34	    & $NODE @nodeArgs 2>&1 | ForEach-Object { Write-Host $_; $lines.Add($_.ToString()) }
35	    $exit = $LASTEXITCODE
36	    $output = $lines -join "`n"
37	    $duration = [math]::Round(((Get-Date) - $start).TotalSeconds, 1)
38	
39	    # Parse output for counts
40	    $harvested = if ($output -match 'harvested=(\d+)') { [int]$matches[1] } else { 0 }
41	    $written = if ($output -match 'written=(\d+)') { [int]$matches[1] } else { 0 }
42	    $removed = if ($output -match 'removed=(\d+)') { [int]$matches[1] } else { 0 }
43	    $vaultFile = if ($output -match 'file=(\S+)') { $matches[1].Trim() } else { $null }
44	
45	    # AI analysis pass
46	    $analyzed = 0; $analyzeSkipped = 0; $analyzeFailed = 0
47	    if ($exit -eq 0 -and $written -gt 0 -and $vaultFile -and (Test-Path $vaultFile)) {
48	        Write-Host "Running AI analysis on $vaultFile..."
49	        $aLines = [System.Collections.Generic.List[string]]::new()
50	        & $BUN run analyze.mjs --file $vaultFile --wiki-dir 'C:\Users\mattm\master-jarvis\second-brain\wiki' 2>&1 |
51	            ForEach-Object { Write-Host $_; $aLines.Add($_.ToString()) }
52	        $aOut = $aLines -join "`n"
53	        if ($aOut -match 'ANALYZE analyzed=(\d+) skipped=(\d+) failed=(\d+)') {
54	            $analyzed = [int]$matches[1]; $analyzeSkipped = [int]$matches[2]; $analyzeFailed = [int]$matches[3]
55	        }
56	    }
57	
58	    $note = switch ($exit) {
59	        0 {
60	            $parts = @()
61	            if ($written -gt 0) { $parts += "+$written tweets" }
62	            if ($removed -gt 0) { $parts += "-$removed deleted-on-X" }
63	            if ($analyzed -gt 0) { $parts += "AI analyzed=$analyzed" }
64	            if ($parts.Count -eq 0) { 'no changes' } else { $parts -join ', ' }
65	        }
66	        2 { 'AUTH_EXPIRED - update .auth.json with fresh cookies from Chrome DevTools' }
67	        default { 'harvest error - see logs' }
68	    }
69	
70	    # Update status dashboard
71	    $ts = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
72	    $row = '| x-bookmarks | ' + $ts + ' | ' + $exit + ' | harvested=' + $harvested + ' written=' + $written + ' removed=' + $removed + ' analyzed=' + $analyzed + ' | ' + $duration + 's | ' + $note + ' |'
73	    $existing = if (Test-Path $STATUS_FILE) { [System.IO.File]::ReadAllText($STATUS_FILE, [System.Text.UTF8Encoding]::new($false)) } else { '' }
74	    if ($existing -match '<!-- x-bookmarks:start -->[\s\S]*<!-- x-bookmarks:end -->') {
75	        $newBlock = "<!-- x-bookmarks:start -->`n$row`n<!-- x-bookmarks:end -->"
76	        $newContent = $existing -replace '<!-- x-bookmarks:start -->[\s\S]*<!-- x-bookmarks:end -->', $newBlock
77	    } else {
78	        $header = if ($existing) { '' } else { "# Vault Ingest Status (auto-updated)`n`n| Source | Last Run | Exit | Counts | Duration | Notes |`n|---|---|---|---|---|---|`n" }
79	        $newContent = $existing + $header + "<!-- x-bookmarks:start -->`n$row`n<!-- x-bookmarks:end -->`n"
80	    }
81	    [System.IO.File]::WriteAllText($STATUS_FILE, $newContent, [System.Text.UTF8Encoding]::new($false))
82	
83	    # --- Sunday: generate weekly digest ---
84	    if ($exit -eq 0 -and (Get-Date).DayOfWeek -eq 'Sunday') {
85	        Write-Host "Sunday run -- generating weekly digest..."
86	        & $NODE 'generate-weekly-digest.mjs' 2>&1 | ForEach-Object { Write-Host $_ }
87	    }
88	
89	    # --- Auto-commit (FV1 + FV2) ---
90	    if ($exit -eq 0 -and $written -gt 0) {
91	        $commitArgs = @{
92	            Source  = 'x-bookmarks'
93	            Paths   = @('raw/x-bookmarks/', 'personal/weekly-reviews/')
94	            Subject = ('feat(x-bookmarks): {0} tweets analyzed={1} (harvested={2})' -f $written, $analyzed, $harvested)
95	        }
96	        & 'C:\Users\mattm\master-jarvis\scripts\vault-commit-and-scan.ps1' @commitArgs
97	    }
98	
99	    exit $exit
100	} finally {
101	    Pop-Location
102	}
