# rotate-x-creds.ps1 -- securely store/rotate X (Twitter) API creds in 1Password.
#
# Prompts (HIDDEN input) for each field. Leave a prompt BLANK to skip that field,
# so this works for BOTH "just add the OAuth2 client secret" and "full rotation".
# Secret values are never printed, never written to disk, never put in the transcript.
# Run it yourself:  ! pwsh -NoProfile -File C:\Users\mattm\Code\x-mcp\rotate-x-creds.ps1
#
# After it finishes, tell Claude "creds stored" and it will run refresh-env.ps1 +
# force a fresh OAuth2 token + flip the harvest flag.

$ErrorActionPreference = 'Stop'
$item  = 'X-API'
$vault = 'Amo Personal'

# field key in 1P  ->  human label shown at the prompt
$fields = @(
    @{ key = 'api_key';              label = 'API Key (consumer key)' }
    @{ key = 'api_secret';           label = 'API Secret (consumer secret)' }
    @{ key = 'access_token';         label = 'Access Token' }
    @{ key = 'access_token_secret';  label = 'Access Token Secret' }
    @{ key = 'bearer_token';         label = 'Bearer Token' }
    @{ key = 'oauth2_client_secret'; label = 'OAuth 2.0 Client Secret  (the durability unblock)' }
)

Write-Host "Storing into 1Password item '$item' (vault '$vault'). Blank = skip a field." -ForegroundColor Cyan

$assignments = @()
foreach ($f in $fields) {
    $sec = Read-Host -AsSecureString ("New {0}" -f $f.label)
    $bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec)
    try {
        $plain = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)
    } finally {
        [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
    }
    if ([string]::IsNullOrWhiteSpace($plain)) {
        Write-Host ("  skip  {0}" -f $f.key) -ForegroundColor DarkGray
        continue
    }
    $assignments += ("{0}[password]={1}" -f $f.key, $plain)
    Write-Host ("  queued {0}  (len {1})" -f $f.key, $plain.Length) -ForegroundColor Green
}

if ($assignments.Count -eq 0) {
    Write-Host 'Nothing entered -- no changes made.' -ForegroundColor Yellow
    exit 0
}

# Single op call. Stdout piped to Out-Null so op's item echo (which includes field
# values) is never shown. Errors still surface on stderr.
& op item edit $item --vault $vault @assignments | Out-Null
if ($LASTEXITCODE -ne 0) {
    Write-Host "op item edit FAILED (exit $LASTEXITCODE)." -ForegroundColor Red
    exit $LASTEXITCODE
}

Write-Host ("Updated {0} field(s) in 1P '{1}'. Tell Claude: creds stored." -f $assignments.Count, $item) -ForegroundColor Cyan

