# refresh-env.ps1 -- generate ~/Code/x-mcp/.env from the 1Password "X-API" item.
#
# The x-twitter MCP (registered in jarvis-trader/.mcp.json) loads its creds from
# this .env via dotenv, so it works regardless of how Claude Code is launched.
# .env is gitignored (see .gitignore) -- 1Password remains the source of truth;
# this file is a derived local artifact. Re-run after rotating the X creds.
#
# Uses a SINGLE `op item get --format json` call (not N `op read`s) to dodge the
# bulk-read throttle in the 1Password desktop integration. Values are parsed
# in-process and never printed to the console.
#
#   pwsh -NoProfile -File ~/Code/x-mcp/refresh-env.ps1

[CmdletBinding()]
param(
    [string]$Vault = "Amo Personal",
    [string]$Item  = "X-API"
)

$ErrorActionPreference = "Stop"

$op = Get-Command op -ErrorAction SilentlyContinue
if (-not $op) { Write-Error "1Password CLI 'op' not found. Install + sign in first."; exit 2 }

# env-var -> 1Password field label (must match the labels on the X-API item)
$Required = [ordered]@{
    "X_API_KEY"             = "api_key"
    "X_API_SECRET"          = "api_secret"
    "X_ACCESS_TOKEN"        = "access_token"
    "X_ACCESS_TOKEN_SECRET" = "access_token_secret"
    "X_BEARER_TOKEN"        = "bearer_token"
}
# Optional OAuth 2.0 client creds (only present if you added these fields)
$Optional = [ordered]@{
    "X_OAUTH2_CLIENT_ID"     = "oauth2_client_id"
    "X_OAUTH2_CLIENT_SECRET" = "oauth2_client_secret"
}

Write-Host "Reading item '$Item' from vault '$Vault' (single op call)..." -ForegroundColor Cyan
$raw = & op item get $Item --vault $Vault --format json 2>&1
if ($LASTEXITCODE -ne 0) {
    Write-Error "op item get failed. Does the '$Item' item exist in vault '$Vault'? Detail: $raw"
    exit 1
}

try { $json = $raw | ConvertFrom-Json } catch { Write-Error "Could not parse op JSON: $_"; exit 1 }

# Map field label -> value
$byLabel = @{}
foreach ($f in $json.fields) {
    if ($f.label) { $byLabel[$f.label] = $f.value }
}

$lines   = @()
$missing = @()
foreach ($pair in $Required.GetEnumerator()) {
    $val = $byLabel[$pair.Value]
    if ([string]::IsNullOrWhiteSpace($val)) { $missing += "$($pair.Key) (field '$($pair.Value)')" }
    else { $lines += "$($pair.Key)=$val" }
}

if ($missing.Count -gt 0) {
    Write-Error ("Missing required field(s) on item '$Item': " + ($missing -join ", ") +
        ". Add them as fields with those exact labels, then re-run.")
    exit 1
}

foreach ($pair in $Optional.GetEnumerator()) {
    $val = $byLabel[$pair.Value]
    if (-not [string]::IsNullOrWhiteSpace($val)) { $lines += "$($pair.Key)=$val" }
}

$envPath = Join-Path $PSScriptRoot ".env"
# Write LF-terminated, no BOM (dotenv-friendly)
$content = ($lines -join "`n") + "`n"
[System.IO.File]::WriteAllText($envPath, $content, (New-Object System.Text.UTF8Encoding($false)))

Write-Host ("Wrote {0} vars to {1}" -f $lines.Count, $envPath) -ForegroundColor Green
Write-Host "Restart the x-twitter MCP (or Claude Code) to pick them up." -ForegroundColor Green

