// Force a confidential-client OAuth2 refresh now (we now have client_secret).
// Mirrors oauth2.ts refreshAccessToken(), but does NOT delete the token file on
// failure (so a still-valid refresh_token survives for a setup_oauth2 fallback).
// Prints status + lengths only -- never token values.
import { readFileSync, writeFileSync } from 'fs';

const TOKEN_FILE = 'C:/Users/mattm/Code/x-mcp/.oauth2-tokens.json';
const ENV_FILE = 'C:/Users/mattm/Code/x-mcp/.env';
const TOKEN_URL = 'https://api.twitter.com/2/oauth2/token';

const tokens = JSON.parse(readFileSync(TOKEN_FILE, 'utf-8'));
const env = Object.fromEntries(
  readFileSync(ENV_FILE, 'utf-8').split(/\r?\n/).filter(Boolean).filter(l => !l.startsWith('#'))
    .map(l => { const i = l.indexOf('='); return [l.slice(0, i).trim(), l.slice(i + 1).trim()]; })
);
const clientId = env.X_OAUTH2_CLIENT_ID;
const clientSecret = env.X_OAUTH2_CLIENT_SECRET;
if (!tokens.refresh_token) { console.error('no refresh_token'); process.exit(2); }
if (!clientId || !clientSecret) { console.error('missing client_id/secret in .env'); process.exit(2); }

const body = new URLSearchParams({
  grant_type: 'refresh_token',
  refresh_token: tokens.refresh_token,
  client_id: clientId,
});

const res = await fetch(TOKEN_URL, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/x-www-form-urlencoded',
    Authorization: 'Basic ' + Buffer.from(`${clientId}:${clientSecret}`).toString('base64'),
  },
  body: body.toString(),
});

console.log('HTTP', res.status, res.statusText);
const text = await res.text();
if (!res.ok) {
  console.log('CONFIDENTIAL REFRESH FAILED (token file preserved):', text.slice(0, 400));
  process.exit(1);
}
const data = JSON.parse(text);
writeFileSync(TOKEN_FILE, JSON.stringify({
  access_token: data.access_token,
  refresh_token: data.refresh_token,
  expires_at: Date.now() + data.expires_in * 1000,
}, null, 2));
const expMin = Math.round(data.expires_in / 60);
console.log(`CONFIDENTIAL REFRESH OK -- fresh tokens saved (access len ${data.access_token.length}, refresh len ${data.refresh_token.length}, valid ~${expMin} min).`);

