// Spawn the x-twitter MCP and invoke setup_oauth2 (fresh PKCE browser authorize).
// The MCP opens the browser + prints the authorize URL to stderr; we mirror that
// URL into a file immediately so the parent session can surface it without waiting.
// Writes fresh tokens to ~/Code/x-mcp/.oauth2-tokens.json on success.
import { spawn } from 'child_process';
import { writeFileSync } from 'fs';

const MCP = 'C:/Users/mattm/Code/x-mcp/dist/index.js';
const URL_FILE = 'C:/Users/mattm/AppData/Local/Temp/claude/C--windows-system32/b2ebcf3b-f06c-4765-b2ab-6fa1767d0291/scratchpad/authorize-url.txt';

const child = spawn('node', [MCP], { stdio: ['pipe', 'pipe', 'pipe'] });
let buf = '';
const send = o => child.stdin.write(JSON.stringify(o) + '\n');

child.stderr.on('data', d => {
  const s = d.toString();
  process.stderr.write(s);
  const m = s.match(/https:\/\/twitter\.com\/i\/oauth2\/authorize\?\S+/);
  if (m) { try { writeFileSync(URL_FILE, m[0]); } catch {} }
});

child.stdout.on('data', d => {
  buf += d.toString();
  let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i); buf = buf.slice(i + 1);
    if (!line.trim()) continue;
    let m; try { m = JSON.parse(line); } catch { continue; }
    if (m.id === 1) {
      send({ jsonrpc: '2.0', method: 'notifications/initialized' });
      send({ jsonrpc: '2.0', id: 2, method: 'tools/call', params: { name: 'setup_oauth2', arguments: {} } });
    } else if (m.id === 2) {
      const okRes = m.result && !m.result.isError;
      console.log(okRes ? 'SETUP_OAUTH2 COMPLETE' : ('SETUP_OAUTH2 ERROR: ' + JSON.stringify(m.result).slice(0, 400)));
      try { child.kill(); } catch {}
      process.exit(okRes ? 0 : 1);
    }
  }
});

send({ jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'setup', version: '1.0' } } });
// Parent safety net (MCP's own authorize times out at 120s).
setTimeout(() => { console.log('HARNESS TIMEOUT'); try { child.kill(); } catch {} process.exit(2); }, 140000);

