// One-time .seen key migration for the cookie->MCP cutover.
// Fetch all current bookmarks via the MCP, compute their MCP dedup keys, and
// append any not-already-present keys to the PRODUCTION .seen ledger. Writes no
// md/jsonl/analyze -- purely seeds the ledger so the first real MCP run sees
// existing bookmarks as already-harvested (no duplicate re-ingest).
import { harvestViaMcp, bookmarkKey } from 'file:///C:/Users/mattm/master-jarvis/scripts/ingest/x-bookmarks/harvest-mcp.mjs';
import { readFileSync, appendFileSync, existsSync } from 'fs';

const SEEN = 'C:/Users/mattm/master-jarvis/second-brain/raw/x-bookmarks/.seen.txt';
const MAX = 2500;

const seen = new Set();
if (existsSync(SEEN)) {
  for (const l of readFileSync(SEEN, 'utf-8').split('\n')) if (l.trim()) seen.add(l.trim());
}
const before = seen.size;

const bms = await harvestViaMcp(MAX);
const keys = [...new Set(bms.map(bookmarkKey))];
const newKeys = keys.filter(k => !seen.has(k));
if (newKeys.length) appendFileSync(SEEN, newKeys.join('\n') + '\n', 'utf-8');

console.log(`fetched=${bms.length} distinct_mcp_keys=${keys.length} already_in_seen=${keys.length - newKeys.length} seeded_new=${newKeys.length} seen_before=${before} seen_after=${before + newKeys.length}`);

