// Probe get_bookmarks page-1 meta only (result_count, next_token presence).
// Tries arg name "next_token" AND a second call with "pagination_token" to see
// if either continues. No tweet content printed.
import { spawn } from 'child_process';
const MCP = 'C:/Users/mattm/Code/x-mcp/dist/index.js';

function rpc(callArgsList) {
  return new Promise((resolve, reject) => {
    const child = spawn('node', [MCP], { stdio: ['pipe', 'pipe', 'pipe'] });
    let buf = '', err = '';
    const results = [];
    const send = o => child.stdin.write(JSON.stringify(o) + '\n');
    child.stderr.on('data', d => err += d.toString());
    child.stdout.on('data', d => {
      buf += d.toString(); let i;
      while ((i = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue;
        let m; try { m = JSON.parse(line); } catch { continue; }
        if (m.id === 1) {
          send({ jsonrpc: '2.0', method: 'notifications/initialized' });
          send({ jsonrpc: '2.0', id: 2, method: 'tools/call', params: { name: 'get_bookmarks', arguments: { max_results: 100 } } });
        } else if (m.id === 2) {
          try {
            const p = JSON.parse(m.result.content[0].text);
            const payload = p.data || p;
            results.push({ call: 'page1', count: (payload.data || []).length, meta: payload.meta || null, rate: p.rate_limit });
            const nt = payload.meta?.next_token;
            // try to continue with next_token if present, else try a bogus check
            send({ jsonrpc: '2.0', id: 3, method: 'tools/call', params: { name: 'get_bookmarks', arguments: nt ? { max_results: 100, next_token: nt } : { max_results: 100, pagination_token: 'TEST' } } });
          } catch (e) { results.push({ call: 'page1', error: m.result?.content?.[0]?.text?.slice(0,200) }); send({ jsonrpc: '2.0', id: 3, method: 'tools/call', params: { name: 'get_bookmarks', arguments: { max_results: 5 } } }); }
        } else if (m.id === 3) {
          try {
            const p = JSON.parse(m.result.content[0].text);
            const payload = p.data || p;
            results.push({ call: 'page2', count: (payload.data || []).length, meta: payload.meta || null });
          } catch (e) { results.push({ call: 'page2', error: (m.result?.content?.[0]?.text || '').slice(0,200) }); }
          try { child.kill(); } catch {}
          resolve(results);
        }
      }
    });
    child.on('exit', () => { if (!results.length) reject(new Error('exited: ' + err.slice(0,300))); });
    send({ jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'probe', version: '1.0' } } });
    setTimeout(() => { try { child.kill(); } catch {}; reject(new Error('timeout: ' + err.slice(0,200))); }, 60000);
  });
}

const r = await rpc();
console.log(JSON.stringify(r, null, 2));

