// Validate the bearer (app-only) token via get_user (bearerFetch path).
// Prints only public profile fields + status -- no creds.
import { spawn } from 'child_process';
const MCP = 'C:/Users/mattm/Code/x-mcp/dist/index.js';
const child = spawn('node', [MCP], { stdio: ['pipe', 'pipe', 'pipe'] });
let buf = '', err = '';
const send = o => child.stdin.write(JSON.stringify(o) + '\n');
child.stderr.on('data', d => err += d.toString());
child.stdout.on('data', d => {
  buf += d.toString(); let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue;
    let m; try { m = JSON.parse(line); } catch { continue; }
    if (m.id === 1) {
      send({ jsonrpc: '2.0', method: 'notifications/initialized' });
      send({ jsonrpc: '2.0', id: 2, method: 'tools/call', params: { name: 'get_user', arguments: { username: 'X' } } });
    } else if (m.id === 2) {
      const txt = m.result?.content?.[0]?.text || '';
      if (m.result?.isError) {
        console.log('BEARER VALIDATION FAILED:', txt.slice(0, 300));
        try { child.kill(); } catch {}; process.exit(1);
      }
      try {
        const p = JSON.parse(txt);
        const u = p.data?.data || p.data || {};
        console.log('BEARER OK -> get_user(@X) returned:',
          JSON.stringify({ id: u.id, username: u.username, name: u.name, followers: u.public_metrics?.followers_count }));
        console.log('rate_limit:', p.rate_limit || '(n/a)');
      } catch { console.log('BEARER OK (200) but unexpected body:', txt.slice(0, 200)); }
      try { child.kill(); } catch {}; process.exit(0);
    }
  }
});
child.on('exit', () => { if (err && !buf) console.log('exit. stderr:', err.slice(0, 300)); });
send({ jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'probe', version: '1.0' } } });
setTimeout(() => { try { child.kill(); } catch {}; console.log('TIMEOUT. stderr:', err.slice(0,200)); process.exit(2); }, 40000);

# x-bookmarks-export.ps1
# Wrapper for the X.com bookmark harvester + AI analysis pass.
# Schedule via: Jarvis-VaultIngest-XBookmarks (daily 06:00 CT).
#
# Harvest source (both share the same VAULT_DIR + .seen/.removed ledgers + DONE line):
#   * PRIMARY  harvest-mcp.mjs -- x-twitter MCP get_bookmarks (X API v2, OAuth2). No cookies.
#   * FALLBACK harvest-api.mjs -- direct X.com GraphQL via .auth.json Chrome cookies.
#   The MCP path is gated behind env X_BM_USE_MCP=1 (default OFF). While OFF, behavior is
#   byte-identical to the cookie-only pipeline. Flip to 1 once OAuth2 refresh is durable
#   (oauth2_client_secret present so the MCP can refresh the ~2h access token unattended).
#   When ON, MCP runs first; ANY nonzero exit falls back to the cookie harvester.
#
# Pipeline:
#   1. harvest (MCP primary / cookie fallback) -- writes YYYY-WW.md (deduped)
#   2. analyze.mjs     -- enriches new tweet blocks with AI frontmatter (summary/topics/wiki_links)
#   3. vault-commit-and-scan.ps1 -- commits enriched file to second-brain git repo

[CmdletBinding()]
param(
    [int]$Max = 1000,
    # Force the full-coverage cookie harvester regardless of X_BM_USE_MCP. Used by the
    # weekly Jarvis-VaultIngest-XBookmarks-FullSync task to catch bookmarks beyond the
    # MCP path's most-recent-~99 window (and keep cookie-side delete-tracking warm).
    [switch]$ForceCookie
)

$ErrorActionPreference = 'Continue'

$HARVEST_DIR = 'C:\Users\mattm\master-jarvis\scripts\ingest\x-bookmarks'
$BUN = 'C:\Users\mattm\.bun\bin\bun.exe'
$NODE = 'C:\Program Files\nodejs\node.exe'   # bun's child_process is incompatible with Playwright; runtime uses node
$STATUS_FILE = 'C:\Users\mattm\master-jarvis\second-brain\raw\_ingest-status.md'

Push-Location $HARVEST_DIR
try {
    # Harvest source selection. Both harvesters accept --max <N> and emit the same DONE line.
    # -ForceCookie wins over the env gate (used by the weekly full-sync task).
    $useMcp = ($env:X_BM_USE_MCP -eq '1') -and (-not $ForceCookie)
    $source = 'cookie'
    $exit = 0

    $start = Get-Date
    # Stream Node output line-by-line so login prompts are visible in real-time.
    # Collect into $lines for later parsing; $LASTEXITCODE is captured after the loop.
    $lines = [System.Collections.Generic.List[string]]::new()

    if ($useMcp) {
        # PRIMARY: x-twitter MCP get_bookmarks (OAuth2). Any nonzero exit -> cookie fallback.
        $mcpLines = [System.Collections.Generic.List[string]]::new()
        & $NODE 'harvest-mcp.mjs' '--max' $Max.ToString() 2>&1 | ForEach-Object { Write-Host $_; $mcpLines.Add($_.ToString()) }
        $mcpExit = $LASTEXITCODE
        if ($mcpExit -eq 0) {
            $source = 'mcp'
            $exit = 0
            foreach ($l in $mcpLines) { [void]$lines.Add($l) }
        } else {
            Write-Host "MCP harvest failed (exit $mcpExit) -- falling back to cookie GraphQL."
        }
    }

    if ($source -ne 'mcp') {
        # FALLBACK (or default): direct GraphQL via .auth.json cookies.
        & $NODE 'harvest-api.mjs' '--max' $Max.ToString() 2>&1 | ForEach-Object { Write-Host $_; [void]$lines.Add($_.ToString()) }
        $exit = $LASTEXITCODE
    }

    $output = $lines -join "`n"
    $duration = [math]::Round(((Get-Date) - $start).TotalSeconds, 1)

    # Parse output for counts
    $harvested = if ($output -match 'harvested=(\d+)') { [int]$matches[1] } else { 0 }
    $written = if ($output -match 'written=(\d+)') { [int]$matches[1] } else { 0 }
    $removed = if ($output -match 'removed=(\d+)') { [int]$matches[1] } else { 0 }
    $vaultFile = if ($output -match 'file=(\S+)') { $matches[1].Trim() } else { $null }

    # AI analysis pass
    $analyzed = 0; $analyzeSkipped = 0; $analyzeFailed = 0
    if ($exit -eq 0 -and $written -gt 0 -and $vaultFile -and (Test-Path $vaultFile)) {
        Write-Host "Running AI analysis on $vaultFile..."
        $aLines = [System.Collections.Generic.List[string]]::new()
        & $BUN run analyze.mjs --file $vaultFile --wiki-dir 'C:\Users\mattm\master-jarvis\second-brain\wiki' 2>&1 |
            ForEach-Object { Write-Host $_; $aLines.Add($_.ToString()) }
        $aOut = $aLines -join "`n"
        if ($aOut -match 'ANALYZE analyzed=(\d+) skipped=(\d+) failed=(\d+)') {
            $analyzed = [int]$matches[1]; $analyzeSkipped = [int]$matches[2]; $analyzeFailed = [int]$matches[3]
        }
    }

    $note = switch ($exit) {
        0 {
            $parts = @()
            if ($written -gt 0) { $parts += "+$written tweets" }
            if ($removed -gt 0) { $parts += "-$removed deleted-on-X" }
            if ($analyzed -gt 0) { $parts += "AI analyzed=$analyzed" }
            if ($parts.Count -eq 0) { 'no changes' } else { $parts -join ', ' }
        }
        2 { 'AUTH_EXPIRED - update .auth.json with fresh cookies from Chrome DevTools' }
        default { 'harvest error - see logs' }
    }

    # Update status dashboard
    $ts = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
    $row = '| x-bookmarks | ' + $ts + ' | ' + $exit + ' | src=' + $source + ' harvested=' + $harvested + ' written=' + $written + ' removed=' + $removed + ' analyzed=' + $analyzed + ' | ' + $duration + 's | ' + $note + ' |'
    $existing = if (Test-Path $STATUS_FILE) { [System.IO.File]::ReadAllText($STATUS_FILE, [System.Text.UTF8Encoding]::new($false)) } else { '' }
    if ($existing -match '<!-- x-bookmarks:start -->[\s\S]*<!-- x-bookmarks:end -->') {
        $newBlock = "<!-- x-bookmarks:start -->`n$row`n<!-- x-bookmarks:end -->"
        $newContent = $existing -replace '<!-- x-bookmarks:start -->[\s\S]*<!-- x-bookmarks:end -->', $newBlock
    } else {
        $header = if ($existing) { '' } else { "# Vault Ingest Status (auto-updated)`n`n| Source | Last Run | Exit | Counts | Duration | Notes |`n|---|---|---|---|---|---|`n" }
        $newContent = $existing + $header + "<!-- x-bookmarks:start -->`n$row`n<!-- x-bookmarks:end -->`n"
    }
    [System.IO.File]::WriteAllText($STATUS_FILE, $newContent, [System.Text.UTF8Encoding]::new($false))

    # --- Sunday: generate weekly digest ---
    if ($exit -eq 0 -and (Get-Date).DayOfWeek -eq 'Sunday') {
        Write-Host "Sunday run -- generating weekly digest..."
        & $NODE 'generate-weekly-digest.mjs' 2>&1 | ForEach-Object { Write-Host $_ }
    }

    # --- Auto-commit (FV1 + FV2) ---
    if ($exit -eq 0 -and $written -gt 0) {
        $commitArgs = @{
            Source  = 'x-bookmarks'
            Paths   = @('raw/x-bookmarks/', 'personal/weekly-reviews/')
            Subject = ('feat(x-bookmarks): {0} tweets analyzed={1} (harvested={2})' -f $written, $analyzed, $harvested)
        }
        & 'C:\Users\mattm\master-jarvis\scripts\vault-commit-and-scan.ps1' @commitArgs
    }

    exit $exit
} finally {
    Pop-Location
}

