# Exit non-zero only on a GENUINE required-task failure.
#
# A still-running task at the orchestrator deadline returns state='TIMEOUT'. That is NOT a
# failure: each pipeline runs on its own cadence and finishes async (Files ~11 min; OneNote
# can run hours), and this orchestrator is a belt-and-suspenders trigger, not a gate. The
# hourly Jarvis-VaultGbrainSync + the verify-jarvis-tasks sweep catch a genuinely stuck or
# failed sub-task independently. Treating TIMEOUT as fatal produced false 0x1 exits
# (2026-06-30: files=TIMEOUT while the standalone Jarvis-VaultIngest-Files task succeeded
# 0x0). So TIMEOUT on a required task is now a soft warning.
#
# A genuine required failure is: couldn't start (TASK_MISSING/START_FAILED/MISSING), the
# daemon sync hard-failed (gbrain-sync FAILED), or a sub-task reached a terminal state with a
# nonzero LastTaskResult. The previous predicate missed terminal+nonzero entirely ('Ready'
# was not in the fail set), so real failures slipped through while TIMEOUT false-tripped.
$timedOut = @($results | Where-Object { $_.state -eq 'TIMEOUT' -and -not $_.optional })
foreach ($w in $timedOut) {
    Write-Host "WARN: required task '$($w.source)' still running at ${PerTaskTimeoutMin}m deadline; it completes on its own cadence (not a roll-up failure)."
}
$failed = @($results | Where-Object {
    if ($_.optional) { $false }
    elseif ($_.state -in @('TASK_MISSING', 'START_FAILED', 'MISSING', 'FAILED')) { $true }
    elseif ($_.state -in @('TIMEOUT', 'OK', 'DAEMON_DOWN')) { $false }
    else { ($null -ne $_.result -and $_.result -ne 0) }
})
if ($failed.Count -gt 0) {
    Write-Host ('Required failures: ' + (($failed | ForEach-Object { "$($_.source)=$($_.state):$($_.result)" }) -join ', '))
    exit 1
}
exit 0

