# apply-openai-key.ps1
# Installs a NEW OpenAI API key from a local temp file into engine/.env + 1Password,
# WITHOUT ever printing the key to the console/chat. Verifies the new key is live
# before installing, then shreds the temp file.
#
# Usage:
#   1. Save your new key (just the key, one line) to the temp file (default below).
#   2. Run:  pwsh -NoProfile -File C:\Users\mattm\scripts\apply-openai-key.ps1
#
# The script NEVER echoes the key. Output is status lines only.

[CmdletBinding()]
param(
    [string]$KeyFile = "$env:TEMP\new-openai-key.txt",
    [string]$EnvPath = 'C:\Users\mattm\ThinkorSwim\jarvis-trader\engine\.env',
    [string]$OpItem  = 'OpenAI-API',
    [string]$OpVault = 'Amo Personal',
    [string]$OpField = 'credential'
)
$ErrorActionPreference = 'Stop'

if (-not (Test-Path $KeyFile)) {
    Write-Host "ERROR: key file not found: $KeyFile"
    Write-Host "Save your new key to that path first, then re-run."
    exit 1
}

# Read, strip any UTF-8 BOM Notepad may add, trim whitespace/newlines. Never printed.
$key = [System.IO.File]::ReadAllText($KeyFile)
$key = $key.TrimStart([char]0xFEFF).Trim()

if ($key.Length -lt 20 -or $key -notmatch '^sk-') {
    Write-Host "ERROR: file does not look like an OpenAI key (must start with 'sk-', length >= 20)."
    Write-Host "Nothing was changed. Fix the file and re-run."
    exit 1
}

# 1) Verify the NEW key is LIVE before touching anything (read-only GET /models).
try {
    $r = Invoke-WebRequest -Uri 'https://api.openai.com/v1/models' -Headers @{ Authorization = "Bearer $key" } -TimeoutSec 20 -UseBasicParsing
    Write-Host ("New key check: HTTP " + $r.StatusCode + " -> LIVE. Installing...")
} catch {
    $code = $_.Exception.Response.StatusCode.value__
    Write-Host ("New key check: HTTP " + $code + " -> NOT live (401=invalid, 429=quota).")
    Write-Host "Nothing was changed. Double-check the key you pasted and re-run."
    exit 1
}

# 2) Surgically rewrite the OPENAI_API_KEY= line in engine/.env (in place, UTF-8 no BOM).
$lines = [System.IO.File]::ReadAllLines($EnvPath)
$found = $false
for ($i = 0; $i -lt $lines.Length; $i++) {
    if ($lines[$i] -match '^\s*OPENAI_API_KEY\s*=') {
        $lines[$i] = "OPENAI_API_KEY=$key"
        $found = $true
        break
    }
}
if (-not $found) {
    Write-Host "ERROR: no 'OPENAI_API_KEY=' line found in $EnvPath. Nothing changed."
    exit 1
}
[System.IO.File]::WriteAllLines($EnvPath, $lines, [System.Text.UTF8Encoding]::new($false))
Write-Host "engine/.env: OPENAI_API_KEY line rewritten in place."

# 3) Update 1Password (canonical store). Best-effort; never prints the key.
$op = Get-Command op -ErrorAction SilentlyContinue
if ($op) {
    try {
        op item edit $OpItem --vault $OpVault ("{0}={1}" -f $OpField, $key) *> $null
        Write-Host ("1Password '" + $OpItem + "/" + $OpField + "' updated.")
    } catch {
        Write-Host "WARN: 1Password update failed (unlock 1P / 'op signin' and update it manually). engine/.env WAS updated."
    }
} else {
    Write-Host "WARN: 'op' CLI not found. engine/.env WAS updated; update 1Password manually later."
}

# 4) Shred the temp file (overwrite with zeros, then delete).
try {
    $len = (Get-Item $KeyFile).Length
    if ($len -gt 0) { [System.IO.File]::WriteAllBytes($KeyFile, (New-Object byte[] $len)) }
    Remove-Item $KeyFile -Force
    Write-Host ("Temp key file shredded and deleted: " + $KeyFile)
} catch {
    Write-Host ("WARN: could not shred " + $KeyFile + " -- delete it yourself.")
}

Write-Host ""
Write-Host "DONE. The engine still holds the OLD key in memory -- restart it to load the new one:"
Write-Host "    cd C:\Users\mattm\ThinkorSwim\jarvis-trader"
Write-Host "    .\restart_engine.ps1"

