# vault-ingest-all.ps1
# Orchestrates all vault ingest pipelines + the daemon-routed gbrain sync.
# Schedule via: Jarvis-VaultIngest-All (daily 04:00 CT)
#
# Per-source tasks run independently on their own cadence. This orchestrator
# is a daily belt-and-suspenders pass that:
#   1) Triggers each pipeline via Start-ScheduledTask (subject to its own conditions)
#   2) Waits for each, captures LastTaskResult
#   3) Runs the daemon-routed vault->brain sync once at the end (via /sync on :8077)
#   4) Writes a roll-up summary to second-brain/raw/_ingest-status.md
#
# NOTE (2026-05-30): step 3 was the legacy gbrain-bridge\sync.ps1, which drove
# `gbrain-trade.cmd sync` directly against PGlite -- that collides with the single-writer
# daemon and throws on chunk writes. It now calls tools\gbrain-vault-sync.ps1, which POSTs
# to the daemon's /sync (the daemon is the sole writer; no lock fight, no corruption).

[CmdletBinding()]
param(
    [int]$PerTaskTimeoutMin = 30
)

$ErrorActionPreference = 'Continue'

# Prevent system sleep during the long orchestration run (avoids 0x41306 terminated result at 4 AM)
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class PowerMgmt {
    [DllImport("kernel32.dll")]
    public static extern uint SetThreadExecutionState(uint esFlags);
    public const uint ES_CONTINUOUS = 0x80000000;
    public const uint ES_SYSTEM_REQUIRED = 0x00000001;
}
"@ -ErrorAction SilentlyContinue
try { [PowerMgmt]::SetThreadExecutionState([PowerMgmt]::ES_CONTINUOUS -bor [PowerMgmt]::ES_SYSTEM_REQUIRED) | Out-Null } catch {}

$STATUS_FILE = 'C:\Users\mattm\master-jarvis\second-brain\raw\_ingest-status.md'
$VAULT_SYNC_SCRIPT = 'C:\Users\mattm\tools\gbrain-vault-sync.ps1'

# Tasks the orchestrator triggers. Order matters only for embarrassingly
# parallel-safe pipelines (each writes to a disjoint vault subdir).
$TASKS = @(
    @{ Name = 'Jarvis-VaultIngest-Files'; Source = 'files'; Optional = $false }
    @{ Name = 'Jarvis-DiscordObsidianSync'; Source = 'discord'; Optional = $false }
    @{ Name = 'Jarvis-VaultIngest-XBookmarks'; Source = 'x-bookmarks'; Optional = $true }   # weekly: triggered here only as catch-up
    @{ Name = 'Jarvis-VaultIngest-OneNote'; Source = 'onenote'; Optional = $true }          # monthly: triggered here only as catch-up
)

function Wait-ForTask {
    param([string]$Name, [int]$TimeoutMin)
    $deadline = (Get-Date).AddMinutes($TimeoutMin)
    while ((Get-Date) -lt $deadline) {
        $info = Get-ScheduledTaskInfo -TaskName $Name -ErrorAction SilentlyContinue
        $task = Get-ScheduledTask -TaskName $Name -ErrorAction SilentlyContinue
        if (-not $task) { return @{ State = 'MISSING'; Result = $null } }
        if ($task.State -ne 'Running') {
            return @{ State = $task.State.ToString(); Result = $info.LastTaskResult }
        }
        Start-Sleep -Seconds 5
    }
    return @{ State = 'TIMEOUT'; Result = $null }
}

$results = @()

foreach ($t in $TASKS) {
    $name = $t.Name
    $task = Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue
    if (-not $task) {
        if ($t.Optional) {
            Write-Host "Skipping missing optional task: $name"
            continue
        }
        $results += @{ source = $t.Source; state = 'TASK_MISSING'; result = $null; duration = 0; optional = $t.Optional }
        continue
    }

    Write-Host "Triggering $name ..."
    $start = Get-Date
    try {
        Start-ScheduledTask -TaskName $name -ErrorAction Stop
    } catch {
        $results += @{ source = $t.Source; state = 'START_FAILED'; result = $_.Exception.Message; duration = 0; optional = $t.Optional }
        continue
    }

    Start-Sleep -Seconds 2
    $r = Wait-ForTask -Name $name -TimeoutMin $PerTaskTimeoutMin
    $duration = [math]::Round(((Get-Date) - $start).TotalSeconds, 1)
    $results += @{ source = $t.Source; state = $r.State; result = $r.Result; duration = $duration; optional = $t.Optional }
    Write-Host "  ${name}: state=$($r.State) result=$($r.Result) duration=${duration}s"
}

# --- daemon-routed vault -> brain sync (replaces the legacy direct-PGlite bridge) ---
Write-Host 'Running daemon-routed gbrain vault sync...'
$bridgeStart = Get-Date
& pwsh -NoProfile -ExecutionPolicy Bypass -File $VAULT_SYNC_SCRIPT 2>&1 | Out-String | Write-Host
$bridgeExit = $LASTEXITCODE
$bridgeDuration = [math]::Round(((Get-Date) - $bridgeStart).TotalSeconds, 1)
# exit 2 = daemon down (don't treat a missing daemon as a hard orchestrator failure; the
# dedicated Jarvis-VaultGbrainSync task + watchdog still cover it). 0 = OK, 1 = sync error.
$bridgeState = if ($bridgeExit -eq 0) { 'OK' } elseif ($bridgeExit -eq 2) { 'DAEMON_DOWN' } else { 'FAILED' }
$results += @{ source = 'gbrain-sync'; state = $bridgeState; result = $bridgeExit; duration = $bridgeDuration; optional = $false }

# --- Roll-up status row ---
$summary = ($results | ForEach-Object { "$($_.source)=$($_.state):$($_.result)" }) -join ' | '
$row = "| orchestrator | $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss')) | 0 | $summary | - | rolled-up daily |"

# Read with explicit UTF-8 (no BOM) to avoid cp1252 round-trip corruption.
# PS 5.1's Get-Content -Raw defaults to system code page, which double-encodes
# any non-ASCII bytes on every rewrite -- historical em-dash bug grew this file
# to 1.6 GB before fix on 2026-05-21.
$existing = if (Test-Path $STATUS_FILE) { [System.IO.File]::ReadAllText($STATUS_FILE, [System.Text.UTF8Encoding]::new($false)) } else { '' }
if ($existing -match '<!-- orchestrator:start -->[\s\S]*<!-- orchestrator:end -->') {
    $newContent = $existing -replace '<!-- orchestrator:start -->[\s\S]*<!-- orchestrator:end -->', "<!-- orchestrator:start -->`n$row`n<!-- orchestrator:end -->"
} else {
    $header = if ($existing) { '' } else { "# Vault Ingest Status (auto-updated)`n`n| Source | Last Run | Exit | Counts | Duration | Notes |`n|---|---|---|---|---|---|`n" }
    $newContent = $existing + $header + "<!-- orchestrator:start -->`n$row`n<!-- orchestrator:end -->`n"
}
[System.IO.File]::WriteAllText($STATUS_FILE, $newContent, [System.Text.UTF8Encoding]::new($false))

# Release sleep prevention
try { [PowerMgmt]::SetThreadExecutionState([PowerMgmt]::ES_CONTINUOUS) | Out-Null } catch {}

# Exit non-zero only on a GENUINE required-task failure.
#
# A still-running task at the orchestrator deadline returns state='TIMEOUT'. That is NOT a
# failure: each pipeline runs on its own cadence and finishes async (Files ~11 min; OneNote
# can run hours), and this orchestrator is a belt-and-suspenders trigger, not a gate. The
# hourly Jarvis-VaultGbrainSync + the verify-jarvis-tasks sweep catch a genuinely stuck or
# failed sub-task independently. Treating TIMEOUT as fatal produced false 0x1 exits
# (2026-06-30: files=TIMEOUT while the standalone Jarvis-VaultIngest-Files task succeeded
# 0x0). So TIMEOUT on a required task is now a soft warning.
#
# A genuine required failure is: couldn't start (TASK_MISSING/START_FAILED/MISSING), the
# daemon sync hard-failed (gbrain-sync FAILED), or a sub-task reached a terminal state with a
# nonzero LastTaskResult. The previous predicate missed terminal+nonzero entirely ('Ready'
# was not in the fail set), so real failures slipped through while TIMEOUT false-tripped.
$timedOut = @($results | Where-Object { $_.state -eq 'TIMEOUT' -and -not $_.optional })
foreach ($w in $timedOut) {
    Write-Host "WARN: required task '$($w.source)' still running at ${PerTaskTimeoutMin}m deadline; it completes on its own cadence (not a roll-up failure)."
}
$failed = @($results | Where-Object {
    if ($_.optional) { $false }
    elseif ($_.state -in @('TASK_MISSING', 'START_FAILED', 'MISSING', 'FAILED')) { $true }
    elseif ($_.state -in @('TIMEOUT', 'OK', 'DAEMON_DOWN')) { $false }
    else { ($null -ne $_.result -and $_.result -ne 0) }
})
if ($failed.Count -gt 0) {
    Write-Host ('Required failures: ' + (($failed | ForEach-Object { "$($_.source)=$($_.state):$($_.result)" }) -join ', '))
    exit 1
}
exit 0

