content.content:
1	<#
2	  fleet-health -- daily digest of Jarvis/Hermes/DP600/Loopify scheduled tasks + the
3	  loopctl loop fleet. Read-only. Reports always; pings Amo only on a HARD red.
4	  Compiled by /loopify (scheduled-cadence archetype). ASCII-only, PS 5.1-safe.
5	#>
6	[CmdletBinding()]
7	param(
8	    [string] $Id = 'fleet-health',
9	    [int]    $MaxRuntimeSec = 300
10	)
11	$ErrorActionPreference = 'Stop'
12	$loopctl = 'C:\Users\mattm\scripts\loopctl.ps1'
13	$sw = [System.Diagnostics.Stopwatch]::StartNew()
14	
15	function Send-LoopNote {
16	    param([string] $Text)
17	    $hook = $env:JARVIS_LOOP_WEBHOOK
18	    if ([string]::IsNullOrWhiteSpace($hook)) { return }
19	    try {
20	        $body = @{ content = "[$Id] $Text" } | ConvertTo-Json -Compress
21	        Invoke-RestMethod -Uri $hook -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 10 | Out-Null
22	    } catch { }
23	}
24	
25	try {
26	    $benign = @(0, 267009, 267011)          # success / running / never-run
27	    $soft   = @(267014, 267010)             # terminated / disabled -- note, don't ping
28	    $hardTasks = New-Object System.Collections.Generic.List[string]
29	    $softTasks = New-Object System.Collections.Generic.List[string]
30	
31	    $tasks = Get-ScheduledTask | Where-Object { $_.TaskName -match '^(Jarvis|JARVIS|Hermes|DP600|Loopify)-' }
32	    foreach ($t in $tasks) {
33	        if ($sw.Elapsed.TotalSeconds -gt $MaxRuntimeSec) { throw "runtime cap $MaxRuntimeSec s exceeded" }
34	        $info = $null
35	        try { $info = Get-ScheduledTaskInfo -TaskName $t.TaskName -ErrorAction Stop } catch { }
36	        $code = if ($info) { [int64]$info.LastTaskResult } else { -1 }
37	        $hex  = ('0x{0:X}' -f ($code -band 0xFFFFFFFF))
38	        if ($benign -contains $code) { continue }
39	        $line = "{0}  last={1} ({2})  lastRun={3}" -f $t.TaskName, $hex, $code, ($(if($info){$info.LastRunTime}else{'?'}))
40	        if ($soft -contains $code) { $softTasks.Add($line) } else { $hardTasks.Add($line) }
41	    }
42	
43	    # Loop fleet from the loopctl registry
44	    $regPath = Join-Path $env:USERPROFILE '.claude\loops\registry.json'
45	    $redLoops   = New-Object System.Collections.Generic.List[string]
46	    $staleLoops = New-Object System.Collections.Generic.List[string]
47	    if (Test-Path $regPath) {
48	        $reg = Get-Content $regPath -Raw | ConvertFrom-Json
49	        foreach ($l in @($reg.loops)) {
50	            if ($null -eq $l -or $l.id -eq $Id) { continue }
51	            $hb = "$($l.last_heartbeat)"
52	            if ($hb -match 'RED|ERROR') { $redLoops.Add("$($l.id): $hb"); continue }
53	            if ($l.status -eq 'deployed' -and $hb) {
54	                $stamp = ($hb -split ' ')[0]
55	                $dt = $null
56	                if ([datetime]::TryParse($stamp, [ref]$dt)) {
57	                    if (((Get-Date).ToUniversalTime() - $dt.ToUniversalTime()).TotalHours -gt 26) {
58	                        $staleLoops.Add("$($l.id): last hb $hb (>26h)")
59	                    }
60	                }
61	            }
62	        }
63	    }
64	
65	    $stamp = (Get-Date).ToString('yyyy-MM-dd HH:mm')
66	    $dir = Join-Path $env:USERPROFILE ".claude\loops\$Id"
67	    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
68	    $reportPath = Join-Path $dir ("report-{0}.md" -f (Get-Date).ToString('yyyy-MM-dd'))
69	
70	    $lines = New-Object System.Collections.Generic.List[string]
71	    $lines.Add("# Fleet health -- $stamp")
72	    $lines.Add("")
73	    $lines.Add("Scanned $($tasks.Count) Jarvis/Hermes/DP600/Loopify tasks.")
74	    $lines.Add("")
75	    $lines.Add("## HARD red (task) -- $($hardTasks.Count)")
76	    if ($hardTasks.Count -eq 0) { $lines.Add("- none") } else { $hardTasks | ForEach-Object { $lines.Add("- $_") } }
77	    $lines.Add("")
78	    $lines.Add("## Soft (terminated/disabled) -- $($softTasks.Count)")
79	    if ($softTasks.Count -eq 0) { $lines.Add("- none") } else { $softTasks | ForEach-Object { $lines.Add("- $_") } }
80	    $lines.Add("")
81	    $lines.Add("## Loop fleet -- red $($redLoops.Count), stale $($staleLoops.Count)")
82	    if ($redLoops.Count -eq 0 -and $staleLoops.Count -eq 0) { $lines.Add("- all green") }
83	    $redLoops   | ForEach-Object { $lines.Add("- RED $_") }
84	    $staleLoops | ForEach-Object { $lines.Add("- STALE $_") }
85	    $lines -join "`r`n" | Set-Content -Path $reportPath -Encoding UTF8
86	
87	    $hardCount = $hardTasks.Count + $redLoops.Count + $staleLoops.Count
88	    if ($hardCount -gt 0) {
89	        Send-LoopNote ("{0} hard issue(s): {1} task(s), {2} red loop(s), {3} stale. See {4}" -f `
90	            $hardCount, $hardTasks.Count, $redLoops.Count, $staleLoops.Count, $reportPath)
91	    }
92	
93	    & $loopctl -Action Heartbeat -Id $Id -State GREEN
94	    Write-Output "fleet-health OK: $($hardTasks.Count) hard, $($softTasks.Count) soft, $($redLoops.Count) red loops, $($staleLoops.Count) stale. report=$reportPath"
95	    exit 0
96	}
97	catch {
98	    $msg = $_.Exception.Message
99	    try { & $loopctl -Action Heartbeat -Id $Id -State RED } catch { }
100	    Send-LoopNote "RED: $msg"
101	    Write-Error "fleet-health FAILED: $msg"
102	    exit 1
103	}
104

