"  $isRepo"

Write-Host ""
Write-Host "=== SIGNAL A: untracked files in ~/scripts ==="
$porc = git -C $scripts status --short 2>$null
$untracked = @($porc | Where-Object { $_ -match '^\?\?' })
$codeUntracked = @($untracked | Where-Object { $_ -match '\.(ps1|ts|py|yaml|yml|md|js|sh|json)$' })
"  untracked(all)=$($untracked.Count)  code=$($codeUntracked.Count)"
$untracked | Select-Object -First 40 | ForEach-Object { "    $_" }

