$modified = @($porc | Where-Object { $_ -match '^ M| M ' -or $_ -match '^.M' })
"  modified=$($modified.Count)"
$modified | Select-Object -First 40 | ForEach-Object { "    $_" }

Write-Host ""
Write-Host "=== SIGNAL D: MEMORY.md size ==="
$sz = (Get-Item $mem).Length
"  bytes=$sz  cap=20480  OVER=$($sz -gt 20480)"

Write-Host ""
Write-Host "=== SIGNAL E: broken memory refs ==="
$mh = Join-Path $scripts 'memory-hygiene.ps1'
if (Test-Path $mh) {
  try {
    & pwsh -NoProfile -ExecutionPolicy Bypass -File $mh *> $null
    $stateF = 'C:\Users\mattm\.claude\projects\C--Users-mattm\memory\.memory-hygiene-state.json'
    if (Test-Path $stateF) {
      $s = Get-Content $stateF -Raw | ConvertFrom-Json
      $br = if ($s.PSObject.Properties.Name -contains 'brokenRefs') { $s.brokenRefs } else { $s.broken_refs }
      "  brokenRefs=$br"
    } else { "  hygiene ran, no state file" }
  } catch { "  memory-hygiene error: $($_.Exception.Message)" }
} else { "  memory-hygiene.ps1 NOT FOUND at $mh" }

Write-Host ""
Write-Host "=== SIGNAL F: large untracked collection (>15) ==="
"  untracked_count=$($untracked.Count)  triggers_batch=$($untracked.Count -gt 15)"

Write-Host ""
Write-Host "=== SIGNAL G: night-scheduled tasks 00:00-05:59 ==="
$night = @()
Get-ScheduledTask | Where-Object { $_.TaskName -match '^(Jarvis|JARVIS|Hermes|DP600|Loopify)-' } | ForEach-Object {
