1	<#
2	.SYNOPSIS
3	  loopctl -- registry + auto-deploy engine for engineered loops (the /loopify backend).
4	
5	.DESCRIPTION
6	  One control plane for every loop /loopify compiles, regardless of runner
7	  (local scheduled task, cloud routine, in-session, or Workflow fan-out). Keeps a
8	  single registry at ~/.claude/loops/registry.json so the whole fleet is visible
9	  and killable from one place.
10	
11	  ASCII-only + no PS7-only syntax so PS 5.1 scheduled tasks can call -Heartbeat.
12	
13	.PARAMETER Action
14	  Register | Deploy | List | Status | Remove | Heartbeat
15	
16	.EXAMPLES
17	  # Register + auto-deploy a local scheduled loop (daytime, battery-safe, shim pwsh):
18	  loopctl.ps1 -Action Register -Id fleet-digest -Goal "Daily loop-fleet health digest" `
19	      -Archetype scheduled-cadence -Runner local-scheduled `
20	      -RunnerPath C:\Users\mattm\.claude\loops\fleet-digest\run.ps1 `
21	      -Schedule "DAILY@10:00" -Deploy
22	
23	  loopctl.ps1 -Action List
24	  loopctl.ps1 -Action Status -Id fleet-digest
25	  loopctl.ps1 -Action Heartbeat -Id fleet-digest -State GREEN     # called by the runner
26	  loopctl.ps1 -Action Remove -Id fleet-digest -Purge             # unregister + delete task
27	#>
28	
29	[CmdletBinding()]
30	param(
31	    [Parameter(Mandatory)][ValidateSet('Register','Deploy','List','Status','Remove','Heartbeat')]
32	    [string] $Action,
33	    [string] $Id,
34	    [string] $Goal,
35	    [ValidateSet('dynamic','backlog-drain','discovery-drain','evaluator-optimizer','scheduled-cadence','fan-out-verify','maker-checker')]
36	    [string] $Archetype,
37	    [ValidateSet('local-scheduled','cloud','in-session','workflow')]
38	    [string] $Runner,
39	    [string] $RunnerPath,
40	    [string] $Schedule,          # e.g. "DAILY@10:00", "HOURLY", "WEEKLY:MON@10:00", or free-text for cloud
41	    [string] $KillCmd,
42	    [string] $StopCondition,
43	    [string] $BudgetCap,
44	    [ValidateSet('GREEN','RED','ERROR')]
45	    [string] $State,
46	    [string] $TimeLimit = 'PT20M',   # ExecutionTimeLimit for deployed tasks -- a hung runner
47	                                     # self-clears instead of holding the slot for schtasks' 72H default
48	    [switch] $Deploy,
49	    [switch] $Purge
50	)
51	
52	Set-StrictMode -Version Latest
53	$ErrorActionPreference = 'Stop'
54	
55	$LoopsDir    = Join-Path $env:USERPROFILE '.claude\loops'
56	$RegistryPath = Join-Path $LoopsDir 'registry.json'
57	$ShimPwsh    = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\pwsh.exe'
58	
59	function Get-Registry {
60	    if (-not (Test-Path $RegistryPath)) {
61	        return [ordered]@{ version = 1; loops = @() }
62	    }
63	    $raw = Get-Content $RegistryPath -Raw
64	    if ([string]::IsNullOrWhiteSpace($raw)) { return [ordered]@{ version = 1; loops = @() } }
65	    return ($raw | ConvertFrom-Json)
66	}
67	
68	function Save-Registry {
69	    param($Reg)
70	    if (-not (Test-Path $LoopsDir)) { New-Item -ItemType Directory -Path $LoopsDir -Force | Out-Null }
71	    $tmp = "$RegistryPath.tmp"
72	    ($Reg | ConvertTo-Json -Depth 8) | Set-Content -Path $tmp -Encoding UTF8
73	    Move-Item -Path $tmp -Destination $RegistryPath -Force
74	}
75	
76	function Get-LoopArray {
77	    param($Reg)
78	    # ConvertFrom-Json makes .loops a single object when there is exactly one entry.
79	    # The leading comma stops PowerShell unwrapping a single-element array on return
80	    # (otherwise a 1-entry registry returns a scalar and the Register concat throws).
81	    if ($null -eq $Reg.loops) { return ,@() }
82	    return ,@($Reg.loops)
83	}
84	
85	function NowUtc { (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
86	
87	function New-TaskTrigger-FromSchedule {
88	    # Translate the compact -Schedule grammar into schtasks.exe args. Returns a hashtable
89	    # with SC/ST/D pieces, or $null for non-scheduled runners.
90	    param([string] $Sched)
91	    if ([string]::IsNullOrWhiteSpace($Sched)) { return $null }
92	    $s = $Sched.Trim().ToUpper()
93	    $time = '10:00'
94	    $day  = $null
95	    if ($s -match '@(\d{1,2}:\d{2})') { $time = $Matches[1] }
96	    if ($s -match ':([A-Z]{3})')      { $day  = $Matches[1] }
97	    if     ($s -like 'HOURLY*')  { return @{ SC='HOURLY'; MO='1' } }
98	    elseif ($s -like 'DAILY*')   { return @{ SC='DAILY';  ST=$time } }
99	    elseif ($s -like 'WEEKLY*')  { return @{ SC='WEEKLY'; ST=$time; D=($day) } }
100	    else { return @{ SC='DAILY'; ST=$time } }   # safe default
101	}
102	
103	function Deploy-LocalScheduled {
104	    param($Loop)
105	    if ([string]::IsNullOrWhiteSpace($Loop.runner_path) -or -not (Test-Path $Loop.runner_path)) {
106	        throw "runner_path missing or not found: $($Loop.runner_path)"
107	    }
108	    $taskName = "Loopify-$($Loop.id)"
109	    $trig = New-TaskTrigger-FromSchedule $Loop.schedule
110	    if ($null -eq $trig) { throw "scheduled-cadence loop needs a -Schedule" }
111	    $exe = if (Test-Path $ShimPwsh) { $ShimPwsh } else { 'powershell.exe' }   # shim survives Store updates
112	    $tr  = "`"$exe`" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File `"$($Loop.runner_path)`""
113	
114	    $argList = @('/Create','/F','/TN',$taskName,'/TR',$tr,'/RL','LIMITED','/SC',$trig.SC)
115	    if ($trig.ContainsKey('ST')) { $argList += @('/ST',$trig.ST) }
116	    if ($trig.ContainsKey('MO')) { $argList += @('/MO',$trig.MO) }
117	    if ($trig.ContainsKey('D') -and $trig.D) { $argList += @('/D',$trig.D) }
118	    & schtasks.exe @argList | Out-Null
119	
120	    # Battery gate is on by default and silently refuses on battery (0x800710E0).
121	    # Clear it -- an unattended loop must run on battery. (windows-pitfalls INC-2.)
122	    try {
123	        $t = Get-ScheduledTask -TaskName $taskName -ErrorAction Stop
124	        $t.Settings.DisallowStartIfOnBatteries = $false
125	        $t.Settings.StopIfGoingOnBatteries     = $false
126	        # Bound runtime so a hung runner self-clears (schtasks defaults to PT72H, which
127	        # combined with MultipleInstances=IgnoreNew would block the schedule for 3 days).
128	        $t.Settings.ExecutionTimeLimit = $TimeLimit
129	        Set-ScheduledTask -TaskName $taskName -Settings $t.Settings | Out-Null
130	    } catch { Write-Warning "battery/time-limit set failed (non-fatal): $($_.Exception.Message)" }
131	    return $taskName
132	}
133	
134	switch ($Action) {
135	
136	  'Register' {
137	    if (-not $Id)        { throw "-Id required" }
138	    if (-not $Goal)      { throw "-Goal required" }
139	    if (-not $Archetype) { throw "-Archetype required" }
140	    if (-not $Runner)    { throw "-Runner required" }
141	    $reg = Get-Registry
142	    $loops = Get-LoopArray $reg
143	    if ($loops | Where-Object { $_.id -eq $Id }) { throw "loop id '$Id' already registered (Remove it first)" }
144	    $hbPath = Join-Path $LoopsDir "$Id\.heartbeat"
145	    $entry = [ordered]@{
146	        id             = $Id
147	        goal           = $Goal
148	        archetype      = $Archetype
149	        runner         = $Runner
150	        runner_path    = $RunnerPath
151	        schedule       = $Schedule
152	        stop_condition = $StopCondition
153	        budget_cap     = $BudgetCap
154	        kill_cmd       = $KillCmd
155	        task_name      = $null
156	        heartbeat_path = $hbPath
157	        status         = 'registered'
158	        created        = (NowUtc)
159	        last_heartbeat = $null
160	    }
161	    if ($Deploy -and $Runner -eq 'local-scheduled') {
162	        $entry.task_name = Deploy-LocalScheduled $entry
163	        $entry.status = 'deployed'
164	        if (-not $entry.kill_cmd) { $entry.kill_cmd = "schtasks /Delete /F /TN $($entry.task_name)" }
165	    } elseif ($Deploy) {
166	        Write-Warning "auto-deploy for runner '$Runner' is done by the agent (cloud=MCP trigger, in-session/workflow=direct); recorded as registered."
167	    }
168	    $reg.loops = @($loops + $entry)
169	    Save-Registry $reg
170	    "REGISTERED $Id [$Archetype/$Runner] status=$($entry.status)$(if($entry.task_name){" task=$($entry.task_name)"})"
171	  }
172	
173	  'Deploy' {
174	    if (-not $Id) { throw "-Id required" }
175	    $reg = Get-Registry; $loops = Get-LoopArray $reg
176	    $loop = $loops | Where-Object { $_.id -eq $Id }
177	    if (-not $loop) { throw "no loop '$Id'" }
178	    if ($loop.runner -ne 'local-scheduled') { throw "Deploy handles local-scheduled only; runner=$($loop.runner)" }
179	    $loop.task_name = Deploy-LocalScheduled $loop
180	    $loop.status = 'deployed'
181	    if (-not $loop.kill_cmd) { $loop.kill_cmd = "schtasks /Delete /F /TN $($loop.task_name)" }
182	    Save-Registry $reg
183	    "DEPLOYED $Id -> task $($loop.task_name)"
184	  }
185	
186	  'List' {
187	    $reg = Get-Registry; $loops = Get-LoopArray $reg
188	    if (-not $loops -or $loops.Count -eq 0) { "no loops registered"; break }
189	    $loops | ForEach-Object {
190	        [pscustomobject]@{
191	            id        = $_.id
192	            archetype = $_.archetype
193	            runner    = $_.runner
194	            status    = $_.status
195	            schedule  = $_.schedule
196	            lastHB    = $_.last_heartbeat
197	        }
198	    } | Format-Table -AutoSize
199	  }
200	
201	  'Status' {
202	    $reg = Get-Registry; $loops = Get-LoopArray $reg
203	    $sel = if ($Id) { $loops | Where-Object { $_.id -eq $Id } } else { $loops }
204	    if (-not $sel) { "no matching loop"; break }
205	    $sel | ForEach-Object { $_ | ConvertTo-Json -Depth 6 }
206	  }
207	
208	  'Remove' {
209	    if (-not $Id) { throw "-Id required" }
210	    $reg = Get-Registry; $loops = Get-LoopArray $reg
211	    $loop = $loops | Where-Object { $_.id -eq $Id }
212	    if (-not $loop) { throw "no loop '$Id'" }
213	    if ($Purge -and $loop.task_name) {
214	        try { & schtasks.exe /Delete /F /TN $loop.task_name | Out-Null; "deleted task $($loop.task_name)" }
215	        catch { Write-Warning "task delete failed: $($_.Exception.Message)" }
216	    }
217	    $reg.loops = @($loops | Where-Object { $_.id -ne $Id })
218	    Save-Registry $reg
219	    "REMOVED $Id$(if($Purge){' (+purged task)'})"
220	  }
221	
222	  'Heartbeat' {
223	    if (-not $Id)    { throw "-Id required" }
224	    if (-not $State) { throw "-State required (GREEN|RED|ERROR)" }
225	    # Append to the per-loop heartbeat file AND stamp the registry (best-effort, never throw).
226	    try {
227	        $dir = Join-Path $LoopsDir $Id
228	        if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
229	        Add-Content -Path (Join-Path $dir '.heartbeat') -Value ("{0}`t{1}" -f (NowUtc), $State) -Encoding UTF8
230	        $reg = Get-Registry; $loops = Get-LoopArray $reg
231	        $loop = $loops | Where-Object { $_.id -eq $Id }
232	        if ($loop) { $loop.last_heartbeat = "$(NowUtc) $State"; Save-Registry $reg }
233	    } catch { Write-Warning "heartbeat failed (non-fatal): $($_.Exception.Message)" }
234	  }
235	}
