1	<#
2	  loop-heal.ps1 -- self-healing layer for the loopctl loop ecosystem.
3	
4	  Stage A: a fault -> remediation catalog (Invoke-LoopHeal). Named remediators keyed
5	           to the fault signatures the fleet actually hits. SAFE/idempotent ops only;
6	           destructive or funding faults (engine restart, exhausted provider) return
7	           Escalate and DO NOTHING -- self-healing inherits the destructive-op gate.
8	  Stage B: an escalation-budget state machine (Register-LoopResult over
9	           ~/.claude/loops/<id>/heal-state.json). Transient fault -> retry on cadence;
10	           after K consecutive fails -> Escalate (page a human). No infinite retry.
11	
12	  Two ways to use it:
13	    Dot-source :  . C:\Users\mattm\scripts\loop-heal.ps1   (then call the functions)
14	    CLI/testing:  loop-heal.ps1 -Action Classify|Heal|Result|State|SelfTest ...
15	
16	  Design rules: ASCII-only, PS 5.1-safe, StrictMode-clean. A helper NEVER throws --
17	  telemetry/heal must not be able to kill a loop.
18	
19	  Decision vocabulary:
20	    OK        no fault / healthy
21	    Healed    a remediator actively repaired the cause
22	    Retry     transient; passive self-heal expected on next cadence (no action taken)
23	    Escalate  permanent / guarded / out-of-budget -> a human must act
24	    NoOp      nothing to do (missing target, benign)
25	    Skipped   -WhatIf dry-run (would act but did not)
26	#>
27	[CmdletBinding()]
28	param(
29	    [ValidateSet('Classify','Heal','Result','State','SelfTest')]
30	    [string] $Action,
31	    [string] $Id,
32	    [string] $Target,
33	    [string] $Fault,
34	    [ValidateSet('GREEN','RED','ERROR')]
35	    [string] $State,
36	    [int]    $Budget = 3,
37	    [switch] $WhatIf
38	)
39	
40	# NB: do NOT set Set-StrictMode at top level -- this file is dot-sourced by loop runners,
41	# and leaking StrictMode into their scope changes method-overload resolution (e.g. breaks
42	# [datetime]::TryParse(str,[ref]$null)). Strictness is enforced only in CLI mode below.
43	$script:LoopRoot = Join-Path $env:USERPROFILE '.claude\loops'
44	$script:Benign = @(0, 267009, 267010, 267011, 267014)   # ok / running / disabled / never-run / terminated (soft, non-actionable)
45	
46	function New-HealDecision {
47	    param([string] $Decision, [string] $Action, [int] $ConsecutiveFails = -1, [bool] $Escalate = $false)
48	    $o = [ordered]@{ decision = $Decision; action = $Action }
49	    if ($ConsecutiveFails -ge 0) { $o.consecutive_fails = $ConsecutiveFails; $o.escalate = $Escalate }
50	    return [pscustomobject]$o
51	}
52	
53	function Send-HealNote {
54	    param([string] $Text)
55	    $hook = $env:JARVIS_LOOP_WEBHOOK
56	    if ([string]::IsNullOrWhiteSpace($hook)) { return $false }
57	    try {
58	        $body = @{ content = "[loop-heal] $Text" } | ConvertTo-Json -Compress
59	        Invoke-RestMethod -Uri $hook -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 8 | Out-Null
60	        return $true
61	    } catch { return $false }
62	}
63	
64	# ---- Pure fault classifier (unit-testable; no live-task dependency) ------------
65	function ConvertTo-LoopFault {
66	    param(
67	        [long]   $LastResult = 0,
68	        [string] $TaskState = 'Ready',
69	        [bool]   $IsNight = $false,
70	        [bool]   $BatteryFlagSet = $false,
71	        [bool]   $HeartbeatStale = $false
72	    )
73	    # LONG literals (...L): a bare 0x800710E0 parses as a negative Int32 and 0xFFFFFFFF as
74	    # -1, so masking must use ...L to match the positive UInt32 Get-ScheduledTaskInfo returns.
75	    # 'Running' state is NOT a fault (a task mid-run is normal); 0x800710E0 is a battery gate
76	    # only when the task flag is actually set -- flag clear means the code is stale/self-clearing.
77	    $masked = [long]$LastResult -band 0xFFFFFFFFL
78	    if ($HeartbeatStale)         { return 'dead-loop' }
79	    if ($masked -eq 0x800710E0L) {
80	        if ($BatteryFlagSet)     { return 'battery-gate' }
81	        return 'stale-refusal'
82	    }
83	    if ($masked -eq 0xFFFD0000L) { return (if_night $IsNight) }
84	    if ($masked -eq 0x1)         { return 'worker-error' }
85	    if ($masked -eq 0x3)         { return 'dependency-down' }
86	    if ($script:Benign -contains $masked) { return 'none' }
87	    return 'unknown'
88	}
89	function if_night { param([bool]$n) if ($n) { 'night-wakefail' } else { 'wake-fail' } }
90	
91	# ---- Live-task classifier wrapper ----------------------------------------------
92	function Get-LoopFaultSignature {
93	    param([Parameter(Mandatory)][string] $TaskName)
94	    try {
95	        $t = Get-ScheduledTask -TaskName $TaskName -ErrorAction Stop
96	        $i = Get-ScheduledTaskInfo -TaskName $TaskName -ErrorAction Stop
97	    } catch { return 'unknown' }
98	    $isNight = $false
99	    foreach ($tr in $t.Triggers) { if ("$($tr.StartBoundary)" -match 'T0[0-5]:') { $isNight = $true } }
100	    $batFlag = $false
101	    try { $batFlag = [bool]$t.Settings.DisallowStartIfOnBatteries } catch { }
102	    return (ConvertTo-LoopFault -LastResult ([long]$i.LastTaskResult) -TaskState "$($t.State)" -IsNight $isNight -BatteryFlagSet $batFlag)
103	}
104	
105	# ---- Stage A: remediator dispatch ----------------------------------------------
106	function Invoke-LoopHeal {
107	    [CmdletBinding()]
108	    param(
109	        [Parameter(Mandatory)][string] $Fault,
110	        [string] $Target,
111	        [switch] $WhatIf
112	    )
113	    switch ($Fault) {
114	        'battery-gate' {
115	            if (-not $Target) { return (New-HealDecision 'NoOp' 'no target task given') }
116	            if ($WhatIf)      { return (New-HealDecision 'Skipped' "would clear battery flags on $Target") }
117	            try {
118	                $t = Get-ScheduledTask -TaskName $Target -ErrorAction Stop
119	                $t.Settings.DisallowStartIfOnBatteries = $false
120	                $t.Settings.StopIfGoingOnBatteries     = $false
121	                Set-ScheduledTask -TaskName $Target -Settings $t.Settings | Out-Null
122	                return (New-HealDecision 'Healed' "cleared battery flags on $Target")
123	            } catch { return (New-HealDecision 'Escalate' "battery clear failed: $($_.Exception.Message)") }
124	        }
125	        'hung-runner' {
126	            if (-not $Target) { return (New-HealDecision 'NoOp' 'no target task given') }
127	            if ($WhatIf)      { return (New-HealDecision 'Skipped' "would end hung instance + ensure ExecutionTimeLimit on $Target") }
128	            try {
129	                try { Stop-ScheduledTask -TaskName $Target -ErrorAction SilentlyContinue | Out-Null } catch { }
130	                $t = Get-ScheduledTask -TaskName $Target -ErrorAction Stop
131	                $lim = "$($t.Settings.ExecutionTimeLimit)"
132	                if ([string]::IsNullOrWhiteSpace($lim) -or $lim -eq 'PT0S') {
133	                    $t.Settings.ExecutionTimeLimit = 'PT20M'
134	                    Set-ScheduledTask -TaskName $Target -Settings $t.Settings | Out-Null
135	                }
136	                return (New-HealDecision 'Healed' "ended hung instance + ensured ExecutionTimeLimit on $Target")
137	            } catch { return (New-HealDecision 'Escalate' "hung-runner heal failed: $($_.Exception.Message)") }
138	        }
139	        'dead-loop' {
140	            if (-not $Target) { return (New-HealDecision 'NoOp' 'no target task given') }
141	            if ($WhatIf)      { return (New-HealDecision 'Skipped' "would re-run stalled task $Target") }
142	            try {
143	                Start-ScheduledTask -TaskName $Target -ErrorAction Stop
144	                return (New-HealDecision 'Healed' "re-ran stalled task $Target")
145	            } catch { return (New-HealDecision 'Escalate' "re-run failed: $($_.Exception.Message)") }
146	        }
147	        'dependency-down'    { return (New-HealDecision 'Retry'    'passive heal: cadence retry recovers when dependency returns') }
148	        'stale-refusal'      { return (New-HealDecision 'NoOp'     'transient 0x800710E0 (task flag clear) -- self-clears on next fire') }
149	        'wake-fail'          { return (New-HealDecision 'Escalate' 'wake-fail off-night: investigate machine sleep/wake') }
150	        'night-wakefail'     { return (New-HealDecision 'Escalate' 'reschedule to 09:00-11:00 or add a wake timer (intent-sensitive -- surface, do not auto-move)') }
151	        'worker-error'       { return (New-HealDecision 'Escalate' '0x1 worker error -- needs investigation') }
152	        'engine-down'        { return (New-HealDecision 'Escalate' 'guarded restart only -- never auto-restart engine/Hermes from a heal') }
153	        'dead-daemon'        { return (New-HealDecision 'Escalate' 'guarded restart only -- route to the daemon watchdog/runbook') }
154	        'provider-exhausted' { return (New-HealDecision 'Escalate' 'billing/funding is human-only (top-up or support case)') }
155	        'none'               { return (New-HealDecision 'NoOp'     'no fault') }
156	        default              { return (New-HealDecision 'Escalate' "unknown fault '$Fault'") }
157	    }
158	}
159	
160	# ---- Stage B: escalation-budget state ------------------------------------------
161	function Get-LoopHealState {
162	    param([Parameter(Mandatory)][string] $Id)
163	    $d = [pscustomobject]@{
164	        id=$Id; consecutive_fails=0; heal_attempts=0; last_state=''; last_fault=''; last_attempt_utc=''; escalated=$false
165	    }
166	    $p = Join-Path $script:LoopRoot "$Id\heal-state.json"
167	    if (-not (Test-Path $p)) { return $d }
168	    try {
169	        $j = Get-Content $p -Raw -ErrorAction Stop | ConvertFrom-Json
170	        foreach ($k in 'consecutive_fails','heal_attempts','last_state','last_fault','last_attempt_utc','escalated') {
171	            if ($j.PSObject.Properties.Name -contains $k) { $d.$k = $j.$k }
172	        }
173	    } catch { }
174	    return $d
175	}
176	
177	function Set-LoopHealState {
178	    param([Parameter(Mandatory)][string] $Id, [Parameter(Mandatory)][object] $StateObj)
179	    try {
180	        $dir = Join-Path $script:LoopRoot $Id
181	        if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
182	        $p = Join-Path $dir 'heal-state.json'
183	        $tmp = "$p.tmp"
184	        ($StateObj | ConvertTo-Json -Depth 5) | Set-Content -Path $tmp -Encoding UTF8
185	        Move-Item -Path $tmp -Destination $p -Force
186	        return $true
187	    } catch { return $false }
188	}
189	
190	function Register-LoopResult {
191	    <# Update the budget on each fire; return {decision, consecutive_fails, escalate}. #>
192	    param(
193	        [Parameter(Mandatory)][string] $Id,
194	        [Parameter(Mandatory)][ValidateSet('GREEN','RED','ERROR')][string] $State,
195	        [string] $Fault = '',
196	        [int] $Budget = 3
197	    )
198	    $s = Get-LoopHealState -Id $Id
199	    $s.last_state = $State
200	    $s.last_attempt_utc = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
201	    if ($State -eq 'GREEN') {
202	        $s.consecutive_fails = 0
203	        $s.last_fault = ''
204	        $s.escalated = $false
205	        Set-LoopHealState -Id $Id -StateObj $s | Out-Null
206	        return (New-HealDecision 'OK' 'green -- counter reset' 0 $false)
207	    }
208	    $s.consecutive_fails = [int]$s.consecutive_fails + 1
209	    if ($Fault) { $s.last_fault = $Fault }
210	    $escalate = ($s.consecutive_fails -ge $Budget)
211	    if ($escalate) { $s.escalated = $true }
212	    Set-LoopHealState -Id $Id -StateObj $s | Out-Null
213	    $dec = 'Retry'; if ($escalate) { $dec = 'Escalate' }
214	    return (New-HealDecision $dec "fail $($s.consecutive_fails)/$Budget (fault=$Fault)" $s.consecutive_fails $escalate)
215	}
216	
217	# ---- Self-test (verification) --------------------------------------------------
218	function Invoke-LoopHealSelfTest {
219	    $script:__stFail = 0
220	    function _assert { param([string]$Name,[bool]$Cond)
221	        if ($Cond) { Write-Host "  PASS  $Name" } else { Write-Host "  FAIL  $Name"; $script:__stFail++ }
222	    }
223	
224	    Write-Host 'ConvertTo-LoopFault:'
225	    _assert 'battery gate (0x800710E0 + flag SET)'  ((ConvertTo-LoopFault -LastResult 0x800710E0L -BatteryFlagSet $true) -eq 'battery-gate')
226	    _assert 'stale-refusal (0x800710E0 flag clear)' ((ConvertTo-LoopFault -LastResult 0x800710E0L -BatteryFlagSet $false) -eq 'stale-refusal')
227	    _assert 'REGRESSION UInt32 2147946720 flag-set -> battery-gate'   ((ConvertTo-LoopFault -LastResult 2147946720 -BatteryFlagSet $true) -eq 'battery-gate')
228	    _assert 'REGRESSION UInt32 2147946720 flag-clear -> stale-refusal' ((ConvertTo-LoopFault -LastResult 2147946720 -BatteryFlagSet $false) -eq 'stale-refusal')
229	    _assert 'night wake-fail (0xFFFD0000 night)'    ((ConvertTo-LoopFault -LastResult 0xFFFD0000L -IsNight $true) -eq 'night-wakefail')
230	    _assert 'REGRESSION UInt32 4294770688 night -> night-wakefail' ((ConvertTo-LoopFault -LastResult 4294770688 -IsNight $true) -eq 'night-wakefail')
231	    _assert 'wake-fail off-night (0xFFFD0000)'      ((ConvertTo-LoopFault -LastResult 0xFFFD0000L -IsNight $false) -eq 'wake-fail')
232	    _assert 'worker error (0x1)'                    ((ConvertTo-LoopFault -LastResult 0x1) -eq 'worker-error')
233	    _assert 'dependency down (0x3)'                 ((ConvertTo-LoopFault -LastResult 0x3) -eq 'dependency-down')
234	    _assert 'running task is NOT a fault -> none'   ((ConvertTo-LoopFault -TaskState 'Running' -LastResult 0) -eq 'none')
235	    _assert 'terminated 267014 -> none (soft)'      ((ConvertTo-LoopFault -LastResult 267014) -eq 'none')
236	    _assert 'disabled 267010 -> none (soft)'        ((ConvertTo-LoopFault -LastResult 267010) -eq 'none')
237	    _assert 'benign 0 -> none'                      ((ConvertTo-LoopFault -LastResult 0) -eq 'none')
238	    _assert 'stale heartbeat -> dead-loop'          ((ConvertTo-LoopFault -HeartbeatStale $true) -eq 'dead-loop')
239	    _assert 'garbage code -> unknown'               ((ConvertTo-LoopFault -LastResult 0x12345) -eq 'unknown')
240	
241	    Write-Host 'Invoke-LoopHeal (WhatIf / decision routing):'
242	    _assert 'battery-gate + target -> Skipped(WhatIf)' ((Invoke-LoopHeal -Fault 'battery-gate' -Target 'X' -WhatIf).decision -eq 'Skipped')
243	    _assert 'battery-gate no target -> NoOp'           ((Invoke-LoopHeal -Fault 'battery-gate' -WhatIf).decision -eq 'NoOp')
244	    _assert 'dead-loop + target -> Skipped(WhatIf)'    ((Invoke-LoopHeal -Fault 'dead-loop' -Target 'X' -WhatIf).decision -eq 'Skipped')
245	    _assert 'dependency-down -> Retry'                 ((Invoke-LoopHeal -Fault 'dependency-down' -WhatIf).decision -eq 'Retry')
246	    _assert 'stale-refusal -> NoOp'                    ((Invoke-LoopHeal -Fault 'stale-refusal' -WhatIf).decision -eq 'NoOp')
247	    _assert 'night-wakefail -> Escalate'               ((Invoke-LoopHeal -Fault 'night-wakefail' -WhatIf).decision -eq 'Escalate')
248	    _assert 'engine-down -> Escalate (guarded)'        ((Invoke-LoopHeal -Fault 'engine-down' -WhatIf).decision -eq 'Escalate')
249	    _assert 'provider-exhausted -> Escalate'           ((Invoke-LoopHeal -Fault 'provider-exhausted' -WhatIf).decision -eq 'Escalate')
250	    _assert 'none -> NoOp'                              ((Invoke-LoopHeal -Fault 'none' -WhatIf).decision -eq 'NoOp')
251	
252	    Write-Host 'Register-LoopResult (escalation budget, id=_healtest, budget=3):'
253	    $tid = '_healtest'
254	    $tdir = Join-Path $script:LoopRoot $tid
255	    if (Test-Path $tdir) { Remove-Item $tdir -Recurse -Force -ErrorAction SilentlyContinue }
256	    $r1 = Register-LoopResult -Id $tid -State RED -Fault 'worker-error' -Budget 3
257	    _assert 'RED #1 -> Retry, fails=1'   ($r1.decision -eq 'Retry' -and $r1.consecutive_fails -eq 1 -and -not $r1.escalate)
258	    $r2 = Register-LoopResult -Id $tid -State RED -Fault 'worker-error' -Budget 3
259	    _assert 'RED #2 -> Retry, fails=2'   ($r2.decision -eq 'Retry' -and $r2.consecutive_fails -eq 2 -and -not $r2.escalate)
260	    $r3 = Register-LoopResult -Id $tid -State RED -Fault 'worker-error' -Budget 3
261	    _assert 'RED #3 -> Escalate, fails=3'($r3.decision -eq 'Escalate' -and $r3.consecutive_fails -eq 3 -and $r3.escalate)
262	    $rg = Register-LoopResult -Id $tid -State GREEN -Budget 3
263	    _assert 'GREEN -> OK, counter reset' ($rg.decision -eq 'OK' -and $rg.consecutive_fails -eq 0)
264	    $persist = Get-LoopHealState -Id $tid
265	    _assert 'state persisted to disk'    ($persist.last_state -eq 'GREEN' -and $persist.consecutive_fails -eq 0)
266	    if (Test-Path $tdir) { Remove-Item $tdir -Recurse -Force -ErrorAction SilentlyContinue }
267	
268	    Write-Host ''
269	    if ($script:__stFail -eq 0) { Write-Host 'SELFTEST: ALL PASS' } else { Write-Host "SELFTEST: $($script:__stFail) FAILURE(S)" }
270	    return [int]$script:__stFail
271	}
272	
273	# ---- CLI dispatch (only when -Action is given; harmless when dot-sourced) -------
274	if ($Action) {
275	    Set-StrictMode -Version Latest   # enforce strictness in CLI mode; not leaked to dot-source callers
276	    switch ($Action) {
277	        'Classify' {
278	            if (-not $Target) { Write-Output 'need -Target <taskName>'; exit 2 }
279	            Write-Output (Get-LoopFaultSignature -TaskName $Target)
280	        }
281	        'Heal' {
282	            if (-not $Fault) { Write-Output 'need -Fault <signature>'; exit 2 }
283	            Write-Output ((Invoke-LoopHeal -Fault $Fault -Target $Target -WhatIf:$WhatIf) | ConvertTo-Json -Compress)
284	        }
285	        'Result' {
286	            if (-not $Id -or -not $State) { Write-Output 'need -Id <id> -State GREEN|RED|ERROR'; exit 2 }
287	            Write-Output ((Register-LoopResult -Id $Id -State $State -Fault $Fault -Budget $Budget) | ConvertTo-Json -Compress)
288	        }
289	        'State' {
290	            if (-not $Id) { Write-Output 'need -Id <id>'; exit 2 }
291	            Write-Output ((Get-LoopHealState -Id $Id) | ConvertTo-Json -Compress)
292	        }
293	        'SelfTest' {
294	            $rc = Invoke-LoopHealSelfTest
295	            exit $rc
296	        }
297	    }
298	}
