content.content:
1	<#
2	  loop-medic -- Stage C of the self-healing stack. Detect -> match -> HEAL -> re-verify,
3	  escalate to Amo ONLY when auto-heal fails or the fault is escalate-class. Closes the
4	  layer-4 gap: fleet-health only REPORTS stale/failing loops; the medic REVIVES them.
5	
6	  Companion, not duplicate: the medic HEALS (runs 09:30), fleet-health REPORTS the
7	  cleaner board (10:00). The medic never posts a routine digest -- it acts, then pings
8	  only on a heal-failure or an escalate-class fault.
9	
10	  SAFETY:
11	    * Default is DRY-RUN. Without -DoApply it mutates NOTHING -- it reports what it WOULD
12	      heal (Invoke-LoopHeal -WhatIf). Flip -DoApply to let it actually heal.
13	    * Only safe/idempotent remediators run (battery-gate, hung-runner, dead-loop).
14	      Destructive/funding faults return Escalate from loop-heal and are never auto-acted.
15	    * Claims the scheduled-tasks resource lock before any mutation (peer-safe).
16	    * Thrash guard: a target healed >= ThrashBudget times is escalated, not re-healed --
17	      a fault that won't stay fixed is a human problem, not a loop to paper over.
18	    * MaxHealsPerRun caps mutations per fire. Runtime cap + fail-closed + heartbeat.
19	
20	  Exit: 0 OK | 1 ERROR (RED + notify).  ASCII-only, PS 5.1-safe.
21	#>
22	[CmdletBinding()]
23	param(
24	    [string] $MedicId = 'loop-medic',
25	    [int]    $MaxRuntimeSec = 240,
26	    [switch] $DoApply,                 # OFF (default) = dry-run; ON = actually heal
27	    [int]    $MaxHealsPerRun = 6,
28	    [int]    $ThrashBudget = 3
29	)
30	$ErrorActionPreference = 'Stop'
31	$loopctl    = 'C:\Users\mattm\scripts\loopctl.ps1'
32	$loopHeal   = 'C:\Users\mattm\scripts\loop-heal.ps1'
33	$lockScript = 'C:\Users\mattm\scripts\claude-resource-lock.ps1'
34	$sw = [System.Diagnostics.Stopwatch]::StartNew()
35	
36	function Send-MedicNote {
37	    param([string] $Text)
38	    $hook = $env:JARVIS_LOOP_WEBHOOK
39	    if ([string]::IsNullOrWhiteSpace($hook)) { return }
40	    try {
41	        $body = @{ content = "[$MedicId] $Text" } | ConvertTo-Json -Compress
42	        Invoke-RestMethod -Uri $hook -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 10 | Out-Null
43	    } catch { }
44	}
45	
46	# Pure decision helper -- returns a bucket + message; caller owns the state.
47	function Get-HealAction {
48	    param(
49	        [string] $Sig, [string] $Target, [string] $Label,
50	        [bool] $Apply, [int] $HealCount, [int] $MaxHeals, [int] $Thrash, [hashtable] $Log
51	    )
52	    $count = 0
53	    if ($Log.ContainsKey($Target)) { $count = [int]$Log[$Target] }
54	    if ($count -ge $Thrash) {
55	        return [pscustomobject]@{ bucket='escalate'; msg="$Label ($Sig): auto-healed $count times already -- WON'T STAY HEALED, needs a human"; target=$Target }
56	    }
57	    if ($Apply -and $HealCount -lt $MaxHeals) {
58	        $r = Invoke-LoopHeal -Fault $Sig -Target $Target
59	        if ($r.decision -eq 'Healed') { return [pscustomobject]@{ bucket='healed'; msg="$Label ($Sig): $($r.action)"; target=$Target } }
60	        return [pscustomobject]@{ bucket='failed'; msg="$Label ($Sig): heal FAILED -- $($r.action)"; target=$Target }
61	    }
62	    $r = Invoke-LoopHeal -Fault $Sig -Target $Target -WhatIf
63	    return [pscustomobject]@{ bucket='would'; msg="$Label ($Sig): would $($r.action)"; target=$Target }
64	}
65	
66	# --- preflight ---------------------------------------------------------------
67	if (-not (Test-Path $loopHeal)) {
68	    try { & $loopctl -Action Heartbeat -Id $MedicId -State RED } catch { }
69	    Send-MedicNote "RED: preflight -- loop-heal.ps1 missing"
70	    Write-Error "preflight: $loopHeal missing"
71	    exit 1
72	}
73	. $loopHeal   # defines ConvertTo-LoopFault / Invoke-LoopHeal / etc. (also sets StrictMode)
74	
75	$medicDir = Join-Path $env:USERPROFILE ".claude\loops\$MedicId"
76	if (-not (Test-Path $medicDir)) { New-Item -ItemType Directory -Path $medicDir -Force | Out-Null }
77	$healLogPath = Join-Path $medicDir 'heal-log.json'
78	$healLog = @{}
79	if (Test-Path $healLogPath) {
80	    try { $j = Get-Content $healLogPath -Raw | ConvertFrom-Json
81	          foreach ($p in $j.PSObject.Properties) { $healLog[$p.Name] = [int]$p.Value } } catch { }
82	}
83	
84	$healed = New-Object System.Collections.Generic.List[string]
85	$would  = New-Object System.Collections.Generic.List[string]
86	$escal  = New-Object System.Collections.Generic.List[string]
87	$failed = New-Object System.Collections.Generic.List[string]
88	$healCount = 0
89	$lockHeld = $false
90	$autoHeal  = @('battery-gate','hung-runner','dead-loop')
91	$escalSigs = @('night-wakefail','wake-fail','worker-error','unknown')
92	
93	try {
94	    if ($DoApply -and (Test-Path $lockScript)) {
95	        try { & $lockScript -Claim scheduled-tasks -Reason "loop-medic auto-heal" | Out-Null; $lockHeld = $true }
96	        catch { $DoApply = $false; $escal.Add("could not claim scheduled-tasks lock -- ran DRY this fire") }
97	    }
98	
99	    # --- 1) failing scheduled tasks -----------------------------------------
100	    $tasks = Get-ScheduledTask | Where-Object { $_.TaskName -match '^(Jarvis|JARVIS|Hermes|DP600|Loopify)-' }
101	    foreach ($t in $tasks) {
102	        if ($sw.Elapsed.TotalSeconds -gt $MaxRuntimeSec) { throw "runtime cap $MaxRuntimeSec s exceeded" }
103	        if ($t.TaskName -eq "Loopify-$MedicId") { continue }
104	        $info = $null
105	        try { $info = Get-ScheduledTaskInfo -TaskName $t.TaskName -ErrorAction Stop } catch { }
106	        if (-not $info) { continue }
107	        $isNight = $false
108	        foreach ($tr in $t.Triggers) { if ("$($tr.StartBoundary)" -match 'T0[0-5]:') { $isNight = $true } }
109	        $batFlag = $false
110	        try { $batFlag = [bool]$t.Settings.DisallowStartIfOnBatteries } catch { }
111	        $sig = ConvertTo-LoopFault -LastResult ([long]$info.LastTaskResult) -TaskState "$($t.State)" -IsNight $isNight -BatteryFlagSet $batFlag
112	        # skip non-actionable: benign, passive-heal (dep-down), and stale/self-clearing refusals
113	        if ($sig -eq 'none' -or $sig -eq 'dependency-down' -or $sig -eq 'stale-refusal') { continue }
114	        if ($autoHeal -contains $sig) {
115	            $res = Get-HealAction -Sig $sig -Target $t.TaskName -Label $t.TaskName -Apply $DoApply -HealCount $healCount -MaxHeals $MaxHealsPerRun -Thrash $ThrashBudget -Log $healLog
116	            switch ($res.bucket) {
117	                'healed'   { $healed.Add($res.msg); $healCount++; $c=0; if ($healLog.ContainsKey($res.target)) { $c=[int]$healLog[$res.target] }; $healLog[$res.target]=$c+1 }
118	                'failed'   { $failed.Add($res.msg); $escal.Add($res.msg) }
119	                'would'    { $would.Add($res.msg) }
120	                'escalate' { $escal.Add($res.msg) }
121	            }
122	        }
123	        elseif ($escalSigs -contains $sig) {
124	            $escal.Add("$($t.TaskName) ($sig): escalate-class -- needs a human")
125	        }
126	    }
127	
128	    # --- 2) dead / red loops in the loopctl registry ------------------------
129	    $regPath = Join-Path $env:USERPROFILE '.claude\loops\registry.json'
130	    if (Test-Path $regPath) {
131	        $reg = Get-Content $regPath -Raw | ConvertFrom-Json
132	        foreach ($l in @($reg.loops)) {
133	            if ($null -eq $l) { continue }
134	            if (-not ($l.PSObject.Properties.Name -contains 'id')) { continue }
135	            if ($l.id -eq $MedicId) { continue }
136	            $status = if ($l.PSObject.Properties.Name -contains 'status') { "$($l.status)" } else { '' }
137	            if ($status -ne 'deployed') { continue }
138	            $hb = if ($l.PSObject.Properties.Name -contains 'last_heartbeat') { "$($l.last_heartbeat)" } else { '' }
139	            if ($hb -match 'RED|ERROR') { $escal.Add("loop $($l.id): heartbeat $hb -- failing its own work, needs a human"); continue }
140	            $stale = $false
141	            if ($hb) {
142	                $stamp = ($hb -split ' ')[0]; $dt = $null
143	                try { $dt = [datetime]::Parse($stamp) } catch { $dt = $null }
144	                if ($dt -and ((Get-Date).ToUniversalTime() - $dt.ToUniversalTime()).TotalHours -gt 26) { $stale = $true }
145	            } else { $stale = $true }
146	            if (-not $stale) { continue }
147	            $target = "Loopify-$($l.id)"
148	            if (-not (Get-ScheduledTask -TaskName $target -ErrorAction SilentlyContinue)) {
149	                $escal.Add("loop $($l.id): stale hb '$hb' and no task $target to re-run -- needs a human"); continue
150	            }
151	            $res = Get-HealAction -Sig 'dead-loop' -Target $target -Label "loop $($l.id)" -Apply $DoApply -HealCount $healCount -MaxHeals $MaxHealsPerRun -Thrash $ThrashBudget -Log $healLog
152	            switch ($res.bucket) {
153	                'healed'   { $healed.Add($res.msg); $healCount++; $c=0; if ($healLog.ContainsKey($res.target)) { $c=[int]$healLog[$res.target] }; $healLog[$res.target]=$c+1 }
154	                'failed'   { $failed.Add($res.msg); $escal.Add($res.msg) }
155	                'would'    { $would.Add($res.msg) }
156	                'escalate' { $escal.Add($res.msg) }
157	            }
158	        }
159	    }
160	
161	    # --- persist heal-log + write report ------------------------------------
162	    try { ($healLog | ConvertTo-Json -Depth 3) | Set-Content -Path $healLogPath -Encoding UTF8 } catch { }
163	    $mode = if ($DoApply) { 'APPLY' } else { 'DRY-RUN' }
164	    $stamp = (Get-Date).ToString('yyyy-MM-dd HH:mm')
165	    $reportPath = Join-Path $medicDir ("report-{0}.md" -f (Get-Date).ToString('yyyy-MM-dd'))
166	    $lines = New-Object System.Collections.Generic.List[string]
167	    $lines.Add("# loop-medic -- $stamp  [$mode]")
168	    $lines.Add('')
169	    $lines.Add("## Healed -- $($healed.Count)")
170	    if ($healed.Count -eq 0) { $lines.Add('- none') } else { $healed | ForEach-Object { $lines.Add("- $_") } }
171	    $lines.Add('')
172	    $lines.Add("## Would heal (dry / over-cap) -- $($would.Count)")
173	    if ($would.Count -eq 0) { $lines.Add('- none') } else { $would | ForEach-Object { $lines.Add("- $_") } }
174	    $lines.Add('')
175	    $lines.Add("## Escalate to human -- $($escal.Count)")
176	    if ($escal.Count -eq 0) { $lines.Add('- none') } else { $escal | ForEach-Object { $lines.Add("- $_") } }
177	    ($lines -join "`r`n") | Set-Content -Path $reportPath -Encoding UTF8
178	
179	    if ($lockHeld) { try { & $lockScript -Release scheduled-tasks | Out-Null } catch { } }
180	
181	    if ($failed.Count -gt 0 -or $escal.Count -gt 0) {
182	        Send-MedicNote ("[$mode] healed $($healed.Count), would $($would.Count), ESCALATE $($escal.Count). See $reportPath")
183	    }
184	    & $loopctl -Action Heartbeat -Id $MedicId -State GREEN
185	    Write-Output ("loop-medic [$mode] OK: healed=$($healed.Count) would=$($would.Count) escalate=$($escal.Count) report=$reportPath")
186	    exit 0
187	}
188	catch {
189	    $msg = $_.Exception.Message
190	    if ($lockHeld) { try { & $lockScript -Release scheduled-tasks | Out-Null } catch { } }
191	    try { & $loopctl -Action Heartbeat -Id $MedicId -State RED } catch { }
192	    Send-MedicNote "RED: $msg"
193	    Write-Error "loop-medic FAILED: $msg"
194	    exit 1
195	}
196

