122	# Release sleep prevention
123	try { [PowerMgmt]::SetThreadExecutionState([PowerMgmt]::ES_CONTINUOUS) | Out-Null } catch {}
124	
125	# Exit non-zero only on a GENUINE required-task failure.
126	#
127	# A still-running task at the orchestrator deadline returns state='TIMEOUT'. That is NOT a
128	# failure: each pipeline runs on its own cadence and finishes async (Files ~11 min; OneNote
129	# can run hours), and this orchestrator is a belt-and-suspenders trigger, not a gate. The
130	# hourly Jarvis-VaultGbrainSync + the verify-jarvis-tasks sweep catch a genuinely stuck or
131	# failed sub-task independently. Treating TIMEOUT as fatal produced false 0x1 exits
132	# (2026-06-30: files=TIMEOUT while the standalone Jarvis-VaultIngest-Files task succeeded
133	# 0x0). So TIMEOUT on a required task is now a soft warning.
134	#
135	# A genuine required failure is: couldn't start (TASK_MISSING/START_FAILED/MISSING), the
136	# daemon sync hard-failed (gbrain-sync FAILED), or a sub-task reached a terminal state with a
137	# nonzero LastTaskResult. The previous predicate missed terminal+nonzero entirely ('Ready'
138	# was not in the fail set), so real failures slipped through while TIMEOUT false-tripped.
139	$timedOut = @($results | Where-Object { $_.state -eq 'TIMEOUT' -and -not $_.optional })
