141	    Write-Host "WARN: required task '$($w.source)' still running at ${PerTaskTimeoutMin}m deadline; it completes on its own cadence (not a roll-up failure)."
142	}
143	$failed = @($results | Where-Object {
144	    if ($_.optional) { $false }
145	    elseif ($_.state -in @('TASK_MISSING', 'START_FAILED', 'MISSING', 'FAILED')) { $true }
146	    elseif ($_.state -in @('TIMEOUT', 'OK', 'DAEMON_DOWN')) { $false }
147	    else { ($null -ne $_.result -and $_.result -ne 0) }
148	})
149	if ($failed.Count -gt 0) {
150	    Write-Host ('Required failures: ' + (($failed | ForEach-Object { "$($_.source)=$($_.state):$($_.result)" }) -join ', '))
151	    exit 1
152	}
153	exit 0
