  <Query Id="0" Path="Microsoft-Windows-TaskScheduler/Operational">
    <Select Path="Microsoft-Windows-TaskScheduler/Operational">
      *[EventData[Data[@Name='TaskName']='\Jarvis-VaultIngest-All']]
      and *[System[(EventID=102 or EventID=103 or EventID=201 or EventID=203)]]
    </Select>
  </Query>
</QueryList>
"@
try {
  Get-WinEvent -FilterXml $xml -MaxEvents 40 -ErrorAction Stop |
    Sort-Object TimeCreated |
    ForEach-Object {
      $rc = ''
      if ($_.Id -in 201,203) { try { $rc = " result=0x{0:X}" -f [int64]$_.Properties[3].Value } catch { $rc = " result=$($_.Properties[3].Value)" } }
      "{0}  id={1}  {2}{3}" -f $_.TimeCreated.ToString('MM-dd HH:mm:ss'), $_.Id, $_.LevelDisplayName, $rc
    } | Select-Object -Last 30
} catch { "event query failed: $($_.Exception.Message)" }

# Reconstruct the 06/30 roll-up results and run the EXACT $failed predicate from the script
$results = @(
  @{ source='files';       state='TIMEOUT'; result=$null; optional=$false }
  @{ source='discord';     state='Ready';   result=0;     optional=$false }
  @{ source='x-bookmarks'; state='Ready';   result=0;     optional=$true  }
  @{ source='onenote';     state='TIMEOUT'; result=$null; optional=$true  }
  @{ source='gbrain-sync'; state='OK';      result=0;     optional=$false }
)
$failed = @($results | Where-Object {
    if ($_.optional) { $false }
    elseif ($_.state -in @('TASK_MISSING','START_FAILED','MISSING','FAILED')) { $true }
    elseif ($_.state -in @('TIMEOUT','OK','DAEMON_DOWN')) { $false }
    else { ($null -ne $_.result -and $_.result -ne 0) }
})
"failed.Count = $($failed.Count)  ->  predicate would 'exit {0}'" -f ($(if($failed.Count -gt 0){1}else{0}))
"So the recorded roll-up should have exited 0; the actual 0x1 came from OUTSIDE the predicate (out-of-band terminating error after the status write, or a process-level error)."

