  $wi = Get-ScheduledTaskInfo -TaskName JARVIS-BrainDaemon-Watchdog
  "LastRunTime=$($wi.LastRunTime)  LastResult=0x{0:X}  NextRunTime=$($wi.NextRunTime)" -f $wi.LastTaskResult
} else { "watchdog task not found" }
Write-Host ""
Write-Host "===== current time + current daemon uptime ====="
"now: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
try { $h = Invoke-RestMethod 'http://127.0.0.1:8077/health' -TimeoutSec 5; "daemon uptime_s=$($h.uptime_s)  pid=$($h.pid)" } catch { "health probe failed: $($_.Exception.Message)" }
Write-Host ""
