$sw=[Diagnostics.Stopwatch]::StartNew()
try { $h2 = Invoke-RestMethod 'http://127.0.0.1:8077/health?deep=1' -TimeoutSec 15; "deep=1 took $($sw.ElapsedMilliseconds)ms  ok=$($h2.ok) spawn.ok=$($h2.spawn.ok)" } catch { "deep probe failed after $($sw.ElapsedMilliseconds)ms: $($_.Exception.Message)" }

