/**
 * gbrain brain daemon (M1 read-path + M3 write-path) — the single-writer brain service.
 *
 * WHY: PGlite is a single-connection embedded Postgres. N processes opening the same dataDir →
 * Aborted() → corruption; today that's guarded by an advisory lock that this whole class of bugs
 * keeps slipping past. This daemon DELETES the condition: it is the ONLY process that ever opens
 * the brain. It connects once, holds the lock for its entire lifetime, and serializes every DB
 * operation through a single promise chain so the one connection never sees overlapping queries.
 * Clients (the gbrain CLI via SocketEngine, the Python semantic_search, the sync jobs) talk to it
 * over localhost HTTP and never open the DB themselves.
 *
 * M3 (write path): the daemon owns the embedding credential (GBRAIN_EMBED_* / Voyage), so it runs
 * gbrain's OWN import/embed pipeline IN-PROCESS against its own connection — clients POST text/dirs
 * to /ingest and never hold the key or the lock. Because EVERY engine access (endpoint reads AND
 * ingest's internal writes) is funnelled through the one serialize() chain, a long ingest interleaves
 * safely with /search and /health: the single connection still never sees overlapping queries, yet
 * liveness polling stays responsive (each op is ~ms, queued not blocked).
 *
 * /health is NON-mutating, so liveness can be polled without the "checking the brain corrupts the
 * brain" hazard. /search embeds server-side — clients send TEXT, never keys.
 *
 * RUN:  bun run src/daemon-server.ts <brain-dir>     (or set GBRAIN_DATABASE_PATH)
 *       env: GBRAIN_EMBED_* (model/dim/key — key from the DPAPI secret store via the launcher),
 *            GBRAIN_DAEMON_PORT (default 8077), GBRAIN_DAEMON_TOKEN (optional bearer guard).
 */
import { writeFileSync, unlinkSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { dirname, join } from 'node:path';
import { PGLiteEngine } from './core/pglite-engine.ts';
import { hybridSearch, type HybridSearchOpts } from './core/search/hybrid.ts';
import { runEmbed } from './commands/embed.ts';
import { runImport } from './commands/import.ts';
import { performSync, type SyncResult } from './commands/sync.ts';
import type { BrainEngine } from './core/engine.ts';

const PORT = parseInt(process.env.GBRAIN_DAEMON_PORT || '8077', 10);
const HOST = process.env.GBRAIN_DAEMON_HOST || '127.0.0.1';
const TOKEN = process.env.GBRAIN_DAEMON_TOKEN || '';
const dataDir = process.env.GBRAIN_DATABASE_PATH || process.argv[2];

if (!dataDir) { console.error('FATAL: set GBRAIN_DATABASE_PATH or pass the brain dir as argv[2]'); process.exit(2); }

const rawEngine = new PGLiteEngine();
console.error(`[braind] connecting ${dataDir} ...`);
await rawEngine.connect({ engine: 'pglite', database_path: dataDir });
const startedAt = Date.now();
console.error(`[braind] connected, lock held for process life. embed model=${process.env.GBRAIN_EMBED_MODEL} dim=${process.env.GBRAIN_EMBED_DIMENSIONS}`);

// File-based liveness + health markers so "is the brain safe to touch right now?" is answerable
// from disk, not only via the live port. markerDir is the brain's parent dir (~/.gbrain-trading).
// The daemon connecting successfully PROVES it holds the single PGlite lock, so writing the lock
// file here is authoritative — a stale file from a crashed prior daemon is correctly overwritten.
const markerDir = dirname(dataDir);
const lockFile = join(markerDir, 'daemon-lock.json');
const healthFile = join(markerDir, 'brain-health.json');
try {
  writeFileSync(lockFile, JSON.stringify({
    pid: process.pid, started_iso: new Date(startedAt).toISOString(), port: PORT, data_dir: dataDir,
  }, null, 2));
  console.error(`[braind] wrote liveness lock ${lockFile}`);

