61	} catch (e) { console.error('[braind] lock write failed', e); }
62	
63	// Single-writer serialization: every engine access runs through ONE promise chain, so the single
64	// PGlite connection never sees overlapping queries. This is the invariant that deletes the
65	// corruption class — not a lock guarding against it, but a structure where it cannot occur.
66	let chain: Promise<unknown> = Promise.resolve();
67	function serialize<T>(fn: () => Promise<T>): Promise<T> {
68	  const run = chain.then(fn, fn) as Promise<T>;
69	  chain = run.then(() => {}, () => {});
70	  return run;
71	}
72	
73	// Funnel EVERY engine method through serialize() — whether called by an endpoint or by the in-process
74	// runImport/runEmbed pipeline. `transaction` is special-cased: the WHOLE transaction is one slot, and
75	// the user fn receives the RAW tx-engine (not the proxy) so its inner tx.* calls run directly inside
76	// the transaction instead of re-entering serialize() and deadlocking on the chain it already holds.
77	function serializingEngine(target: BrainEngine): BrainEngine {
78	  return new Proxy(target, {
79	    get(t, prop, recv) {
80	      const v = Reflect.get(t, prop, recv);
81	      if (typeof v !== 'function') return v;
82	      if (prop === 'transaction') {
83	        return <T>(fn: (e: BrainEngine) => Promise<T>): Promise<T> =>
84	          serialize(() => (t.transaction as (f: (e: BrainEngine) => Promise<T>) => Promise<T>)(fn));
85	      }
86	      return (...args: unknown[]) =>
87	        serialize(() => (v as (...a: unknown[]) => Promise<unknown>).apply(t, args));
88	    },
89	  }) as BrainEngine;
90	}
91	const engine = serializingEngine(rawEngine);
92	
93	// Cheap child-spawn liveness check. A daemon whose working directory was deleted stays up with /health
94	// ok (HTTP + PGlite both fine) but can no longer spawn child processes -- on Windows, CreateProcess
95	// can't resolve a dead cwd -- so /sync's git ops all fail (observed 2026-05-30). A plain /health can't
96	// see this; exposing spawn capability (behind ?deep=1, so frequent cheap probes stay cheap) lets the
97	// watchdog heal a spawn-dead daemon, not just a down/wedged one. git --version is ~tens of ms.
98	function spawnProbe(): { ok: boolean; error?: string } {
99	  try {
100	    // Use Bun's native spawn: once PGLite's WASM is loaded, Node-compat execFileSync
101	    // is wedged and returns a spurious ETIMEDOUT for every spawn (see git() in
102	    // commands/sync.ts). A probe that used execFileSync would report spawn-dead even
103	    // though the daemon CAN spawn via Bun.spawnSync, making the watchdog churn.
104	    const B = (globalThis as { Bun?: { spawnSync: (cmd: string[], o?: unknown) => { success: boolean; exitCode: number } } }).Bun;
105	    if (B && typeof B.spawnSync === 'function') {
106	      const p = B.spawnSync(['git', '--version'], { stdout: 'ignore', stderr: 'ignore' });
107	      return p.success ? { ok: true } : { ok: false, error: `git --version exited ${p.exitCode}` };
108	    }
109	    execFileSync('git', ['--version'], { timeout: 3000, stdio: 'ignore' });
110	    return { ok: true };
111	  } catch (e: unknown) {
112	    return { ok: false, error: e instanceof Error ? e.message : String(e) };
113	  }
114	}
115	
116	// Stamp the on-disk health marker after a clean ingest, so a checker can read coverage/freshness
117	// WITHOUT opening the DB. Mirrors the schema safe-embed.ps1 writes. Never throws into the caller.
118	async function stampHealth(phase: string) {
119	  try {
120	    const s = await engine.getStats() as { chunk_count?: number; embedded_count?: number };
121	    const chunks = s.chunk_count ?? 0;
122	    const embedded = s.embedded_count ?? 0;
123	    writeFileSync(healthFile, JSON.stringify({
124	      model: process.env.GBRAIN_EMBED_MODEL || null,
125	      dim: process.env.GBRAIN_EMBED_DIMENSIONS || null,
126	      chunks, embedded,
127	      coverage_pct: chunks > 0 ? Math.round((embedded / chunks) * 1000) / 10 : 0,
128	      last_embed_exit: 0,
129	      last_embed_iso: new Date().toISOString(),
130	      source: `daemon ${phase}`,
131	    }, null, 2));
132	  } catch (e) { console.error('[braind] health stamp failed', e); }
133	}
