// Single-writer serialization: every engine access runs through ONE promise chain, so the single
// PGlite connection never sees overlapping queries. This is the invariant that deletes the
// corruption class — not a lock guarding against it, but a structure where it cannot occur.
let chain: Promise<unknown> = Promise.resolve();
function serialize<T>(fn: () => Promise<T>): Promise<T> {
  const run = chain.then(fn, fn) as Promise<T>;
  chain = run.then(() => {}, () => {});
  return run;
}

// Funnel EVERY engine method through serialize() — whether called by an endpoint or by the in-process
// runImport/runEmbed pipeline. `transaction` is special-cased: the WHOLE transaction is one slot, and
// the user fn receives the RAW tx-engine (not the proxy) so its inner tx.* calls run directly inside
// the transaction instead of re-entering serialize() and deadlocking on the chain it already holds.
function serializingEngine(target: BrainEngine): BrainEngine {
  return new Proxy(target, {
    get(t, prop, recv) {
      const v = Reflect.get(t, prop, recv);
      if (typeof v !== 'function') return v;
      if (prop === 'transaction') {
        return <T>(fn: (e: BrainEngine) => Promise<T>): Promise<T> =>
          serialize(() => (t.transaction as (f: (e: BrainEngine) => Promise<T>) => Promise<T>)(fn));
      }
      return (...args: unknown[]) =>
        serialize(() => (v as (...a: unknown[]) => Promise<unknown>).apply(t, args));
    },
  }) as BrainEngine;
}
const engine = serializingEngine(rawEngine);

// Cheap child-spawn liveness check. A daemon whose working directory was deleted stays up with /health
// ok (HTTP + PGlite both fine) but can no longer spawn child processes -- on Windows, CreateProcess
// can't resolve a dead cwd -- so /sync's git ops all fail (observed 2026-05-30). A plain /health can't
// see this; exposing spawn capability (behind ?deep=1, so frequent cheap probes stay cheap) lets the
// watchdog heal a spawn-dead daemon, not just a down/wedged one. git --version is ~tens of ms.
function spawnProbe(): { ok: boolean; error?: string } {
  try {
    // Use Bun's native spawn: once PGLite's WASM is loaded, Node-compat execFileSync
    // is wedged and returns a spurious ETIMEDOUT for every spawn (see git() in
    // commands/sync.ts). A probe that used execFileSync would report spawn-dead even
    // though the daemon CAN spawn via Bun.spawnSync, making the watchdog churn.
    const B = (globalThis as { Bun?: { spawnSync: (cmd: string[], o?: unknown) => { success: boolean; exitCode: number } } }).Bun;
    if (B && typeof B.spawnSync === 'function') {
      const p = B.spawnSync(['git', '--version'], { stdout: 'ignore', stderr: 'ignore' });
      return p.success ? { ok: true } : { ok: false, error: `git --version exited ${p.exitCode}` };
    }
    execFileSync('git', ['--version'], { timeout: 3000, stdio: 'ignore' });
    return { ok: true };
  } catch (e: unknown) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}

// Stamp the on-disk health marker after a clean ingest, so a checker can read coverage/freshness
// WITHOUT opening the DB. Mirrors the schema safe-embed.ps1 writes. Never throws into the caller.
async function stampHealth(phase: string) {
  try {
    const s = await engine.getStats() as { chunk_count?: number; embedded_count?: number };
    const chunks = s.chunk_count ?? 0;
    const embedded = s.embedded_count ?? 0;
    writeFileSync(healthFile, JSON.stringify({
      model: process.env.GBRAIN_EMBED_MODEL || null,
      dim: process.env.GBRAIN_EMBED_DIMENSIONS || null,
      chunks, embedded,
      coverage_pct: chunks > 0 ? Math.round((embedded / chunks) * 1000) / 10 : 0,
      last_embed_exit: 0,
      last_embed_iso: new Date().toISOString(),
      source: `daemon ${phase}`,
    }, null, 2));
  } catch (e) { console.error('[braind] health stamp failed', e); }
}

