const url = new URL(req.url);
if (!authOK(req)) return json({ error: 'unauthorized' }, 401);
try {
  if (url.pathname === '/health') {
    // Each engine call serializes individually, so /health stays responsive even mid-ingest.
    // ?deep=1 adds a child-spawn probe (git --version): a spawn-dead daemon (deleted cwd) answers
    // /health ok but can't run /sync -- the watchdog uses deep=1 to detect + heal that. Plain
    // /health stays cheap for the bridge's frequent liveness probes.
    const deep = url.searchParams.get('deep') === '1';
    const health = await engine.getHealth();
    const stats = await engine.getStats();
    return json({
      ok: true,
      pid: process.pid,
      uptime_s: Math.round((Date.now() - startedAt) / 1000),
      data_dir: dataDir,
      embed: { model: process.env.GBRAIN_EMBED_MODEL || null, dim: parseInt(process.env.GBRAIN_EMBED_DIMENSIONS || '0', 10) },
      ingest: ingestStatus(),
      spawn: deep ? spawnProbe() : null,
      health, stats,
    });
  }
  if (url.pathname === '/search' && req.method === 'POST') {
    const body = await req.json() as { query?: string; opts?: HybridSearchOpts };
    if (!body.query) return json({ error: 'missing query' }, 400);
    const results = await hybridSearch(engine, body.query, body.opts);
    return json({ query: body.query, count: results.length, results });
  }
  if (url.pathname.startsWith('/pages/') && req.method === 'GET') {
    const slug = decodeURIComponent(url.pathname.slice('/pages/'.length));
    const page = await engine.getPage(slug);
    return page ? json({ page }) : json({ error: 'not found', slug }, 404);
  }
  if (url.pathname === '/ingest' && req.method === 'GET') {
    return json(ingestStatus());
  }
  if (url.pathname === '/ingest' && req.method === 'POST') {
    if (ingest.running) return json({ error: 'ingest already running', status: ingestStatus() }, 409);
    const body = await req.json().catch(() => ({})) as { raw_dir?: string; embed?: 'all' | 'stale'; no_embed?: boolean };
    if (!body.raw_dir && !body.embed) return json({ error: 'specify raw_dir and/or embed ("all"|"stale")' }, 400);

