const server = Bun.serve({
  port: PORT,
  hostname: HOST,
  async fetch(req) {
    const url = new URL(req.url);
    if (!authOK(req)) return json({ error: 'unauthorized' }, 401);
    try {
      if (url.pathname === '/health') {
        // Each engine call serializes individually, so /health stays responsive even mid-ingest.
        // ?deep=1 adds a child-spawn probe (git --version): a spawn-dead daemon (deleted cwd) answers
        // /health ok but can't run /sync -- the watchdog uses deep=1 to detect + heal that. Plain
        // /health stays cheap for the bridge's frequent liveness probes.
        const deep = url.searchParams.get('deep') === '1';
        const health = await engine.getHealth();
        const stats = await engine.getStats();
        return json({
          ok: true,
          pid: process.pid,
          uptime_s: Math.round((Date.now() - startedAt) / 1000),
          data_dir: dataDir,
          embed: { model: process.env.GBRAIN_EMBED_MODEL || null, dim: parseInt(process.env.GBRAIN_EMBED_DIMENSIONS || '0', 10) },
          ingest: ingestStatus(),
          spawn: deep ? spawnProbe() : null,
          health, stats,
        });
      }
      if (url.pathname === '/search' && req.method === 'POST') {
        const body = await req.json() as { query?: string; opts?: HybridSearchOpts };
        if (!body.query) return json({ error: 'missing query' }, 400);
        const results = await hybridSearch(engine, body.query, body.opts);
        return json({ query: body.query, count: results.length, results });
      }
      if (url.pathname.startsWith('/pages/') && req.method === 'GET') {
        const slug = decodeURIComponent(url.pathname.slice('/pages/'.length));
        const page = await engine.getPage(slug);
        return page ? json({ page }) : json({ error: 'not found', slug }, 404);
      }
      if (url.pathname === '/ingest' && req.method === 'GET') {
        return json(ingestStatus());
      }
      if (url.pathname === '/ingest' && req.method === 'POST') {
        if (ingest.running) return json({ error: 'ingest already running', status: ingestStatus() }, 409);
        const body = await req.json().catch(() => ({})) as { raw_dir?: string; embed?: 'all' | 'stale'; no_embed?: boolean };
        if (!body.raw_dir && !body.embed) return json({ error: 'specify raw_dir and/or embed ("all"|"stale")' }, 400);
        // Kick off async; the long op interleaves with reads via serialize(). Return 202 + status.
        void runIngest(body);
        return json({ accepted: true, status: ingestStatus() }, 202);
      }
      if (url.pathname === '/sync' && req.method === 'POST') {
        // Git-incremental repo sync (the autonomous vault->brain write path). Single-flight via the
        // shared `ingest` state; poll completion at GET /ingest. dry_run computes the changeset without
        // writing. A non-ancestor/missing anchor (which would full-reimport) is refused unless allow_full.
        if (ingest.running) return json({ error: 'ingest/sync already running', status: ingestStatus() }, 409);
        const body = await req.json().catch(() => ({})) as { repo?: string; full?: boolean; dry_run?: boolean; no_embed?: boolean; allow_full?: boolean };
        if (!body.repo) return json({ error: 'specify repo (path to a git-initialized brain repo)' }, 400);
        void runIngest({ sync_repo: body.repo, full: body.full, dry_run: body.dry_run, no_embed: body.no_embed, allow_full: body.allow_full });
        return json({ accepted: true, mode: body.dry_run ? 'dry_run' : 'sync', status: ingestStatus() }, 202);
      }
      if (url.pathname === '/rpc' && req.method === 'POST') {
        const { method, args } = await req.json() as { method?: string; args?: unknown[] };
        if (!method || (!READ_METHODS.has(method) && !WRITE_METHODS.has(method))) {
          return json({ error: `method '${method}' not allowed (read: ${[...READ_METHODS].length}, write: ${[...WRITE_METHODS].length})` }, 403);
        }
        const result = await (engine as unknown as Record<string, (...a: unknown[]) => Promise<unknown>>)[method](...(args || []));
        return json({ result });
      }
      return json({ error: 'not found', path: url.pathname }, 404);
    } catch (e: unknown) {
      return json({ error: (e instanceof Error ? e.message : String(e)) }, 500);
    }
  },
});

console.error(`[braind] listening http://${HOST}:${PORT}  (token ${TOKEN ? 'required' : 'OFF: localhost-only'})  [M1 read + M3 write]`);

async function shutdown(sig: string) {
  console.error(`[braind] ${sig} -> stop + release lock`);
  try { unlinkSync(lockFile); } catch { /* ignore — may already be gone */ }
  try { server.stop(true); } catch { /* ignore */ }
  try { await serialize(() => rawEngine.disconnect()); } catch (e) { console.error('[braind] disconnect error', e); }
  process.exit(0);
}
process.on('SIGINT', () => void shutdown('SIGINT'));
process.on('SIGTERM', () => void shutdown('SIGTERM'));

