if (url.pathname === '/health') {
  // NOTE: this does NOT hold for /sync -- runIngest's sync_repo branch deliberately runs
  // performSync as ONE giant serialize() slot for its whole duration (to avoid a proxy
  // re-entrant-transaction deadlock; see the comment at that call site), so a real sync with
  // embed work routinely runs long enough to exceed the watchdog's probe timeouts.
  // engine.getHealth()/getStats() are proxied through that SAME chain, so they'd queue behind
  // the in-flight sync and not resolve until it finishes -- the watchdog's -IfUnhealthy then
  // times out, its own ingest.running safety check ALSO queues behind the same chain and times
  // out too, and it falls through to "assume wedged" and force-kills a daemon that was actually
  // alive and correctly busy (observed 2026-07-01: every hourly vault-sync restarted right at
  // the watchdog's :01-past-hour tick). Fast path: while ingest.running, answer entirely from
  // in-memory state -- never touch the shared chain -- so a busy-but-alive daemon reports
  // honestly instead of looking wedged.
  const deep = url.searchParams.get('deep') === '1';
  if (ingest.running) {
    return json({
      ok: true,
      pid: process.pid,
      uptime_s: Math.round((Date.now() - startedAt) / 1000),
      data_dir: dataDir,
      embed: { model: process.env.GBRAIN_EMBED_MODEL || null, dim: parseInt(process.env.GBRAIN_EMBED_DIMENSIONS || '0', 10) },
      ingest: ingestStatus(),
      spawn: null, health: null, stats: null, busy: true,
    });
  }
  // ?deep=1 adds a child-spawn probe (git --version): a spawn-dead daemon (deleted cwd) answers
  // /health ok but can't run /sync -- the watchdog uses deep=1 to detect + heal that. Plain
  // /health stays cheap for the bridge's frequent liveness probes.
  const health = await engine.getHealth();
  const stats = await engine.getStats();
  return json({
    ok: true,
    pid: process.pid,
    uptime_s: Math.round((Date.now() - startedAt) / 1000),
