$pidBefore = (Invoke-RestMethod 'http://127.0.0.1:8077/health' -TimeoutSec 5).pid
"daemon pid before test: $pidBefore"

$body = @{ repo = 'C:/Users/mattm/master-jarvis/second-brain' } | ConvertTo-Json -Compress
$syncJob = Start-Job -ScriptBlock {
    param($b)
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try { $r = Invoke-RestMethod 'http://127.0.0.1:8077/sync' -Method Post -Body $b -ContentType 'application/json' -TimeoutSec 60 }
    catch { $r = "ERR: $($_.Exception.Message)" }
    [pscustomobject]@{ elapsedMs = $sw.ElapsedMilliseconds; resp = ($r | ConvertTo-Json -Compress -Depth 4) }
} -ArgumentList $body

# burst-poll /health as fast as possible for ~3s to try to catch the busy window
$caughtBusy = $false
$sawFast = $true
for ($i = 0; $i -lt 25; $i++) {
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try {
        $h = Invoke-RestMethod 'http://127.0.0.1:8077/health' -TimeoutSec 5
        $ms = $sw.ElapsedMilliseconds
        if ($h.busy -eq $true -or $h.ingest.running -eq $true) {
            $caughtBusy = $true
            "  [poll $i] BUSY caught -- ${ms}ms  busy=$($h.busy) ingest.running=$($h.ingest.running) phase=$($h.ingest.phase) health=$($h.health) stats=$($h.stats)"
        }
        if ($ms -gt 3000) { $sawFast = $false; "  [poll $i] SLOW -- ${ms}ms (busy=$($h.busy))" }
    } catch {
        "  [poll $i] /health THREW after $($sw.ElapsedMilliseconds)ms: $($_.Exception.Message)"
        $sawFast = $false
    }
    Start-Sleep -Milliseconds 100
}
$syncJob | Wait-Job -Timeout 90 | Out-Null
$res = Receive-Job $syncJob
Remove-Job $syncJob -Force
"sync total elapsed: $($res.elapsedMs)ms  resp=$($res.resp)"
"caught a busy response during the window: $caughtBusy"
"all /health polls stayed fast (<3s) and none threw: $sawFast"

$pidAfter = (Invoke-RestMethod 'http://127.0.0.1:8077/health' -TimeoutSec 5).pid
"daemon pid after: $pidAfter  (same process, no kill happened: $([bool]($pidAfter -eq $pidBefore)))"

$pidBefore = (Invoke-RestMethod 'http://127.0.0.1:8077/health' -TimeoutSec 5).pid
"pid before: $pidBefore"
$body = @{ repo = 'C:/Users/mattm/master-jarvis/second-brain' } | ConvertTo-Json -Compress
$null = Start-Job -ScriptBlock {
    param($b)
    try { Invoke-RestMethod 'http://127.0.0.1:8077/sync' -Method Post -Body $b -ContentType 'application/json' -TimeoutSec 60 } catch { }
} -ArgumentList $body

$slowCount = 0; $fastBusyCount = 0; $errCount = 0
for ($i = 0; $i -lt 20; $i++) {
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try {
        $h = Invoke-RestMethod 'http://127.0.0.1:8077/health' -TimeoutSec 5
        $ms = $sw.ElapsedMilliseconds
        if ($ms -gt 500) { $slowCount++; "  [poll $i] SLOW ${ms}ms busy=$($h.busy) running=$($h.ingest.running)" }
        elseif ($h.busy -eq $true) { $fastBusyCount++ }
    } catch { $errCount++; "  [poll $i] THREW after $($sw.ElapsedMilliseconds)ms" }
    Start-Sleep -Milliseconds 80
}
"fastBusyCount=$fastBusyCount  slowCount=$slowCount  errCount=$errCount"
Get-Job | Wait-Job -Timeout 30 | Out-Null; Get-Job | Remove-Job -Force
$pidAfter = (Invoke-RestMethod 'http://127.0.0.1:8077/health' -TimeoutSec 5).pid
"pid after: $pidAfter  (unchanged: $([bool]($pidAfter -eq $pidBefore)))"

Write-Host "===== Signal C: failing scheduled tasks (Jarvis/JARVIS/Hermes/DP600/Loopify) ====="
$tasks = Get-ScheduledTask | Where-Object { $_.TaskName -match '^(Jarvis|JARVIS|Hermes|DP600|Loopify)-' }
$bad = foreach ($t in $tasks) {
  $i = Get-ScheduledTaskInfo -TaskName $t.TaskName -ErrorAction SilentlyContinue
  if (-not $i) { continue }
  $benign = @(0, 267009, 267011, 267014, 267010)
  if ($t.State -ne 'Disabled' -and ($benign -notcontains $i.LastTaskResult)) {
    [pscustomobject]@{ Name=$t.TaskName; State=$t.State; LastResult=('0x{0:X}' -f $i.LastTaskResult); LastRun=$i.LastRunTime }
  }
}
if ($bad) { $bad | Format-Table -AutoSize } else { "clean -- no failing tasks" }

Write-Host ""
Write-Host "===== Signal G: night-scheduled tasks (00:00-05:59) ====="
$night = foreach ($t in $tasks) {
  foreach ($tr in $t.Triggers) {
    if ("$($tr.StartBoundary)" -match 'T0[0-5]:') { [pscustomobject]@{ Name=$t.TaskName; Start=$tr.StartBoundary } }
  }
}
if ($night) { $night | Sort-Object Name -Unique | Format-Table -AutoSize } else { "clean -- no night-scheduled tasks" }

