function Resolve-HealTaskName {
    # Map a -Id (registry loop) or -Target (raw task name) to the scheduled-task name to heal.
    param([string] $Id, [string] $Target)
    if ($Target) { return $Target }
    if (-not $Id) { throw "Heal/Restart needs -Id <loop-id> or -Target <taskName>" }
    $reg = Get-Registry; $loops = Get-LoopArray $reg
    $loop = $loops | Where-Object { $_.id -eq $Id }
    if (-not $loop) { throw "no loop '$Id' in registry (pass -Target for a raw task name)" }
    if ($loop.runner -ne 'local-scheduled') {
        throw "loop '$Id' runner=$($loop.runner) has no scheduled task to heal (local-scheduled only)"
    }
    if ($loop.task_name) { return $loop.task_name }
    return "Loopify-$Id"
}

switch ($Action) {

  'Register' {
    if (-not $Id)        { throw "-Id required" }
    if (-not $Goal)      { throw "-Goal required" }
    if (-not $Archetype) { throw "-Archetype required" }
    if (-not $Runner)    { throw "-Runner required" }
    $reg = Get-Registry
    $loops = Get-LoopArray $reg
    if ($loops | Where-Object { $_.id -eq $Id }) { throw "loop id '$Id' already registered (Remove it first)" }
    $hbPath = Join-Path $LoopsDir "$Id\.heartbeat"
    $entry = [ordered]@{
        id             = $Id
        goal           = $Goal
        archetype      = $Archetype
        runner         = $Runner
        runner_path    = $RunnerPath
        schedule       = $Schedule
        stop_condition = $StopCondition
        budget_cap     = $BudgetCap
        kill_cmd       = $KillCmd
        task_name      = $null
        heartbeat_path = $hbPath
        status         = 'registered'
        created        = (NowUtc)
        last_heartbeat = $null
    }
