/**
 * Embedding Service
 * Ported from production Ruby implementation (embedding_service.rb, 190 LOC)
 *
 * Defaults: OpenAI text-embedding-3-large at 1536 dimensions.
 * Retry with exponential backoff (4s base, 120s cap, 5 retries).
 * 8000 character input truncation.
 *
 * Provider override (gbrain v0.10.2 + Amo patch 2026-05-07):
 *   GBRAIN_EMBED_BASE_URL  override OpenAI base URL (e.g. http://127.0.0.1:11434/v1 for Ollama)
 *   GBRAIN_EMBED_MODEL     override embedding model (e.g. nomic-embed-text for Ollama)
 *   GBRAIN_EMBED_DIMENSIONS  override output dimension count (must match brain schema)
 *   GBRAIN_EMBED_API_KEY   override API key (e.g. "ollama" for local Ollama)
 *
 * Note: dimensions are stored in the pgvector column type at brain init. Changing
 * dimensions on an existing brain requires re-init or schema migration.
 */

import OpenAI from 'openai';

const MODEL = process.env.GBRAIN_EMBED_MODEL || 'text-embedding-3-large';
const DIMENSIONS = parseInt(process.env.GBRAIN_EMBED_DIMENSIONS || '1536', 10);
const BASE_URL = process.env.GBRAIN_EMBED_BASE_URL || undefined;
const API_KEY = process.env.GBRAIN_EMBED_API_KEY || process.env.OPENAI_API_KEY;
const SUPPORTS_DIMENSIONS = !BASE_URL || /openai\.com/i.test(BASE_URL);

const MAX_CHARS = 8000;
const MAX_RETRIES = 5;
const BASE_DELAY_MS = 4000;
const MAX_DELAY_MS = 120000;
const BATCH_SIZE = 100;
// Per-request timeout (ms). The OpenAI SDK defaults to 600_000 (10 min); combined with the
// retry loop below that compounded into ~40-min zombie embeds when the backend (Ollama) was
// saturated — which then had to be hard-killed, corrupting the single-connection PGLite DB.
// A finite per-request timeout makes a stalled backend fail LOUD instead of hanging. Override
// via GBRAIN_EMBED_TIMEOUT_MS. Tune up for very large batches on slow providers.
const REQUEST_TIMEOUT_MS = parseInt(process.env.GBRAIN_EMBED_TIMEOUT_MS || '60000', 10);

let client: OpenAI | null = null;

function getClient(): OpenAI {
  if (!client) {
    const opts: { baseURL?: string; apiKey?: string; timeout?: number; maxRetries?: number } = {
      // Finite per-request timeout so a saturated/dead backend can't hang the embed forever.
      timeout: REQUEST_TIMEOUT_MS,
      // This module runs its own retry/backoff loop (embedBatchWithRetry); disable the SDK's
      // built-in retries so the two layers don't compound (SDK default is 2).
      maxRetries: 0,
    };
    if (BASE_URL) opts.baseURL = BASE_URL;
    if (API_KEY) opts.apiKey = API_KEY;
    client = new OpenAI(opts);
  }
  return client;
}

export async function embed(text: string): Promise<Float32Array> {
  const truncated = text.slice(0, MAX_CHARS);
  const result = await embedBatch([truncated]);
  return result[0];
}

export async function embedBatch(texts: string[]): Promise<Float32Array[]> {
  const truncated = texts.map(t => t.slice(0, MAX_CHARS));
  const results: Float32Array[] = [];

  // Process in batches of BATCH_SIZE
  for (let i = 0; i < truncated.length; i += BATCH_SIZE) {
    const batch = truncated.slice(i, i + BATCH_SIZE);
    const batchResults = await embedBatchWithRetry(batch);
    results.push(...batchResults);
  }

  return results;
}

async function embedBatchWithRetry(texts: string[]): Promise<Float32Array[]> {
  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    try {
      // Ollama and other OpenAI-compatible endpoints often don't support
      // the `dimensions` parameter (only OpenAI's text-embedding-3-* models do).
      // Omit it when the base URL points at a non-OpenAI provider.
      const params: { model: string; input: string[]; dimensions?: number } = {
        model: MODEL,
        input: texts,
      };
      if (SUPPORTS_DIMENSIONS) {
        params.dimensions = DIMENSIONS;
      }
      const response = await getClient().embeddings.create(params);

      // Sort by index to maintain order
      const sorted = response.data.sort((a, b) => a.index - b.index);
      return sorted.map(d => new Float32Array(d.embedding));
    } catch (e: unknown) {
      if (attempt === MAX_RETRIES - 1) throw e;

      // Check for rate limit with Retry-After header
      let delay = exponentialDelay(attempt);

      if (e instanceof OpenAI.APIError && e.status === 429) {
        const retryAfter = e.headers?.['retry-after'];
        if (retryAfter) {
          const parsed = parseInt(retryAfter, 10);
          if (!isNaN(parsed)) {
            delay = parsed * 1000;
          }
        }
      }

      await sleep(delay);
    }
  }

  // Should not reach here
  throw new Error('Embedding failed after all retries');
}

function exponentialDelay(attempt: number): number {
  const delay = BASE_DELAY_MS * Math.pow(2, attempt);
  return Math.min(delay, MAX_DELAY_MS);
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export { MODEL as EMBEDDING_MODEL, DIMENSIONS as EMBEDDING_DIMENSIONS };

