  // force-push). For a curated brain served by the daemon that would re-import the ENTIRE repo and
  // re-embed every chunk on the paid provider — the daemon sets this so the caller must opt in.
  refuseFull?: boolean;
}

function git(repoPath: string, ...args: string[]): string {
  const argv = ['-C', repoPath, ...args];
  // Bun-on-Windows footgun: once the PGLite WASM engine is loaded in-process (the
  // daemon connects it at startup), Node-compat child_process (execFileSync/spawnSync)
  // is wedged and returns a SPURIOUS `ETIMEDOUT` on every subsequent spawn -- in ~16ms,
  // not after the timeout. Bun's native Bun.spawnSync uses a different path and is
  // unaffected. Prefer it whenever running under Bun (the CLI binary and the daemon
  // both do); fall back to execFileSync only under plain Node (some test runners).
  // Verified 2026-06-01: after PGLiteEngine.connect(), execFileSync('git') -> ETIMEDOUT
  // in 16ms while Bun.spawnSync('git') -> OK in 59ms (pglite-spawn-repro).
  const B = (globalThis as { Bun?: { spawnSync: (cmd: string[], o?: unknown) => { success: boolean; exitCode: number; stdout: Uint8Array; stderr: Uint8Array } } }).Bun;
  if (B && typeof B.spawnSync === 'function') {
    const p = B.spawnSync(['git', ...argv], { stdout: 'pipe', stderr: 'pipe' });
    if (!p.success) {
      const stderr = Buffer.from(p.stderr).toString();
      const err = new Error(stderr.trim() || `git exited ${p.exitCode}`) as Error & { code?: number; stderr?: string };
      err.code = p.exitCode;
      err.stderr = stderr;
      throw err;
    }
    return Buffer.from(p.stdout).toString().trim();
  }
  return execFileSync('git', argv, {
    encoding: 'utf-8',
    timeout: 30000,
  }).trim();
}

export async function performSync(engine: BrainEngine, opts: SyncOpts): Promise<SyncResult> {
  // Resolve repo path
  const repoPath = opts.repoPath || await engine.getConfig('sync.repo_path');
  if (!repoPath) {
    throw new Error('No repo path specified. Use --repo or run gbrain init with --repo first.');
  }

  // Validate git repo
  if (!existsSync(join(repoPath, '.git'))) {
    throw new Error(`Not a git repository: ${repoPath}. GBrain sync requires a git-initialized repo.`);
  }

  // Git pull (unless --no-pull)
  if (!opts.noPull) {
    try {
      git(repoPath, 'pull', '--ff-only');
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      if (msg.includes('non-fast-forward') || msg.includes('diverged')) {
        console.error(`Warning: git pull failed (remote diverged). Syncing from local state.`);
      } else {
        console.error(`Warning: git pull failed: ${msg.slice(0, 100)}`);
      }
    }
  }

