import { existsSync } from 'fs';
import { execFileSync } from 'child_process';
import { join, relative } from 'path';
import type { BrainEngine } from '../core/engine.ts';
import { importFile } from '../core/import-file.ts';
import { buildSyncManifest, isSyncable, pathToSlug } from '../core/sync.ts';
import type { SyncManifest } from '../core/sync.ts';

export interface SyncResult {
  status: 'up_to_date' | 'synced' | 'first_sync' | 'dry_run';
  fromCommit: string | null;
  toCommit: string;
  added: number;
  modified: number;
  deleted: number;
  renamed: number;
  chunksCreated: number;
  pagesAffected: string[];
}

export interface SyncOpts {
  repoPath?: string;
  dryRun?: boolean;
  full?: boolean;
  noPull?: boolean;
  noEmbed?: boolean;
  noExtract?: boolean;
  // When set, refuse (throw) instead of falling into a FULL reimport. A full reimport happens on
  // first sync, --full, or when the stored anchor is missing / not an ancestor of HEAD (rebase /
  // force-push). For a curated brain served by the daemon that would re-import the ENTIRE repo and
  // re-embed every chunk on the paid provider — the daemon sets this so the caller must opt in.
  refuseFull?: boolean;
}

// A hung git subprocess (unreachable remote on `pull`, a stale index.lock, or an interactive
// credential prompt) blocks the daemon's single-writer thread FOREVER -- the Bun.spawnSync path
// below had no timeout, so a hung `git pull --ff-only` in performSync wedged the whole ingest
// (busy:true, CPU idle, no PGLite progress, last_error:null -- it's blocked, never thrown).
// GIT_TERMINAL_PROMPT=0 makes git fail instead of blocking on a credential prompt; the timeout
// makes a network/lock hang fail-fast (killed -> success:false -> throw -> surfaces as last_error,
// and the sync retries next fire) instead of silently hanging. Env-tunable for slow remotes.
const GIT_TIMEOUT_MS = parseInt(process.env.GBRAIN_GIT_TIMEOUT_MS || '30000', 10);

function git(repoPath: string, ...args: string[]): string {
  const argv = ['-C', repoPath, ...args];
  const gitEnv = { ...process.env, GIT_TERMINAL_PROMPT: '0' };
  // Bun-on-Windows footgun: once the PGLite WASM engine is loaded in-process (the
  // daemon connects it at startup), Node-compat child_process (execFileSync/spawnSync)
  // is wedged and returns a SPURIOUS `ETIMEDOUT` on every subsequent spawn -- in ~16ms,
  // not after the timeout. Bun's native Bun.spawnSync uses a different path and is
  // unaffected. Prefer it whenever running under Bun (the CLI binary and the daemon
  // both do); fall back to execFileSync only under plain Node (some test runners).
  // Verified 2026-06-01: after PGLiteEngine.connect(), execFileSync('git') -> ETIMEDOUT
  // in 16ms while Bun.spawnSync('git') -> OK in 59ms (pglite-spawn-repro).
  const B = (globalThis as { Bun?: { spawnSync: (cmd: string[], o?: unknown) => { success: boolean; exitCode: number; stdout: Uint8Array; stderr: Uint8Array; signalCode?: string | null } } }).Bun;
  if (B && typeof B.spawnSync === 'function') {
    const p = B.spawnSync(['git', ...argv], { stdout: 'pipe', stderr: 'pipe', timeout: GIT_TIMEOUT_MS, env: gitEnv });
    if (!p.success) {
      const stderr = Buffer.from(p.stderr).toString();
      // On a timeout Bun kills the child (signalCode set, empty stderr) -> make the reason explicit.
      const timedOut = p.signalCode && !stderr.trim();
      const reason = timedOut
        ? `git timed out after ${GIT_TIMEOUT_MS}ms (killed ${p.signalCode}) -- hung remote/lock/prompt?`
        : (stderr.trim() || `git exited ${p.exitCode}`);
      const err = new Error(reason) as Error & { code?: number; stderr?: string };
      err.code = p.exitCode;
      err.stderr = stderr;
      throw err;
    }
    return Buffer.from(p.stdout).toString().trim();
  }
  return execFileSync('git', argv, {
    encoding: 'utf-8',
    timeout: GIT_TIMEOUT_MS,
    env: gitEnv,
  }).trim();
}

