  for (let attempt = 0; attempt <= GIT_SPAWN_RETRIES; attempt++) {
    const outFd = openSync(outP, 'w');
    const errFd = openSync(errP, 'w');
    const started = Date.now();
    let ok = false, exitCode = -1, signalCode: string | null | undefined;
    try {
      const p = B.spawnSync(['git', ...argv], { stdout: outFd, stderr: errFd, timeout: GIT_TIMEOUT_MS, env: gitEnv });
