    try { stdout = readFileSync(outP, 'utf-8'); } catch { /* no output */ }
    try { stderr = readFileSync(errP, 'utf-8'); } catch { /* no output */ }
    try { unlinkSync(outP); } catch { /* best effort */ }
    try { unlinkSync(errP); } catch { /* best effort */ }
