function Test-SyncPersistentlyFailing {
  # The SECOND watchdog blind spot (found 2026-07-01): a daemon can answer /health ok, pass the
  # spawn probe (git --version, stdout:'ignore'), AND not be wedged (ingest.running:false) -- yet
  # every SYNC fails fast on `git rev-parse` because Bun.spawnSync with PIPED stdio is corrupted in
  # that long-lived instance. phase='error' with running:false => Test-IngestWedged is blind to it,
  # so the old healthy-branch said "nothing to do" and the brain silently stopped ingesting for
  # HOURS. This detector heals that class: phase=error on the git/spawn-instability pattern, seen
  # across >= $Threshold consecutive fires (persistence, not a one-off), and not within
  # $CooldownMinutes of the last heal (storm-safe -- at most one restart per cooldown). A restart
  # clears the Bun spawn corruption. State: ~/.gbrain-trading/watchdog-state.json. Fail SAFE: any
  # error reading state, or a non-spawn error class (e.g. genuine non-fast-forward), returns $false.
  param($Health, [int]$Threshold = 2, [int]$CooldownMinutes = 30)
  $stateFile = Join-Path $env:USERPROFILE '.gbrain-trading\watchdog-state.json'
  $consecutive = 0; $lastHealMs = 0
  if (Test-Path $stateFile) {
    try { $j = Get-Content $stateFile -Raw | ConvertFrom-Json; $consecutive = [int]$j.consecutive; $lastHealMs = [long]$j.last_heal_ms } catch { $consecutive = 0; $lastHealMs = 0 }
  }
  $ing = $Health.ingest
  $isSpawnFail = $false
  if ($ing -and $ing.phase -eq 'error' -and $ing.last_error) {
    # ONLY the spawn/git-instability class -- never a legit 'non-fast-forward'/'diverged'/config error.
    if ($ing.last_error -match 'rev-parse|spawn failed fast|spawn instability|git timed out|killed SIG') { $isSpawnFail = $true }
  }
  if (-not $isSpawnFail) {
    if ($consecutive -ne 0) { try { @{ consecutive = 0; last_heal_ms = $lastHealMs } | ConvertTo-Json | Set-Content -Path $stateFile -Encoding ASCII } catch { } }
    return $false
  }
  $consecutive++
  $nowMs = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
  $sinceHealMin = if ($lastHealMs -gt 0) { ($nowMs - $lastHealMs) / 60000 } else { [double]::PositiveInfinity }
  $shouldHeal = ($consecutive -ge $Threshold) -and ($sinceHealMin -ge $CooldownMinutes)
  $newLastHeal = if ($shouldHeal) { $nowMs } else { $lastHealMs }
  $newConsecutive = if ($shouldHeal) { 0 } else { $consecutive }
  try { @{ consecutive = $newConsecutive; last_heal_ms = $newLastHeal } | ConvertTo-Json | Set-Content -Path $stateFile -Encoding ASCII } catch { }
  Write-Host ("[restart-brain-daemon] sync-fail watch: spawn-class error, consecutive={0} (>= {1}?), since last heal={2:N0} min (>= {3}?) => heal={4}" -f $consecutive, $Threshold, $sinceHealMin, $CooldownMinutes, $shouldHeal)
  return $shouldHeal
}

