function bodyAfterFrontmatter(raw:string):string {
  // everything after the SECOND '---' line (the frontmatter close)
  const lines = raw.split('\n');
  let seen=0, i=0;
  for (; i<lines.length; i++){ if (/^---\s*\r?$/.test(lines[i])) { seen++; if (seen===2) { i++; break; } } }
