  try {
    ({ data: frontmatter, content: body } = matter(content));
  } catch (e: unknown) {
    console.warn(`[gbrain] frontmatter parse failed for ${filePath ?? '<unknown>'} -- ingesting body with derived metadata (fix + re-ingest to restore structured fields): ${e instanceof Error ? e.message.split('\n')[0] : String(e)}`);
