function spawnProbe(): { ok: boolean; error?: string } {
  try {
    // Use Bun's native spawn: once PGLite's WASM is loaded, Node-compat execFileSync
    // is wedged and returns a spurious ETIMEDOUT for every spawn (see git() in
    // commands/sync.ts). A probe that used execFileSync would report spawn-dead even
    // though the daemon CAN spawn via Bun.spawnSync, making the watchdog churn.
    const B = (globalThis as { Bun?: { spawnSync: (cmd: string[], o?: unknown) => { success: boolean; exitCode: number } } }).Bun;
    if (B && typeof B.spawnSync === 'function') {
      const p = B.spawnSync(['git', '--version'], { stdout: 'ignore', stderr: 'ignore' });
      return p.success ? { ok: true } : { ok: false, error: `git --version exited ${p.exitCode}` };
    }
    execFileSync('git', ['--version'], { timeout: 3000, stdio: 'ignore' });
    return { ok: true };
  } catch (e: unknown) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}

// Stamp the on-disk health marker after a clean ingest, so a checker can read coverage/freshness
// WITHOUT opening the DB. Mirrors the schema safe-embed.ps1 writes. Never throws into the caller.
async function stampHealth(phase: string) {
  try {
    const s = await engine.getStats() as { chunk_count?: number; embedded_count?: number };
    const chunks = s.chunk_count ?? 0;
    const embedded = s.embedded_count ?? 0;
    writeFileSync(healthFile, JSON.stringify({
      model: process.env.GBRAIN_EMBED_MODEL || null,
      dim: process.env.GBRAIN_EMBED_DIMENSIONS || null,
