// --- Semantic auto-linking (orphan revival) -------------------------------------------------------
// "The value of the system is in the edges, not the nodes." ~61% of pages are orphans (no outgoing
// links) -- semantically recallable but invisible to graph_recall / traverseGraph, which walk the
// `links` table. This pass gives every orphan up to K nearest-neighbour edges by embedding cosine
// similarity, reusing the daemon's OWN vector engine (searchVector) + addLink. It writes ONLY into the
// links table with link_type='semantic' (never touches vault .md files), so the whole pass reverses
// with `DELETE FROM links WHERE link_type='semantic'`. addLink is ON CONFLICT DO UPDATE keyed on
// (from,to), so re-running is idempotent. Runs server-side because searchVector takes a Float32Array
// (daemon-owned; not JSON-round-trippable over /rpc). Each engine call self-serializes via the proxy,
// so /search interleaves -- this does NOT hold the writer for its whole duration.

async function pickEmbedding(
  chunks: Array<{ id: number; chunk_source?: string; chunk_index?: number }>,
): Promise<Float32Array | null> {
  if (!chunks || chunks.length === 0) return null;
  // Prefer a compiled_truth chunk (the page's distilled summary) at the lowest index; fall back to any.
  const ordered = [...chunks].sort((a, b) => {
    const av = a.chunk_source === 'compiled_truth' ? 0 : 1;
    const bv = b.chunk_source === 'compiled_truth' ? 0 : 1;
    if (av !== bv) return av - bv;
    return (a.chunk_index ?? 0) - (b.chunk_index ?? 0);
  });
  const ids = ordered.map(c => c.id).filter((id): id is number => typeof id === 'number');
  if (ids.length === 0) return null;
  const embMap = await engine.getEmbeddingsByChunkIds(ids);
  for (const c of ordered) {
    const e = embMap.get(c.id);
    if (e) return e;
  }
  return null;
}

async function runAutoLink(opts: { dryRun: boolean; k: number; threshold: number; maxPages?: number }) {
  const { dryRun, k, threshold, maxPages } = opts;
  const pages = await engine.listPages();
  let orphans = 0, orphansEmbedMissing = 0, pagesLinked = 0, edgesProposed = 0, edgesApplied = 0, orphansProcessed = 0;
  const sample: Array<{ from: string; to: string; score: number }> = [];
  for (const page of pages) {
    if (maxPages && orphansProcessed >= maxPages) break;
    const existing = await engine.getLinks(page.slug);
    if (existing.length > 0) continue;               // has outgoing edges -> not an orphan
    orphans++; orphansProcessed++;
    const chunks = await engine.getChunks(page.slug) as Array<{ id: number; chunk_source?: string; chunk_index?: number }>;
    const emb = await pickEmbedding(chunks);
    if (!emb) { orphansEmbedMissing++; continue; }
    const neighbors = await engine.searchVector(emb, { limit: k * 5 });
    const best = new Map<string, number>();          // dedup by slug -> best score across its chunks
    for (const n of neighbors) {
      const s = n.slug as string;
      if (!s || s === page.slug) continue;
      const sc = Number(n.score);
      const prev = best.get(s);
      if (prev === undefined || sc > prev) best.set(s, sc);
    }
    const targets = [...best.entries()]
      .filter(([, sc]) => sc >= threshold)
      .sort((a, b) => b[1] - a[1])
      .slice(0, k);
    if (targets.length > 0) pagesLinked++;
    for (const [toSlug, score] of targets) {
      edgesProposed++;
      if (sample.length < 50) sample.push({ from: page.slug, to: toSlug, score: Math.round(score * 1000) / 1000 });
      if (!dryRun) {
        await engine.addLink(page.slug, toSlug, `auto:semantic score=${score.toFixed(3)}`, 'semantic');
        edgesApplied++;
      }
    }
  }
  return { totalPages: pages.length, orphans, orphansEmbedMissing, pagesLinked, edgesProposed, edgesApplied, dryRun, k, threshold, sample };
}

