if (url.pathname === '/auto-link' && req.method === 'POST') {
  // Semantic orphan-revival pass. dry_run defaults TRUE (inspect before mutating). This is a LONG op
  // (per-orphan vector search across the whole corpus), so it runs single-flight through the SAME
  // `ingest` busy-state as /ingest+/sync: that makes /health fast-path to in-memory state, so the
  // watchdog reads "busy+alive" instead of force-reaping a daemon whose serialize() chain is
  // saturated for minutes (observed: a synchronous full-corpus run got killed mid-pass). Returns 202
