  if (ingest.running) return json({ error: 'ingest/sync/auto-link already running', status: ingestStatus() }, 409);
  const body = await req.json().catch(() => ({})) as { dry_run?: boolean; k?: number; threshold?: number; max_pages?: number };
  const k = Math.max(1, Math.min(20, body.k ?? 5));
  const threshold = Math.max(0, Math.min(1, body.threshold ?? 0.78));
  const dryRun = body.dry_run !== false;
  ingest.running = true; ingest.startedAt = Date.now(); ingest.finishedAt = null;
  ingest.phase = `auto-link:${dryRun ? 'dry' : 'apply'}`; ingest.lastError = null;
  void (async () => {
    try {
      const result = await runAutoLink({ dryRun, k, threshold, maxPages: body.max_pages });
      lastAutoLink = { ...result, finished_iso: new Date().toISOString() };
      ingest.lastResult = lastAutoLink;
    } catch (e: unknown) {
      ingest.lastError = e instanceof Error ? e.message : String(e);
    } finally {
      ingest.running = false; ingest.finishedAt = Date.now(); ingest.phase = null;
    }
  })();
  return json({ accepted: true, mode: dryRun ? 'dry_run' : 'apply', status: ingestStatus() }, 202);
}

