  @{ name="45 min (healthy hourly-sync sawtooth)";    stale=45;    expect="skip" },
  @{ name="200 min (every-sync-failing wedge)";        stale=200;   expect="THROW" }
)) {
  # Exact logic mirrored from run.ps1
  $staleMin = $case.stale
  $fired = $false
  if ($null -ne $staleMin -and $staleMin -gt $Threshold) { $fired = $true }
  $got = if ($fired) { "THROW" } else { "skip" }
  $ok = if ($got -eq $case.expect) { "PASS" } else { "FAIL" }
  "{0,-5} stale={1,-6} threshold={2} -> {3,-6} (expected {4})  [{5}]" -f $ok, $case.stale, $Threshold, $got, $case.expect, $case.name
}'

