async searchVector(embedding: Float32Array, opts?: SearchOpts): Promise<SearchResult[]> {
  const limit = clampSearchLimit(opts?.limit);
  const offset = opts?.offset || 0;
  const vecStr = '[' + Array.from(embedding).join(',') + ']';
  // detailFilter runs inside the bare-table CTE below, so it references chunk_source WITHOUT an alias.
  const detailFilter = opts?.detail === 'low' ? `AND chunk_source = 'compiled_truth'` : '';

  if (opts?.limit && opts.limit > MAX_SEARCH_LIMIT) {
    console.warn(`[gbrain] Warning: search limit clamped from ${opts.limit} to ${MAX_SEARCH_LIMIT}`);
  }

  // KNN-then-join: run `ORDER BY embedding <-> q LIMIT k` on the BARE content_chunks table so the
  // pgvector HNSW index (idx_chunks_embedding) can serve it as an index scan. Doing the pages JOIN and
  // the `stale` correlated subquery in the same SELECT defeats the index -- the planner falls back to a
  // full sequential scan + sort over every embedding (~5.5k rows, ~500ms in WASM PGlite). Fetch the k
  // nearest chunk ids first, THEN join page metadata; re-apply the distance order on the outer query.
  const { rows } = await this.db.query(
    `WITH knn AS (
      SELECT id AS chunk_id, page_id, chunk_index, chunk_text, chunk_source,
             embedding <=> $1::vector AS dist
      FROM content_chunks
      WHERE embedding IS NOT NULL ${detailFilter}
      ORDER BY embedding <=> $1::vector
      LIMIT $2 OFFSET $3
    )
    SELECT
      p.slug, p.id as page_id, p.title, p.type,
      k.chunk_id, k.chunk_index, k.chunk_text, k.chunk_source,
      1 - k.dist AS score,
      CASE WHEN p.updated_at < (
        SELECT MAX(te.created_at) FROM timeline_entries te WHERE te.page_id = p.id
      ) THEN true ELSE false END AS stale
    FROM knn k
    JOIN pages p ON p.id = k.page_id
    ORDER BY k.dist`,
    [vecStr, limit, offset]
  );

  return (rows as Record<string, unknown>[]).map(rowToSearchResult);
}

/**
 * Read-only diagnostic: list the indexes on content_chunks and EXPLAIN ANALYZE a bare KNN query, so we
 * can see whether the pgvector HNSW index is actually used (Index Scan using idx_chunks_embedding) or
 * the planner falls back to a Seq Scan. Used to verify the searchVector KNN-then-join rewrite.
 */
async explainVectorSearch(): Promise<{ indexes: { indexname: string; indexdef: string }[]; plan: string; rowsScanned: number }> {
  const idx = await this.db.query(
    `SELECT indexname, indexdef FROM pg_indexes WHERE tablename = 'content_chunks'`
  );
  const cnt = await this.db.query(`SELECT count(*)::int AS n FROM content_chunks WHERE embedding IS NOT NULL`);
  const one = await this.db.query(`SELECT embedding FROM content_chunks WHERE embedding IS NOT NULL LIMIT 1`);
  let plan = 'no embedding sample available';
  if (one.rows.length) {
    const emb = (one.rows[0] as { embedding: unknown }).embedding;
    const vecStr = typeof emb === 'string' ? emb : '[' + Array.from(emb as Float32Array).join(',') + ']';
    const ex = await this.db.query(
      `EXPLAIN (ANALYZE, FORMAT TEXT)
       SELECT id FROM content_chunks WHERE embedding IS NOT NULL
       ORDER BY embedding <=> $1::vector LIMIT 5`,
      [vecStr]
    );
    plan = (ex.rows as Record<string, unknown>[]).map(r => String(r['QUERY PLAN'])).join('\n');
  }
  return {
    indexes: idx.rows as { indexname: string; indexdef: string }[],
    plan,
    rowsScanned: (cnt.rows[0] as { n: number }).n,
  };
}

