1	/**
2	 * SocketEngine — a BrainEngine implementation that proxies to the brain daemon over localhost HTTP
3	 * instead of opening PGlite directly. This is how TS clients (the gbrain CLI) use the daemon: they
4	 * NEVER touch the DB or the lock; the daemon is the sole writer/serializer.
5	 *
6	 * M1 = READ PATH: read methods proxy to the daemon's /rpc; writes throw (M3), and vector/embedding
7	 * methods throw (use the daemon's high-level /search, which embeds server-side — clients send text).
8	 *
9	 * Config: engine='daemon', daemon_url (default http://127.0.0.1:8077). Bearer token from
10	 * GBRAIN_DAEMON_TOKEN if the daemon requires one.
11	 */
12	import type { BrainEngine } from './engine.ts';
13	import type {
14	  Page, PageInput, PageFilters,
15	  Chunk, ChunkInput,
16	  SearchResult, SearchOpts,
17	  Link, GraphNode,
18	  TimelineEntry, TimelineInput, TimelineOpts,
19	  RawData, PageVersion,
20	  BrainStats, BrainHealth,
21	  IngestLogEntry, IngestLogInput,
22	  EngineConfig,
23	} from './types.ts';
24	
25	const INGEST_MSG = 'daemon: chunk/embedding writes go through POST /ingest (text in, embedded server-side with the daemon\'s key) — not raw over /rpc';
26	const VECTOR_MSG = 'daemon: use the /search endpoint (embeds server-side) — raw vector methods are not proxied';
27	
28	export class SocketEngine implements BrainEngine {
29	  private baseUrl = 'http://127.0.0.1:8077';
30	  private token = process.env.GBRAIN_DAEMON_TOKEN || '';
31	
32	  // Lifecycle ---------------------------------------------------------------
