/**
 * SocketEngine — a BrainEngine implementation that proxies to the brain daemon over localhost HTTP
 * instead of opening PGlite directly. This is how TS clients (the gbrain CLI) use the daemon: they
 * NEVER touch the DB or the lock; the daemon is the sole writer/serializer.
 *
 * M1 = READ PATH: read methods proxy to the daemon's /rpc; writes throw (M3), and vector/embedding
 * methods throw (use the daemon's high-level /search, which embeds server-side — clients send text).
 *
 * Config: engine='daemon', daemon_url (default http://127.0.0.1:8077). Bearer token from
 * GBRAIN_DAEMON_TOKEN if the daemon requires one.
 */
import type { BrainEngine } from './engine.ts';
import type {
  Page, PageInput, PageFilters,
  Chunk, ChunkInput,
  SearchResult, SearchOpts,
  Link, GraphNode,
  TimelineEntry, TimelineInput, TimelineOpts,
  RawData, PageVersion,
  BrainStats, BrainHealth,
  IngestLogEntry, IngestLogInput,
  EngineConfig,
} from './types.ts';

const INGEST_MSG = 'daemon: chunk/embedding writes go through POST /ingest (text in, embedded server-side with the daemon\'s key) — not raw over /rpc';
const VECTOR_MSG = 'daemon: use the /search endpoint (embeds server-side) — raw vector methods are not proxied';

export class SocketEngine implements BrainEngine {
  private baseUrl = 'http://127.0.0.1:8077';
  private token = process.env.GBRAIN_DAEMON_TOKEN || '';

  // Lifecycle ---------------------------------------------------------------
  async connect(config: EngineConfig): Promise<void> {
    if (config.daemon_url) this.baseUrl = config.daemon_url.replace(/\/$/, '');
    // fail fast if the daemon isn't up — a clear error beats a pile of opaque rpc failures
    const res = await fetch(`${this.baseUrl}/health`, { headers: this.headers() }).catch(() => null);
    if (!res || !res.ok) {
      throw new Error(`brain daemon not reachable at ${this.baseUrl}. Start it: pwsh tools\\start-brain-daemon.ps1`);
    }
  }
  async disconnect(): Promise<void> { /* nothing to release — the daemon owns the connection */ }
  async initSchema(): Promise<void> { throw new Error('daemon owns the schema; initSchema is not a client operation'); }
  async transaction<T>(_fn: (engine: BrainEngine) => Promise<T>): Promise<T> {
    throw new Error('daemon read-path (M1): cross-call transactions are not supported over the socket');
  }

  // internals ---------------------------------------------------------------
  private headers(): Record<string, string> {
    const h: Record<string, string> = { 'content-type': 'application/json' };
    if (this.token) h['authorization'] = `Bearer ${this.token}`;
    return h;
  }
  private async rpc<T>(method: string, args: unknown[]): Promise<T> {
    const res = await fetch(`${this.baseUrl}/rpc`, { method: 'POST', headers: this.headers(), body: JSON.stringify({ method, args }) });
    if (!res.ok) {
      const body = await res.json().catch(() => ({ error: res.statusText })) as { error?: string };
      throw new Error(`daemon rpc ${method} -> ${res.status}: ${body.error || res.statusText}`);
    }
    const j = await res.json() as { result: T };
    return j.result;

