/**
 * gbrain-episodic-backfill.ts  --  populate the EPISODIC (timeline) layer of the trading brain.
 *
 * gbrain has three memory layers: semantic (pages/chunks), graph (links), and EPISODIC
 * (timeline_entries -- dated events). The episodic layer shipped fully wired but empty
 * (timeline_entry_count = 0): the stock `extract timeline` producer only matches two markdown
 * patterns the memory corpus does not use (measured: 1 entry from 444 files). This producer is
 * corpus-aware: every dated memory file (`*_YYYY_MM_DD.md`) becomes one dated timeline entry,
 * collected on a single canonical journal page so the brain gains a queryable cross-topic
 * chronology ("what happened around date X" via getTimeline {after,before}).
 *
 * SAFE + REVERSIBLE + IDEMPOTENT, all over the daemon's existing /rpc (no daemon change, no restart):
 *   - writes ONLY the synthetic `jarvis-session-journal` page + its timeline_entries rows.
 *   - reverse the ENTIRE backfill with one call: rpc deletePage('jarvis-session-journal')
 *     -> the timeline_entries FK is ON DELETE CASCADE, so every entry goes with the page.
 *   - idempotent: dedup on date::summary against the journal's existing timeline; re-runs only fill gaps.
 *   - the synthetic journal page never lives in the vault git repo, so vault /sync (which deletes
 *     only pages that appear in a git-diff manifest) can never prune it.
 *
 * USAGE (bun):
 *   bun run gbrain-episodic-backfill.ts               # DRY-RUN (default): prints what it would write
 *   bun run gbrain-episodic-backfill.ts --apply       # write the entries
 *   bun run gbrain-episodic-backfill.ts --json        # machine-readable summary
 *   bun run gbrain-episodic-backfill.ts --revert       # deletePage(journal) -> cascade-remove all entries
 *   env: GBRAIN_ENDPOINT (default http://127.0.0.1:8077), GBRAIN_MEMDIR (default the memory corpus)
 */
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { homedir } from 'node:os';

const ENDPOINT = (process.env.GBRAIN_ENDPOINT || 'http://127.0.0.1:8077').replace(/\/$/, '');
const MEMDIR = process.env.GBRAIN_MEMDIR
  || join(homedir(), '.claude', 'projects', 'C--Users-mattm', 'memory');
const JOURNAL_SLUG = 'jarvis-session-journal';
const SOURCE_PREFIX = 'memory:';
const SUMMARY_MAX = 300;

const APPLY = process.argv.includes('--apply');
const JSON_MODE = process.argv.includes('--json');
const REVERT = process.argv.includes('--revert');

async function rpc<T>(method: string, args: unknown[]): Promise<T> {
  const res = await fetch(`${ENDPOINT}/rpc`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ method, args }),
  });
  if (!res.ok) {
    const body = (await res.json().catch(() => ({ error: res.statusText }))) as { error?: string };
    throw new Error(`rpc ${method} -> ${res.status}: ${body.error || res.statusText}`);
  }
  const j = (await res.json()) as { result: T };
  return j.result;
}

/** Parse the LAST YYYY_MM_DD in a filename -> ISO date, or null. */
function dateFromФilename(_name: string): string | null { return null; } // placeholder; real impl below

function dateFromName(name: string): string | null {
  const re = /(20\d{2})[_-](\d{2})[_-](\d{2})/g;
  let m: RegExpExecArray | null;
  let last: RegExpExecArray | null = null;
  while ((m = re.exec(name)) !== null) last = m;
  if (!last) return null;
  const [, y, mo, d] = last;
  const mi = Number(mo), di = Number(d);
  if (mi < 1 || mi > 12 || di < 1 || di > 31) return null;
  return `${y}-${mo}-${d}`;
}

/** Pull a concise summary + longer detail from a memory file's frontmatter/body. */
function summarize(raw: string, slug: string): { summary: string; detail: string } {
  let description = '';
  const fm = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (fm) {
    // description may be quoted or bare, possibly spanning the rest of the line
    const dm = fm[1].match(/^description:\s*(.+)$/m);
    if (dm) description = dm[1].trim().replace(/^["']/, '').replace(/["']$/, '').trim();
  }
  // body = everything after frontmatter
  const body = fm ? raw.slice(fm[0].length) : raw;
  let firstPara = '';
  for (const line of body.split(/\r?\n/)) {
    const t = line.trim();
    if (!t) { if (firstPara) break; else continue; }
    if (t.startsWith('#')) { if (!firstPara) { firstPara = t.replace(/^#+\s*/, ''); break; } }
    firstPara += (firstPara ? ' ' : '') + t;
    if (firstPara.length > 400) break;
  }
  const humanSlug = slug.replace(/[_-]/g, ' ').replace(/\b\d{4} \d{2} \d{2}\b/, '').trim();
  let summary = (description || firstPara || humanSlug).replace(/\s+/g, ' ').trim();
  if (summary.length > SUMMARY_MAX) summary = summary.slice(0, SUMMARY_MAX - 1).trimEnd() + '…';
  if (!summary) summary = humanSlug || slug;
  const detail = (description && firstPara && description !== firstPara)
    ? firstPara.replace(/\s+/g, ' ').trim().slice(0, 1000)
    : '';
  return { summary, detail };
}

async function main() {
  // Preflight (brake 1): daemon up + not mid-ingest.
  const health = (await rpc<any>('getHealth', []).catch(() => null))
    ?? (await fetch(`${ENDPOINT}/health`).then(r => r.json()).catch(() => null));
  if (!health || !health.ok) throw new Error('daemon /health not ok -- aborting');
  if (health.ingest && health.ingest.running) throw new Error(`ingest/sync running (phase=${health.ingest.phase}) -- aborting`);

  if (REVERT) {
    if (!APPLY) { console.log(`[revert dry-run] would deletePage('${JOURNAL_SLUG}') -> cascade-remove all episodic entries. Re-run with --apply --revert.`); return; }
    await rpc('deletePage', [JOURNAL_SLUG]);
    console.log(`[revert] deleted page '${JOURNAL_SLUG}' (timeline entries cascade-removed).`);
    return;
  }

  // Ensure the journal page exists (idempotent upsert only when absent, so we never clobber it).
  const existingPage = await rpc<any>('getPage', [JOURNAL_SLUG]).catch(() => null);
  if (!existingPage) {
    if (APPLY) {
      await rpc('putPage', [JOURNAL_SLUG, {
        type: 'journal',
        title: 'Jarvis Session Journal',
        compiled_truth: 'Episodic log of dated session decisions/events, backfilled from the dated memory corpus (one timeline entry per *_YYYY_MM_DD.md file). Query with getTimeline(after,before). Reverse the whole backfill with deletePage(jarvis-session-journal) -- CASCADE removes every entry.',
        timeline: '',
        frontmatter: { generated: true, producer: 'gbrain-episodic-backfill' },
      }]);
    } else {
      console.log(`[dry-run] would create journal page '${JOURNAL_SLUG}'`);
    }
  }

  // Existing episodic entries for O(1) idempotent dedup.
  const existing = new Set<string>();
  const prior = APPLY || existingPage
    ? await rpc<any[]>('getTimeline', [JOURNAL_SLUG, { limit: 100000 }]).catch(() => [])
    : [];
  for (const e of prior) existing.add(`${e.date}::${e.summary}`);

  // Walk the memory corpus for dated files.
  const files = readdirSync(MEMDIR).filter(f => f.endsWith('.md') && f !== 'MEMORY.md' && f !== 'MEMORY-archive.md');
  const planned: { date: string; source: string; summary: string; detail: string; slug: string }[] = [];
  for (const f of files) {
    const date = dateFromName(f);
    if (!date) continue;
    const slug = f.replace(/\.md$/, '');
    let raw = '';
    try { raw = readFileSync(join(MEMDIR, f), 'utf-8'); } catch { continue; }
    const { summary, detail } = summarize(raw, slug);
    const key = `${date}::${summary}`;
    if (existing.has(key)) continue;
    existing.add(key);
    planned.push({ date, source: SOURCE_PREFIX + slug, summary, detail, slug });
  }

  planned.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  let written = 0;
  if (APPLY) {
    for (const p of planned) {
      try { await rpc('addTimelineEntry', [JOURNAL_SLUG, { date: p.date, source: p.source, summary: p.summary, detail: p.detail }]); written++; }
      catch (e) { if (!JSON_MODE) console.error(`  skip ${p.slug}: ${(e as Error).message}`); }
    }
  }

  const summary = {
    mode: APPLY ? 'apply' : 'dry-run',
    memdir: MEMDIR,
    journal: JOURNAL_SLUG,
    dated_files_scanned: files.length,
    already_present: prior.length,
    new_entries: planned.length,
    written,
    date_range: planned.length ? { first: planned[0].date, last: planned[planned.length - 1].date } : null,
  };
  if (JSON_MODE) { console.log(JSON.stringify(summary, null, 2)); return; }
  console.log(`episodic-backfill (${summary.mode}): ${planned.length} new entries` + (APPLY ? ` (${written} written)` : ' (would write)') +
    ` from ${files.length} corpus files; ${prior.length} already present.`);
  if (planned.length) {
    console.log(`  date range: ${summary.date_range!.first} .. ${summary.date_range!.last}`);
    for (const p of planned.slice(0, 8)) console.log(`  ${p.date}  ${p.summary.slice(0, 90)}`);
    if (planned.length > 8) console.log(`  ... +${planned.length - 8} more`);
  }
}

main().catch(e => { console.error(`FAILED: ${e.message}`); process.exit(1); });

