def build_cache(golden):
    """Search each unique query ONCE (skip-gated) and cache (skipped, results). Sweeping the floor
    reuses these -- 10 searches, not 10*len(sweep) -- so we don't hammer the single-writer daemon.
    """
    cache = {}
    for case in golden.get("positives", []) + golden.get("negatives", []):
        q = case["query"]
        if q in cache:
            continue
        skipped = hook.should_skip(q)
        results = [] if skipped else hook.search(q)
        cache[q] = (skipped, results)
    return cache

