def _compute_max_dd(equity: np.ndarray) -> float:
    """Max drawdown as a positive percentage (0-100 scale)."""
    if len(equity) < 2:
        return 0.0
    peak = np.maximum.accumulate(equity)
    dd = (equity - peak) / peak
    return float(abs(dd.min()) * 100.0)


